export default [{"id":52,"question":"أحد الإخوة من الفلبين يسأل ويقول: من أساليب  تنصير المسلمين في الفلبين الآن تقديم المساعدات المادية والمعنوية من قبل القساوسة على إمام المسجد وجماعته على أن يسمحوا للقسيسين النصارى إلقاء محاضرة عن خليط من الإسلام والمسيحية، بدلًا من خطبة الجمعة وذلك أسبوعيًّا، و كيف نواجه هذا الأسلوب؟ أفيدونا جزاكم الله خيرًا.","title":"ما النصيحة لمواجهة جهود التنصير بالفلبين؟","answer":"الجواب: الواجب على المسؤولين عن المسلمين - العلماء وغيرهم - أن يحولوا بين هؤلاء وبين ما أرادوا، وأن يبذلوا المساعدة المستطاعة للمسلمين، وأن يَكْفُوهم الحاجة إلى عدوهم، وأن يحذروا مكائد الأعداء، وأن يحثوا المسلمين على الصبر والحرص على البعد عن أعدائهم والاختلاط بأعدائهم والسماع لتوجيهات أعدائهم؛ فإنهم يدعون إلى النار وأهل الإسلام يدعون إلى الجنة. فعلى المؤمن أن يصبر وأن يحتسب وأن يتصبر على ما قد يصيبه من ضعف وحاجة حتى يجد ما يسدّها، وعلى إخوانه المسلمين أن يواسوهم وأن يحسنوا إليهم وأن يتعاونوا في ذلك بكل ما يستطيعون ولو بالقليل؛ فإن القليل مع القليل يكون كثيرًا، إذا بذل هذا مستطاعه والآخر كذلك والآخر كذلك؛ تجمَّع الخير الكثير وانتفع به المحاويج من المسلمين واستغنوا به عن شر أعدائهم ومكائد أعدائهم الذين يتربصون بهم الدوائر، ويبذلون المال الذي يقودهم إلى النار، نسأل الله السلامة. ثم من المهمّات أن على رؤساء الأقليات الإسلامية وعلى أعيانهم أن يكتبوا لمن يرون فيه الخير، وأن يوضحوا حاجة إخوانهم الفقراء، وأن يستعينوا بمن حولهم من رؤساء المراكز الإسلامية والجمعيات الإسلامية؛ حتى يتم التعاون، لا يغفلوا، على الجميع أن يتعاونوا على البر والتقوى وعلى إيجاد المكاسب الطيبة التي تعينهم على طاعة الله في بلادهم، على أن يعتنوا بالمكاسب والصناعة التي تنفعهم بأي عمل ينفعهم؛ حتى يستغنوا عن الحاجة إلى أعدائهم، الرسول يقول عليه الصلاة والسلام في الحديث الصحيح: احرص على ما ينفعك واستعن بالله ولا تعجز رواه مسلم في الصحيح، فعلى المؤمن أن يبذل وسعه في طلب الرزق والحرص على طلب الرزق بالطرق الحلال؛ حتى يستغني عن الحاجة إلى أعداء الله.","link":"https://binbaz.org.sa/fatwas/2963/ما-النصيحة-لمواجهة-جهود-التنصير-بالفلبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0026.mp3","categories":["الدعوة والدعاة","قضايا معاصرة"]},{"id":58,"question":"سماحة الشيخ: يوجد عند طائفة من الناس نظرة غير متفائلة تجاه إخوانهم المستقيمين مما نتج عنه ابتعاد أولئك عن مجتمعات الصالحين، فما السبيل إلى إبعاد هذه الفجوة، وما موقف المستقيمين من هذه النظرة لهم؟","title":"حكم الجفاء والعنف في دعوة الناس","answer":"الجواب: الواجب على الملتزمين أن يتواضعوا وأن يتحروا الأسلوب الحسن والرفق بالناس لاسيما العامة، وأن يخاطبوهم بما يفهمون من الأساليب الواضحة اللينة، مع الرفق في كل الأمور، وألا يتكبروا وألا يستعملوا العنف في الكلام فإن هذا ينفّر من الحق ويبغّض الناس لأهل الحق، فينبغي للمؤمن، ولاسيما الداعية إلى الله وطالب العلم، أن يكون رفيقًا في كل أموره حليمًا متواضعًا في دعوته للناس وتعليمه الناس؛ حتى يقبلوا منه، يقول النبي عليه الصلاة والسلام: من يُحرم الرفق يُحرم الخير كله ويقول عليه الصلاة والسلام: عليكم بالرفق فإنه لا يكون في شيء إلا زانه ولا ينزع من شيء إلا شانه ويقول: يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا. فالتعاظم من الملتزم والتكبر على الناس لأنه هداه الله ووفقه لشيء جهلوه هذا من أسباب حرمانه، من أسباب عدم توفيقه، من أسباب ضلاله بعد الهدى، فالواجب التواضع لله وعدم التكبر على عباد الله وأن يكون في نصيحته وتعليمه وإرشاده متواضعًا حليمًا رفيقًا يخاطب الناس بما يعرفون، وأن يخاطبهم بالأساليب الحسنة اللينة الطيبة، هذا هو الذي ينبغي؛ حتى لا ينفّر عنه إخوانه، وحتى لا يكرهوا موعظته، وحتى لا يتباعدوا عن قرب. رزق الله الجميع التوفيق. س: فضيلة الشيخ: ينظر بعض الشباب الملتزم إلى إخوانه مما يلاحظ عليهم ارتكاب بعض المعاصي الظاهرة نظرة فيها كثير من الجفاء والبعد عن حكمة التوجيه والدعوة إلى الله بأسلوب الداعية الحكيم، فما توجيهكم لهؤلاء، أثابكم الله؟ الشيخ: تقدم الكلام في هذا وأن الواجب عليهم التواضع وأن يخاطبوا الناس بالخطاب الحسن والأسلوب الحسن، وأن يرفقوا، وأن يستعملوا الحلم في كل الأمور وألا يتكبروا على عباد الله؛ بل يجب عليهم يحمدوا الله وأن يشكروه الذي منّ عليهم بالعلم ووفقهم وهداهم فلا يتكبروا بذلك على إخوانهم، ولا تَشْمَخ أنوفهم على إخوانهم تكبرًا وتعاظمًا لأنهم فهموا ما لم يفهموا لا، كان النبي ﷺ في غاية التواضع يعلم الجاهل ويرفق بالجاهل ولا يعنف عليه ولا يشدد، وفيما وقع من أخلاقه ﷺ وما جرى عليه عبرة وعظة لأهل العلم، من ذلك مما جرى في قصة الرجل الذي بال في المسجد فهمّ به الناس فقال: دعوه فلما فرغ من بوله دعاه وقال: إن هذه المساجد لا يصلح فيها شيء من هذا القذر إنما بنيت لذكر الله والصلاة وقراءة القرآن ولم يعنّفه ولم يشدّد عليه، بل علمه ما جهل، ومن ذلك قصة الأعرابي الذي جذبه برداءه حتى أثّر في صفحة عنقه، وقال: أعطني من مال الله الذي عندك، فتبسّم عليه الصلاة والسلام وأمر له بعطاء، ولم يعنّفه عليه الصلاة والسلام، ومن ذلك قصة معاوية بن الحكم لما عطس رجل بقربه في الصلاة فشمته قال: يرحمك الله، فرأى الناس ينظرون إليه فاستنكر ذلك وقال: وأمياه ما شأنهم ينظرون إليّ؟! فجعلوا يسكّتونه، يوصونه بالتسكيت، فسكت، فلما صلى أتى النبي ﷺ فعلمه عليه الصلاة والسلام، قال: والله ما رأيت أحسن تعليمًا منه عليه الصلاة والسلام فما كهرني ولا ضربني ولا شتمني، إلى آخر ما قال، بل علمه وأحسن تعليمه عليه الصلاة والسلام، وبيّن له أن هذه الصلاة لا يصلح فيها شيء من كلام الناس، إنما هي التسبيح والتكبير وقراءة القرآن، فلم يشدّد عليه الصلاة والسلام بل علمه، وكذلك قصة المسيء في صلاته الذي صلى ولم يطمئن فدعاه النبي ﷺ وقال: ارجع فصل فإنك لم تصل ولم يقل: يا خبيث أو يا جاهل أو يا ضال، قال: ارجع فصل فإنك لم تصل فرجع فصلى كما صلى، ثم جاء فسلم على النبي ﷺ فرد عليه السلام وقال: ارجع فصل فإنك لم تصل، فرجع فصلى كما صلى ثم جاء فسلم على النبي ﷺ فرد عليه، ما هجره، رد عليه السلام، وقال: ارجع فصل فإنك لم تصل فقال: والذي بعثك بالحق نبيًّا لا أحسن غير هذا فعلمني فعلمه النبي ﷺ فقال: إذا قمت إلى الصلاة فأسبغ الوضوء ثم استقبل القبلة فكبّر ثم اقرأ ما تيسر معك من القرآن ثم اركع حتى تطمئن راكعًا... الحديث. فلم يشدّد عليه ولم يسبّه ولم يقل: يا جاهل أو يا فاجر أو يا خبيث، أو يا كذا من الألفاظ النابئة لا، بل علّمه وأحسن تعليمه عليه الصلاة والسلام، ففي هذه الوقائع وأشباهها عظة للداعية وذكرى؛ حتى يرفق بالناس، وحتى يستعمل الألفاظ الطيبة، وحتى يبتعد عن كل لفظ يؤذي الناس وينفّرهم من الحق، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/2969/حكم-الجفاء-والعنف-في-دعوة-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0032.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":93,"question":"أنا رجلٌ أقوم بالدعوة والإرشاد والأمر بالمعروف والنَّهي عن المنكر، وإنكار المنكرات على الناس، ولكن هناك مَن يتصدَّى لي ويقول: إنَّك تتدخل فيما لا يعنيك، وإنك تُثير فتنةً، فما الحكم في ذلك؟","title":"ما واجب كل مسلم في الدعوة وإنكار المنكر؟","answer":"الجواب: إذا كان عندك علمٌ وتدعو إلى الله على بصيرةٍ فلا تلتفت إلى مَن ثَبَّطك، فادعُ إلى الله، وعلِّم الناس، وَأْمُرْ بالمعروف، وانهَ عن المنكر، مع الحلم والصبر والاحتساب وطيب الكلام، كما قال الله جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ.. [التوبة:71]، وقال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ.. [آل عمران:110]، وقال سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ.. [النحل:125].\nفاستمر على ذلك ما دام عندك علمٌ، فاستقم على ذلك، ولا تلتفت إلى مَن ثبَّطك، لكن عليك بالحكمة، وعليك بـ: قال الله ورسوله، ووضع الأشياء في مواضعها، والحلم والصبر، وعدم العجلة في الأمور، وعليك بالرفق وطيب الكلام.","link":"https://binbaz.org.sa/fatwas/3108/ما-واجب-كل-مسلم-في-الدعوة-وانكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0070.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":129,"question":"سائلٌ يقول: وظيفتي وطبيعة عملي تستدعي مُخالطة جاليات غير مسلمة ومعاشرتهم، وقد نُفطر معًا في مقر العمل، وقد نبدأهم بالسلام أو التحية، فكيف نُحقق جانب الولاء والبراء مع هؤلاء؟","title":"حكم مخالطة الجاليات غير المسلمة","answer":"الجواب: عليك أن تنصحهم وتدعوهم إلى الله، وتُعاملهم بما تدعو الحاجةُ إليه: سؤالهم عن معاملة، إعطاؤهم معاملة يعملونها، ردّ السلام عليهم إذا سلَّموا هم، ولا تبدأهم أنت، وهكذا. أما اتِّخاذهم أصحابًا وأحبابًا ومُعاشرتهم كأنَّهم مسلمون فلا، ما يجوز هذا، لكن تُعاملهم بما تدعو الحاجة إليه في أنظمة الوظيفة: من معاملة تُعطى إياه، أو تُؤخذ منه، أو يُسأل عنها: أين ذهبت؟ أين جئت؟ ولا بأس أن يُقال: كيف أولادك؟ كيف حالك؟ ما هو ببدءٍ بالسلام، وإذا سلم تقول: وعليكم السلام.","link":"https://binbaz.org.sa/fatwas/3655/حكم-مخالطة-الجاليات-غير-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0118.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":164,"question":"ما رأيكم فيما يتعرض له المسلمون في سوريا من حربٍ إباديَّةٍ؟","title":"ما واجب المسلمين تجاه إخوانهم بسوريا؟","answer":"الجواب:\nقولنا فيها معروف؛ أن الواجب على الدول الإسلامية أن يُساعدوا المسلمين هناك، وأن يأخذوا على يد الدولة النُّصيرية في هذا الباب، وأن يُصلحوا بينهم وبين الشعب السوري بما يرفع النزاع ويحلّ الوئام بين الدولة والشعب على أساس من الكتاب والسنة، فإن الشعب المسلم لا يُرضيه إلا أن تخضع الدولةُ لدين الله، وأن تحكم شريعة الله، وأن تمنع ما حرَّم الله، هذا هو الذي يُرضي الشعب السوري: الإخوان المسلمين، وغيرهم من المسلمين، فالنزاع بينهم وبين الشعب المسلم الذي يغار لله ويُنكر المنكر.\nفالواجب على الدول الإسلامية وعلى المجاورين وعلى غيرهم أن يتَّقوا الله في ذلك، وأن يتوسَّطوا في الإصلاح بين هؤلاء حتى تخضع الدولةُ لحكم الله، وحتى تنفذ شرع الله، وحتى تقوم بما يلزم فيما يتعلق بالشعب: من أمره بالمعروف، ونهيه عن المنكر، وتحكيم الشرع فيه، هذا هو الذي به تزول الوحشة بينه وبين الشعب، والله المستعان.","link":"https://binbaz.org.sa/fatwas/3702/ما-واجب-المسلمين-تجاه-اخوانهم-بسوريا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0158.mp3","categories":["قضايا معاصرة"]},{"id":183,"question":"هذا يسأل عمَّا أصاب المسلمين اليوم من الذلِّ والهوان والفُرقة والاختلاف وطمع الأعداء بهم؟","title":"ما أسباب ذلة المسلمين وتفرُّقهم؟","answer":"الجواب: لا أعلم سببًا لهذه الذلة وهذا التَّفرق إلا عدم استقامتهم على دين الله، وعدم تحقيقهم لشريعة الله، وعدم اعتصامهم بحبل الله جميعًا، فإنَّ الله جلَّ وعلا وعد عباده المؤمنين المُستقيمين بالنصر والتأييد، قال جلَّ وعلا: وَلَيَنْصُرَنَّ اللَّهُ مَنْ يَنْصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ ۝ الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ [الحج:40- 41]، وقال : يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ [محمد:7]، وقال سبحانه: وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ الآية [النور:55]، فالله وعدهم بالنصر والاستخلاف إذا آمنوا وعملوا الصَّالحات، إذا نصروا دين الله، إذا أمروا بالمعروف ونهوا عن المنكر، ولا فعل بهم اليوم ما وقع؛ من الاختلاف، والتأخُّر عن نصر دين الله، والجهاد في سبيله، والأمر بالمعروف، والنَّهي عن المنكر.\nهذا هو السر في تأخُّر المسلمين وذلّهم، هو عدم اعتصامهم بحبل الله، وعدم التعاون على البر والتقوى، وعدم قيامهم بالواجب من الأمر بالمعروف والنَّهي عن المنكر، ونصر دين الله، وعلى حسب قيام مَن قام منهم بذلك حصل له بعضُ النصر، فدولتنا السعودية لما قامت ببعض الواجب حصل لها من النصر والخير والطُّمأنينة والأمن ما لم يحصل لغيرها، ولو أنها قامت بكل الواجب وعُنيت بكل الواجب لرأيتم من النصر والتَّأييد والعزة العظيمة والسَّعة الباهرة ما لا يخطر في البال، ولكن بسبب ما فرطنا فيه وبسبب نقصنا وتقصيرنا في بعض الأمور وبعض الواجب حصل ما حصل من النقص فيما عندنا.\nوهكذا الدول الأخرى؛ كل دولةٍ بحسب حالها، فكل دولةٍ عندها شيءٌ من خيرٍ، وشيءٌ من إيمانٍ، وشيءٌ من تقوى؛ يحصل لها بعضُ الخير، وكلما زاد شرُّها وفسادُها زاد بلاؤها، وزاد الفسادُ فيها، وزاد اختلال الأمن فيها، إلى غير ذلك؛ جزاءً وفاقًا: وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] .","link":"https://binbaz.org.sa/fatwas/3756/ما-اسباب-ذلة-المسلمين-وتفرقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0186.mp3","categories":["قضايا معاصرة"]},{"id":233,"question":"يقول بأنه أحد الطلبة في السكن الجامعي، ويقول بأنه يُعاني من بعض الطلاب الذين لا يُصلون، وعندما يحين وقتُ الصلاة يقعدون عند التلفاز، بحيث إننا نُصلي ونعود وهم في أماكنهم، يقول: فنرجو من الله ثم من سماحتكم أن تقترحوا حلًّا لهذه المشكلة.","title":"حكم من يسكن مع زملاء لا يصلون","answer":"الجواب: هذه مصيبةٌ عظيمةٌ، فإنَّ الطالب قدوةٌ لزملائه وغيرهم، والواجب أن يكون قمةً في الخير، وأن يكون قدوةً صالحةً لزملائه وغيرهم، والصلاة عمود الإسلام، وهي أعظم الفرائض بعد الشَّهادتين، فالواجب على طلبة العلم وعلى كل مسلمٍ العناية بالصلاة، والاهتمام بها، والحذر من التهاون بها، وعلى إخوانه وزملائه إذا رأوا منه منكرًا أن يُنكروا عليه، وأن ينصحوه، وأن يجتهدوا في استقامته، يقول الله جلَّ وعلا في كتابه المبين: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71].\nفالمؤمنون والمؤمنات أولياء يتناصحون، ليسوا بأعداء، بل أولياء يتناصحون، وينصح بعضُهم بعضًا، ويُحذِّر بعضُهم بعضًا من الباطل، لا يحسده، ولا يخونه، ولا يغشه، ولا يكذب عليه، ولا يشهد عليه بالزور، ولا يتركه على منكرٍ، بل يُعلّمه ويُوجهه إلى الخير، ويُنكر عليه المنكر.\nفالمؤمن يُنكر على أخيه وعلى أخته في الله، والمؤمنات كذلك تُنكر على أختها في الله وعلى أخيها في الله إذا رأت منه منكرًا.\nفعلى الطلبة أن يُنكر بعضُهم على بعضٍ إذا رأوا من زملائهم المنكر: من ترك الصلاة، أو التهاون بها، أو شرب المسكر، أو التدخين، أو إسبال الملابس، أو حلق اللحى، أو غير هذا مما يُنكر، فهكذا المؤمنون يتناصحون، ويأمرون بالمعروف، وينهون عن المنكر أينما كانوا: في الكلية، في المطعم، في الطريق، في المسجد، في السفر، في الإقامة، في الطائرة، في القطار، في السيارة، في كل مكانٍ، هكذا المؤمنون والمؤمنات أينما كانوا.\nوبهذا يصلح المجتمع، وبهذا يسلموا من غضب الله وعقابه، أما إذا تساكت الناسُ فقد أحلّوا بأنفسهم عقاب الله، في \"الصحيحين\" عن زينب بنت جحشٍ أم المؤمنين رضي الله عنها: أن النبيَّ عليه الصلاة والسلام دخل عليها ذات يومٍ وهو غضبان يقول: ويلٌ للعرب من شرٍّ قد اقترب، فُتح اليوم من ردم يأجوج ومأجوج مثل هذه وأشار بأصبعيه: الإبهام والوسطى، فقالت له زينب: يا رسول الله، أنهلك وفينا الصَّالحون؟ قال: نعم، إذا كثر الخبث، فبيَّن عليه الصلاة والسلام أنَّ الناس يهلكون إذا كثر فيهم الخبثُ، والخبث هو المُنكر والسعي..... في المعاصي، فإذا وُجد الخبثُ ولم يُنكر عمَّت العقوبة.\nوقال عليه الصلاة والسلام: إنَّ الناس إذا رأوا المنكر فلم يُغيروه أوشك أن يعمَّهم الله بعقابه خرجه الإمام أحمد وغيره بإسنادٍ صحيحٍ من حديث الصديق .\nفالواجب على الأساتذة والموظفين والطلبة -على الجميع- أن يأمروا بالمعروف، وأن ينهوا عن المنكر، هذا هو الواجب على الجميع، لا يخص واحدًا دون واحدٍ، ولا يجوز التواكل، لكن بالحكمة، بالكلام الطيب، بالأسلوب الحسن، بالمُواظبة، فالأستاذ والمدرسة والطالبة والموظفة والموظف والطالب كلهم شُركاء في هذا الأمر، فعلى الجميع أن يأمر بالمعروف، وأن ينهى عن المنكر، وعدم الغفلة، وعدم التساهل؛ حتى يكونوا قدوةً صالحةً لغيرهم في هذا الخير العظيم، وحتى ينفع بعضُهم بعضًا، وحتى يأخذ بعضُهم على يد بعضٍ، وحتى يسود الخيرُ، وحتى يقلَّ الشرُّ.\nهكذا أمر الرسولُ ﷺ، بل هكذا أمر الله عزَّ وجل، وبهذا تصلح المُجتمعات، ويأمن المجتمع من عقاب الله سبحانه وتعالى، ومتى أخلَّ الناسُ بهذا الأمر فهم على خطرٍ عظيمٍ، ولا حول ولا قوة إلا بالله، قال الله عزَّ وجل: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ  ۝  كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:78- 79]، وأخبر أنَّهم لُعنوا على لسان أنبيائهم بسبب هذا: ذَلِكَ بِمَا عَصَوْا يعني: بسبب عصيانهم واعتدائهم: ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ، ثم فسَّر ذلك بقوله: كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ، فعلى المؤمن وعلى المؤمنة الحذر.","link":"https://binbaz.org.sa/fatwas/4091/حكم-من-يسكن-مع-زملاء-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0243.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":260,"question":"صاحب السَّماحة، إني أحبُّكم في الله، ما رأي سماحتكم فيمَن يتصدَّى للدعوة إلى الله بغير عُدَّةٍ علميةٍ ولا خبرةٍ؟ وهل من الأمانة نحو الدَّعوة أن يقع هذا؟ وما الطريق الصَّحيح الذي ترونه لإعداد الدُّعاة والقيام بأمانة الدعوة، أثابكم الله؟","title":"حكم من يتصدَّر للدَّعوة بدون علمٍ ولا خبرةٍ","answer":"الجواب: أولًا: أحبَّك الله الذي أحببتنا له، نسأل الله أن يجعلنا جميعًا مُتحابين في جلاله، فقد قال النبيُّ عليه الصلاة والسلام: يقول الله  يوم القيامة: أين المُتحابُّون بجلالي؟ اليوم أُظلّهم في ظلِّي يوم لا ظلَّ إلا ظلي، ويقول جلَّ وعلا: وجبت محبَّتي للمُتحابين فيَّ، والمُتباذلين فيَّ، والمُتجالسين فيَّ، والمُتزاورين فيَّ، نسأل الله أن يجعلنا وإيَّاكم منهم.\nوأما ما يتعلق بالدعوة على غير علمٍ: فهذا لا يجوز، فالواجب على الدَّاعي أن يتأهَّل أولًا، وأن يعدَّ العُدَّة لدعوته، حتى يكون على علمٍ وبصيرةٍ بما يدعو إليه، وبما ينهى عنه، قال الله : قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، قال لنبيه: قُلْ يعني: قل يا أيها الرسول للناس، هَذِهِ سَبِيلِي يعني: هذه طريقي، أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ يعني: على علمٍ، فلا بد من العلم.\nويقول الله : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ [النحل:125]، والحكمة هي العلم: قال الله، وقال الرسول، أما أن يتصدَّى للدعوة على جهلٍ وعلى غير بصيرةٍ فهذا لا يجوز، بل يُفسد أكثر مما يُصلح، يقول الله سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [الأعراف:33]، فجعل القولَ عليه بغير علمٍ فوق مرتبة الشرك؛ لما يترتب على هذا من الفساد العظيم.\nوقال سبحانه: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [البقرة:168- 169]، فبيَّن سبحانه أنَّ الشيطان يأمر بالسوء والفحشاء، وأن نقول على الله ما لا نعلم.\nفالقول على الله بغير علمٍ هو مما يأمر به الشيطان، ويدعو إليه؛ لعلمه بأنه يترتب عليه من الفساد ما لا يُحصيه إلا الله ، فالدَّاعي الجاهل يُنَفِّر عن الدين، ويُحلّ الحرام، ويُحرّم الحلال، ويدعو إلى ما لا يجوز؛ لجهله، قال سبحانه: وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء:36]، فالواجب على الدَّاعي إلى الله أن يتَّقي ربَّه، وأن يعد العدَّة قبل ذلك.\nوطريق العلم أن يحضر حلقات العلم، وأن يعتني بطلب العلم، وأن يُعنى بكتاب الله: قراءةً وتدبُّرًا وتعقُّلًا وتفهُّمًا، ويعتني بالسنة -سنة الرسول ﷺ- ويحفظ ما تيسر منها، مع الكتاب العزيز، ويجتهد في فهم الكتاب والسنة، ويسأل أهل العلم عمَّا أشكل عليه، ثم إذا أحسَّ من نفسه أنه تأهَّل لهذا الأمر؛ لأنه كثر علمه بما أمر الله، وبما نهى الله، وعرف ما أوجب الله وما حرَّم الله، كان على هدى في ذلك وعلى بصيرةٍ؛ فيدعو إلى ما أمر الله به ورسوله، وينهى عمَّا نهى الله عنه ورسوله.\nهذا هو الواجب على مَن يريد الدعوة إلى الله ومَن يتصدر لذلك: أن يُعنى بالعلم، والعلم ليس بالتَّمني، يحتاج إلى جهودٍ، إلى صبرٍ، وبهذا يقول ﷺ: مَن سلك طريقًا يلتمس فيه علمًا سهَّل الله له به طريقًا إلى الجنة، ويقول ﷺ: مَن يُرد الله به خيرًا يُفقهه في الدين متفقٌ على صحَّته، هذا دليلٌ على أن الله سبحانه إذا أراد بالعبد خيرًا فقهه في الدين، وجعله يتبصَّر ويتعلم ويعتني بما أوجب الله عليه، وما حرَّم عليه، حتى يعبد ربَّه على بصيرةٍ، ومفهومه أنَّ مَن لم يُوفَّق في الفقه في الدين معناه: أن الله ما أراد به خيرًا، فالخطر عظيم في الإعراض والجهل وعدم المُبالاة.","link":"https://binbaz.org.sa/fatwas/4254/حكم-من-يتصدر-للدعوة-بدون-علم-ولا-خبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0305.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":306,"question":"نحن نحبكم في الله تعالى، لا يخفى عليكم ذلك الانتشار الكبير لأفلام الفيديو، وفشوها بين المسلمين في أسواقهم وبيوتهم، وهي لا شكَّ لها أثرٌ كبيرٌ على عقائد المسلمين وقيمهم وأخلاقهم. ما حكم مشاهدة هذه الأفلام؟ وما حكم بيعها وشرائها وتأجير محلاتها؟ وماذا يجب على العلماء والناس تجاهها؟","title":"حكم الفيديوهات التي تهدم العقيدة والأخلاق","answer":"الجواب: الفيديو فيه تفصيل: إذا كان يُباع فيه ما يضرُّ الأخلاق ويضرُّ الدين فهو مُحرَّمٌ، وقد عمّمت الدولةُ على منع ذلك، وكتب إليها مجلس هيئة كبار العلماء، وعمّدت الجهة المُختصة بمنع جميع الأفلام الخبيثة. فالذي يعلم شيئًا خبيثًا يجب عليه أن يُنكر ذلك، ولا يجوز بيعه ولا شراؤه، وعلى المسلمين أن يتناصحوا، وأن يُبلِّغوا عمَّن يبيع الأفلام الخبيثة، وأن يُنكروا عليه؛ حتى يحصل التَّعاون على البرِّ والتَّقوى والتَّواصي بالحقِّ، هذا دين الله، لا بدّ فيه من التَّعاون.\nفالأفلام التي تنشر الرذائل، وتُصور اختلاط النساء بالرجال، أو الرجل على زوجته، أو الرجل مع الرجل على اللواط، أو ما أشبه ذلك من أنواع الفساد، هذا منكرٌ عظيمٌ، لا يجوز بيعه، ولا التَّصرف فيه، ولا تصويره، بل يجب إنكاره وتمزيقه، ويجب الرفع عن صاحبه، وبيان حاله، حتى تزول هذه الشرور، وحتى يسلم المسلمون من شرِّها، ولا يجوز بيعها بالكلية ولا شراؤها -نعوذ بالله من ذلك.\nنسأل الله أن يُوفق الدولة للقيام بما يجب نحوها على الوجه الأكمل.","link":"https://binbaz.org.sa/fatwas/4309/حكم-الفيديوهات-التي-تهدم-العقيدة-والاخلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0356.mp3","categories":["قضايا معاصرة"]},{"id":363,"question":"لي جيرانٌ لا يُؤدون الصلاة في المسجد، وأنا أحضر مجالسهم وأُخالطهم كثيرًا، حتى على ولائمهم، وذلك من باب النَّصيحة، وأذكر حديثًا أو مناقشة موضوع بيني وبينهم، هل يجوز لي ذلك؟ علمًا بأنَّ بعض المجالس يُشرب بها الدخان، ويكثر فيها الكلام الذي لا فائدةَ فيه، وأنا هدفي من مُخالطتهم النَّصيحة؟","title":"ما الواجب تجاه الجيران الذين لايصلون؟","answer":"الجواب: الواجب على مَن كان له جيرانٌ لا يُصلون أو يتعاطون المسكر أو نحو ذلك من المعاصي: أن ينصحهم، وأن يُحرضهم على تقوى الله، فإنَّ الجار له حقٌّ على جاره، تقدَّم قول النبي ﷺ: مَن كان يؤمن بالله واليوم الآخر فليُحْسِن إلى جاره، فالجار له حقٌّ، والنَّصيحة بالحقِّ تنصحه، وتأمره بالمعروف، وتنهاه عن المنكر، وتجتهد في ذلك، فإذا أصرَّ وأبى ينبغي أن تُقاطعه، ينبغي أن تهجره ولا تأتي إلى دعوته ووليمته، ولا تتخذه جليسًا، وهكذا الجماعة من الجيران إذا لم يقبلوا النَّصيحة وأصرُّوا على ترك الصلاة في المساجد، فهذه علامة النِّفاق، وهذا دليل النفاق، فينبغي هجرهم، وعدم مُجالستهم، وعدم إجابة دعوتهم حتى يستجيبوا لداعي الحقِّ.\nوإذا نصحتهم فالأوْلى والأفضل أن يكون معك غيرُك، يكون معك بعض جيرانك الطيبين، تذهب إليهم ومعك اثنان، ثلاثة، أربعة، تنصحونهم؛ لأنَّ هذا أقرب إلى التأثير، إذا كانت النصيحة من جماعةٍ أقرب إلى التَّأديب للمنصوحين، أما أن تستمر معهم على باطلهم فلا يصلح هذا.\nوقد جاء في حديث ابن مسعودٍ عن النبي ﷺ أنه قال: لما وقعت بنو إسرائيل في المعاصي نهتهم علماؤهم، فلم ينتهوا، فجالسوهم، وواكلوهم، وشاربوهم، فلمَّا رأى الله ذلك منهم ضرب قلوبَ بعضهم ببعضٍ، ثم لعنهم على لسان دواد وعيسى ابن مريم، وأنزل في هذا قوله سبحانه: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ۝ كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:78- 79].\nفالواجب على المسلمين التناصح، والتَّعاون على الخير، والتآمر بالمعروف، والتناهي عن المنكر، وإذا رأوا من قريبهم أو جارهم الإصرار على المعصية وعدم الاستجابة تركوه، ولم يتَّخذوه جليسًا، بل هجروه حتى يرعوي.","link":"https://binbaz.org.sa/fatwas/4559/ما-الواجب-تجاه-الجيران-الذين-لايصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0418.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":370,"question":"نرجو من سماحتكم أن تُوضح لنا كيف تكون العلاقةُ والمعاملةُ بين الموظف المسلم وبين الموظفين (من غير المسلمين)، إذا كان هذا الموظفُ المسلم وهؤلاء يعملون في نفس العمل، وفي نفس المؤسسة الحكومية، حيث إن هذا المطلوب منه: أن يتعلم منهم، أن يتعلم منهم ليُرشد مثلهم، وليوجد العمل على الوجه المطلوب؟","title":"ما كيفية معاملة زملاء العمل غير المسلمين؟","answer":"الجواب: الواجب على المؤمن إذا بُلي بهؤلاء أن يتميز بإيمانه، وأن يكون داعيةً إلى الخير، ومُرشدًا إلى الخير، وحريصًا على إيصال الخير إلى مَن حوله من المسلمين وغيرهم، فإذا بُلي بكفرةٍ يعملون معه؛ حرص على نصيحتهم، وعلى دعوتهم إلى الله ، وعلى بيان حقيقة الإسلام لهم بفعله وقوله؛ لعله يكون سببًا لهدايتهم، كما قال النبيُّ عليه الصلاة والسلام: مَن دلَّ على خيرٍ فله مثل أجر فاعله، مَن دعا إلى هُدًى كان له مثل أجور مَن تبعه، لا ينقص ذلك من أجورهم شيئًا، فيكون محافظًا على دينه، قدوةً حسنةً لزملائه في الأمانة، في أداء الأمانة، في النصح، في العمل، بعدم التَّساهل في ذلك، في الإكثار من ذكر الله، والمحافظة على ما أوجب الله عليه؛ حتى يقتدي به مَن حوله من الزملاء من مسلم وكافرٍ.\nوأن يحذر أن يغترَّ بما يُلقون من شُبَهٍ، فليحذر ذلك غاية الحذر، ويكون هو الذي يدعو، وهو الذي يُوَجِّه، وهو الذي يُرشد، ولا مانع من أن يستفيد من ذلك الكافر في طبٍّ أو هندسةٍ أو غير ذلك مما قد يطلبه هذا العامل، مع حذره، ومع ابتعاده عن أسباب الخطر، ومهما أمكن أن يكون في مؤسسةٍ أو دائرةٍ سليمةٍ من أولئك، بعيدةٍ عن الخطر، فهو خيرٌ له إن استطاع، ومتى بُلي بهذا الشيء فليحذر، وليتَّقِ الله، وليكن داعيةً إلى الخير، مُوَجِّهًا إلى الخير، بعيدًا عن خطر المقاربة لهؤلاء والاتِّصال بهم.","link":"https://binbaz.org.sa/fatwas/4625/ما-كيفية-معاملة-زملاء-العمل-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0425.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":427,"question":"السلام عليكم ورحمة الله وبركاته، وبعد: ما سبب هذا البعد الشَّاسع بين النظرية والتَّطبيق في العالم الإسلامي، وآثار مثل هذا؟","title":"ما سبب البُعد بين النظرية والعمل في الأمة؟","answer":"الجواب: الظاهر -والله أعلم- أنَّ سبب ذلك: الإعراض والغفلة، فإن أكثر الخلق غافلٌ عمَّا خُلِقَ له. ومع ذلك: قلَّة المنبه، وقلَّة الداعي، وقلَّة المُبَصِّر والمُوَجِّه، ولهذا اتَّسعت الشّقَّة، وعظمت الفُرقة بين الناس، واتسع نطاقها؛ لكثرة المشاغل عن تدبُّر ما خُلق له العبد، ولكثرة المُعينين على أسباب الغفلة، ولقلة الموجّهين والمرشدين، فلهذا اتسعت الشقة بين النظرية والعمل.","link":"https://binbaz.org.sa/fatwas/4851/ما-سبب-البعد-بين-النظرية-والعمل-في-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0485.mp3","categories":["قضايا معاصرة"]},{"id":428,"question":"سماحة الشيخ، أخبرك بأني أحبّك في الله، سماحة الشيخ، مَن هم الذين يجب عليهم الأمر بالمعروف والنَّهي عن المنكر؟ وما درجات الأمر بالمعروف والنهي عن المنكر؟ مع أمثلةٍ في هذا الزمان.","title":"ما منزلة الأمر بالمعروف وعلى من يجب؟","answer":"الجوب: أما المحبَّة فنقول: أحبَّك الله الذي أحببتنا له، ونسأل الله أن يجعلنا جميعًا من المتحابين في جلاله، وأن يحشرنا مع أولئك الأخيار، يقول النبيُّ ﷺ: يقول الله  يوم القيامة: أين المتحابّون بجلالي؟ اليوم أظلّهم في ظلي يوم لا ظلَّ إلا ظلي أخرجه مسلم في \"الصحيح\"، وفي \"الصحيحين\" من حديث أبي هريرة: سبعة يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله منهم: رجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، وفي \"موطأ مالك\" بإسنادٍ جيدٍ عن النبي ﷺ قال: وجبت محبتي للمُتزاورين في، والمتجالسين فيَّ، والمتحابّين في، والمتباذلين في، جعلنا الله وإياكم منهم.\nأما ما يتعلق بالأمر بالمعروف والنهي عن المنكر: فهذا له شأنٌ عظيمٌ، وقد سمعتم بعض الشيء في هذا، فالله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ومن خصال المؤمن ومن صفاته الواجبة؛ لأنَّ المذكور في الآية الصفة الواجبة، فمن صفاته الواجبة وفرائض الله عليه أنه يأمر بالمعروف وينهى عن المنكر، هذا أمرٌ لازمٌ لكل مؤمنٍ، ليس خاصًّا بأحدٍ، وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]، فجعل الأمة كذلك كلها، ثم قدَّم الأمر والنَّهي، قدَّمه على الإيمان.\nهذا يدل على العناية والاهتمام، وعظم المنزلة، الإيمان هو أصل الدين، وأساس الملة، ومع هذا قدَّم عليه -وهو جزء منه- الأمر بالمعروف والنَّهي عن المنكر، شعبة من الإيمان، شعبة من شعب الإيمان، لكن لعظم الأمر وشدَّة الضَّرورة إليه قُدِّم، كما قُدِّم في آية براءة: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ، ثم قال: وَيُقِيمُونَ الصَّلَاةَ [التوبة:71]، فقدَّمه على الصلاة لعظم الأمر وشدة الضَّرورة إلى هذا الواجب العظيم، الذي به صلاح الناس، وردعهم عن الباطل، وإلزامهم بالحقِّ، والأخذ على أيدي السُّفهاء.\nولهذا تقدَّم لكم في الحديث يقول ﷺ: إن الناس إذا رأوا المنكر فلم يُغيروه أوشك أن يعمَّهم الله بعقابه، وفي اللفظ الآخر: يقول ﷺ: يقول الله : مروا بالمعروف، وانهوا عن المنكر قبل أن تدعوني فلا أستجيب لكم، وقبل أن تسألوني فلا أُعطيكم، وقبل أن تستنصروني فلا أنصركم، وفي اللفظ الآخر: لتأمرنَّ بالمعروف، ولتنهونَّ عن المنكر، أو ليوشكنَّ الله أن يُرسل لكم عقابًا من عنده -أو قال: يُنزل عليكم عقابًا من عنده- ثم تدعونه فلا يستجيب لكم.\nوفي حديث ابن مسعودٍ لما ذكر النبيُّ ﷺ قصة بني إسرائيل وأسباب النَّقص الذي دخل عليهم قال: أول ما بدأ النقص في بني إسرائيل أن الرجل منهم كان إذا رأى من الرجل المنكر نهاه عنه وقال: يا هذا، اتَّقِ الله، ثم لا يمنعه ذلك بعد ذلك أن يكون أكيلَه وقعيدَه وشريبَه، فلما رأى الله ذلك منهم ضرب بقلوب بعضهم على بعضٍ، ثم لعنهم، فقال عليه الصلاة والسلام: والذي نفسي بيده، لتأمرنَّ بالمعروف، ولتنهونَّ عن المنكر، ولتأخذنَّ على يد السَّفيه -وفي روايةٍ: على يد الظالم- ثم لتأطُرنَّه على الحقِّ أطرًا -أو قال: تقصرونه على الحقِّ قصرًا- أو ليضربنَّ الله بقلوب بعضكم على بعضٍ، ثم يلعنكم كما لعنهم نسأل الله السلامة.\nفالواجب هو الأمر بالمعروف، والنهي عن المنكر على العموم، لكنه مراتب ثلاثة بيَّنها النبيُّ ﷺ، فقال ﷺ: مَن رأى منكم منكرًا فليُغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان.\nويجب على الدولة الإسلامية أن تُقيم طائفةً من الناس في كل بلدٍ لهذا الأمر العظيم، حتى تهتم به، وحتى تُعنى به؛ لقوله سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، فهذه الأمة وهذه الطائفة تكون عليها مسؤولية كبرى، ولكنها لا تضع المسؤولية على غيرها، ولا تُلقي المسؤولية على غيرها، بل يبقى الغيرُ عليه أيضًا مسؤولية إذا رأى المنكر لا يقول: هذا على غيري، إذا رآه ولم تُنكره الهيئة المعينة، أو لم يبلغها، وبلغه هو أنكره، أو رفع إليها لتُنكر، المقصود التعاون على إزالة المنكر، وعلى إقامة المعروف.","link":"https://binbaz.org.sa/fatwas/4852/ما-منزلة-الامر-بالمعروف-وعلى-من-يجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0486.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":429,"question":"إنه كما نعرف قد كثرت المُنكرات والمفاسد، وانتشر الخبث في البر والبحر، فهل على المسلم أن يُنكر كلَّ ما يرى من المفاسد أم ماذا عليه؟","title":"هل يجب على المؤمن إنكار كل منكر يراه؟","answer":"الجواب: الواجب على المؤمن أن يُنكر، وإنما جاءت المصيبة العظيمة من التَّساهل، وهذا يقول: هذا على غيري، وهذا يحقر نفسه ولا يرى أنه أهلًا لأن يُنكر، وهذا يخاف أن يُقابَل بما لا ينبغي، وهذه مصيبة عظيمة.\nالرسل عليهم الصلاة والسلام ما خافوا، بذلوا المستطاع، مع أنهم استهزأ بهم الناس، وسخروا بهم، وآذوهم، بل قُتِل بعضُهم، كما سمعت في القرآن: وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ [آل عمران:21]، في آيات، فلم تمنعهم مخافة الناس من أداء الواجب.\nفالواجب على أهل العلم وعلى المؤمنين التأسِّي بهم، وألا يمنعهم من ذلك خوف الناس، أو قول بعض الناس: عليك بنفسك، اشتغل بنفسك، أو السخرية منه، أو غير هذا مما يفعله الجهلةُ والسُّفهاء، لا، لا يهمّك هذا، اتَّقِ الله، واعمل، فإن قُبِلَ منك فهذا المطلوب، وإن لم يُقبل منك برئت الذمةُ.\nوأنتم تعلمون ما جرى للنبي ﷺ في مكة، ولم يمنعه هذا من الدَّعوة إلى الله، وأُوذي، وهكذا المؤمنون في مكة، وهكذا في كل بلادٍ من حين بعث الله نبيه إلى يومنا هذا، بل من حين نزل آدم في الأرض، فالبلاء حاصلٌ، وقد قصَّ الله علينا ما جرى بين ابنيه: قابيل وهابيل، حتى قتل أحدُهما الآخر.\nفالأمر موجودٌ من عهد آدم إلى يومنا هذا، لا بدّ من إنكار المنكر، ولا بدّ من الصبر، يقول الله عن لقمان يقول لابنه: يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ [لقمان:17]، والله يقول في كتابه العظيم: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46]، ويقول عمر : \"وجدنا خير عيشنا بالصبر\"، ويقول عليٌّ : \"الصبر من الإيمان بمنزلة الرأس من الجسد\"، ثم رفع صوته فقال: \"ألا لا إيمان لمن لا صبرَ له\" يعني: لا إيمان كامل، مَن لا يصبر؛ ضعف إيمانه، ووقع في أغلاطٍ.\nومن ذلك مسألة الأمر بالمعروف والنَّهي عن المنكر: في بيتك، في الطريق، حسب الطاقة، إن سمعت الغناء أنكرته، إن رأيت تهاونًا بالصلاة أنكرته، إن رأيت مَن يحلق لحيته أنكرتَ عليه بالحكمة، إن رأيت من يُسبل ثيابه أنكرت عليه، إن رأيتَ مَن يشرب الخمر أو يُدخن أنكرتَ عليه، إن رأيتَ مَن يعقّ والديه أو أحدهما أنكرتَ عليه، وهكذا كل معصيةٍ تعرفها أنها معصية، عندك الدليل، لا تأمر ولا تنهى إلا عن علمٍ، عن بصيرةٍ، فإذا تكلمت عن بصيرةٍ فأنت على خيرٍ، حتى ولو رُدَّ عليك، حتى ولو استُهزئ بك، حتى لو ضُربت أنت، هذا خيرٌ لك؛ أسوة بالأنبياء والأخيار.","link":"https://binbaz.org.sa/fatwas/4853/هل-يجب-على-المومن-انكار-كل-منكر-يراه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0487.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":430,"question":"ما مدى حدود واجب الفرد في مجال الحِسْبة؟ هل هي فرض عينٍ لكل فردٍ؟","title":"هل الحِسْبة فرض على كل مسلم؟","answer":"الجواب: كما تقدم: فرض، فرض، فرض على كلِّ واحدٍ إذا لم يوجد مَن يقوم مقامه، أما إذا وُجد مَن يقوم مقامه صارت في حقِّه سُنةً، لكن أنت في قريةٍ، أو في حيٍّ من الأحياء، أو في قبيلةٍ ما عندك أحدٌ يُنكر المنكر، أنت رأيت المنكر بنفسك، عليك أن تُنكر المنكر حسب الطاقة: إما باليد، أو باللسان، حسب الطاقة، أقل شيءٍ القلبُ، إذا خِفْتَ الضرب والقتل كفى القلب، وإلا فالواجب اليد كالحِسْبة، رجل الحِسْبة حسب التعليمات التي لديه، في الرجل مع أولاده حسب الطاقة، مع زوجته حسب الطاقة، أمير القرية في بلده، في قريته، في قبيلته شيخ القبيلة حسب طاقته، وهكذا كل بحسبه، أما أن تمر بالمنكر وتقول: هذا على الهيئة، الهيئة ما سوّت شيئًا، ولا تعلمه أيضًا، ما هو في جهتها، ولا في حيِّها، مثلًا: ما عندك مركز، أو عندك مركز وغفل، أنت رأيت المنكر: إما أن تُنكر المنكر، وإما أن ترفعه إلى مَن يُنكره إذا عجزت وتقول: جرى كذا، وجرى كذا من المنكرات الظَّاهرة.\nومن هذا ما يتعلق بالصَّلوات: كثير من الناس يعرفون جيرانهم لا يُصلون في مسجدهم، ولا يقولون لهم: لماذا؟ أو يزورونهم، يروح اثنان أو ثلاثة، لا تروح وحدك، وحدك قد يُستهان بك، لكن انظر مَن يتيسر معك من الإخوان: اثنين، ثلاثة، تزورونه، أو في الطريق تُوقفونه: يا فلان، يا عبدالله، اتَّقِ الله، ما نُشاهدك -ما نشوفك- في المسجد، أو نسمع صوت المزامير والأغاني في بيتك، وأنتم جيرانه تسمعونه، تقولون له بالكلام الطيب، وتنصحونه، ولعله يستفيد، فإن لم يستجب في المرة الأولى استجاب في الثانية أو في الثالثة أو في الرابعة، أو ترفعون أمره بعد الإعْذار إلى مَن يقوم عليه، وهكذا، فالغفلة هي المصيبة، والإعراض هو المصيبة.","link":"https://binbaz.org.sa/fatwas/4854/هل-الحسبة-فرض-على-كل-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0488.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":431,"question":"ما رأي سماحتكم في الخَيِّرين الذين يدعون الناسَ إلى السُّنة دون أن يُراعوا مقاصد السنة وأسلوب الحكمة وأصول الدعوة إليها، فيكون مردود دعوتهم عكسيًّا، وهم يريدون الخير إن شاء الله؟","title":"ما أهمية وكيفية تحري الحكمة في الدعوة؟","answer":"الجواب: الواجب تحرِّي الحقّ.\nس: حبَّذا لو ذكَّرتُموهم بكلمةٍ جامعةٍ في هذا، بارك الله فيكم.\nالشيخ: الواجب على الدَّاعي إلى الله والآمر والنَّاهي أن يتحرى الوسائل في الإقناع؛ لأن المقصود ما هو أنك قلت وأمرت، المقصود الفائدة، المقصود الحرص على أن يُقبل منك، وعلى أن تنتفع وتنفع. فمن ذلك: الأسلوب الحسن الطيب اللّين، وعدم الاكفهرار. ومن ذلك: أن تكون معك جماعةٌ، ما هو وحدك، قد يحقرونك وحدك، ولكن إن كان معك إخوانٌ لك كان أقربَ إلى النجاح، وأقرب إلى أن يُصغي ويحترم.\nومن ذلك: أن تُعنى بالمسائل الكبيرة قبل الصغيرة: مَن يترك الصلاة، تُعنى بأمر الصلاة قبل كل شيءٍ، مَن يسبّ الدين أو يستهزئ، تُعنى بهذا الأمر؛ لأنَّ هذه ردَّة، تُعنى بهذه الأمور، وتجتهد أنت وإخوانك معه، لعلَّ الله يهديه على يديك، مع الصبر.\nثم: العناية بألا تُنكر منكرًا يتولد عنه ما هو أنكر، يتحرى في الإنكار، ينظر إذا كان هذا الشخص الإنكار عليه يُولّد منكرًا أكبر، وأنت تعرف ذلك؛ فدعه حتى يتيسر الطريق الموصل إلى ألا يكون هذا الإنكار يُحدث منكرًا أكبر. فإن الإنكار تترتب عليه أمور: تارةً يتولد عنه إنكار المنكر وزواله، وهذا واجب. وتارةً يتولد عنه خفَّة المنكر وقلَّته، وهذا واجبٌ. وتارة يتولد عنه وجود منكر أكبر؛ فلا، قال الله تعالى: وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ [الأنعام:108].\nذكر بعضُ أصحاب الشيخ تقي الدين ابن تيمية رحمه الله في وقت التتار في الشام أنهم مرُّوا على أناسٍ يشربون الخمر من التتار، فقال بعضُ أصحاب الشيخ: دعنا ننكر عليهم، قال: لا، لا تُنكر عليهم يقومون يقتلون الناس، هذا لو قاموا إلى الأسواق قتلوا الناسَ، خلّهم في بلائهم أسهل من القتل، أسهل من قتلهم الناس.\nفالمقصود: مراعاة الأمور التي يُخشى منها ما هو أكبر، فطالب العلم والمؤمن البصير يظهر له ما يقتضي الحال؛ إذا تأمَّل يظهر له هل هذا المنكر يزول أو يعقبه ما هو شرٌّ منه أو أخفَّ منه، ينظر ويتأمل، ولا يعجل.\nوقد بسط ابنُ القيم رحمه الله الكلامَ في هذا في مواضع من كتابه \"إعلام الموقعين\"، وهو كتابٌ جيدٌ جديرٌ بالعناية.\nثم مما ينبغي أن يُذكر أيضًا: كثرة الجماعات، وتنوع الجماعات، واختلاف الأساليب، واختلاف الأهداف، يجب على الجماعات الإسلامية كلها، سواء كانت تُسمَّى: سلفية، أو جمعية أنصار السنة، أو الإخوان المسلمين، أو التبليغ، أو غير ذلك من الأسماء، يجب أن يتعاونوا كلّهم في طريق الحقِّ، وأن يكون بينهم من المودة والمحبَّة ما يقتضي إنكار المنكر، والدعوة إلى الخير، وألا يكون بينهم وحشةٌ، بل يجب أن يكونوا متعاونين، ويكون الهدف واحدًا، وهو إقامة أمر الله في أرض الله، والقضاء على المنكرات، وأن يهتموا بالعقيدة قبل كل شيءٍ؛ لأن العقيدة هي رأس المال، وهي أساس السعادة، وأساس الملة، وليحذروا أن يكون بينهم تشاحن، أو أن يقصد أحدُهم القضاء على الآخر، لا، بل يجب أن يكون بينهم التعاون والتواصي بالحقِّ، وأن تكون الأهدافُ صالحةً، هي إقامة أمر الله في أرض الله؛ لتقليل المنكر، ولتكثير الخير، ولتبصير الناس.\nولا يضرّ تنوع الأسماء، المهم العمل، لو كانت الأسماء عشرة أسماء، أو مئة اسم، لكن إذا اتَّحدت الأهدافُ، واتَّحدت الجهود، وتضافرت الجهود على الخير، وصار الهدفُ واحدًا، وهو إقامة شرع الله، وإقامة أمر الله، والقضاء على المنكرات، فلا يضرّ تنوع الأسماء، لكن المصيبة أن تكون كل طائفةٍ ضد الأخرى، وتسبّها، أو تلومها، أو تُحب القضاء عليها، ما يصلح هذا، لا يجوز هذا، هذا منكرٌ.\nيجب على الجماعات الإسلامية بأي اسمٍ كانت: باسم أنصار السنة، باسم الإخوان المسلمين، باسم الجماعة الإسلامية، باسم جماعة التبليغ، باسم جماعة كذا، أي اسمٍ كان ما دام الهدف إسلاميًّا، والمقصود إسلاميًّا؛ يجب أن يتعاونوا، وأن يطرحوا الاختلاف والتَّنابز والإيذاء، بل كل واحدٍ يحرص على إصلاح أخيه، وإذا رأى عنده نقصًا أصلحه بالحكمة، والكلام الطيب، والدلالة على الخير، والتعاون على البر والتقوى، والتزاور، حتى تزول الوحشةُ، وحتى يتَّحد الهدف، وحتى يكون المقصود هو إقامة أمر الله في أرض الله.","link":"https://binbaz.org.sa/fatwas/4855/ما-اهمية-وكيفية-تحري-الحكمة-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0489.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":433,"question":"نرجو من سماحة الشيخ توضيح دور الحسبة في توجيه النشاط الاقتصادي المُعاصر؟","title":"ما دور الحسبة في توجيه النشاط الاقتصادي؟","answer":"الجواب: هذا مهمٌّ لا شك، وهذا لا يختص به العلماء، كل مَن له بصيرة من عاقلٍ يهتم بهذا الأمر؛ ليحرص على نشر الوعي فيما يتعلق بالاقتصاد، وأن يهتم كلُّ واحدٍ من أهل المال بأن يستخدم ماله فيما ينفع المسلمين: من زراعةٍ، وصناعةٍ، وغير هذا مما ينفع العباد ويُغنيهم عن الخارج، وألا يكون همُّه الفائدة من البنوك التي تمحقه وتمحق علمه ودينه وبركة ماله، بل يحرص على أن يستعمل هذا المال فيما ينفع المسلمين، فيوجد المصانع النافعة، والمزارع النافعة، وكل ما ينفع المسلمين ويُغنيهم عن الاستفادة من الخارج.\nوهذا لا شكَّ أنه يعمّ العلماء وأعيان البلاد وكل مَن له أدنى بصيرة، وعنده أدنى قدرةٍ على العمل أو المال، ينبغي أن يُنبه ويُشجع على الاستفادة من قوته في العمل، والاستفادة من ماله في العمل.\nبعض الناس عنده قوة ولكنه غافل ضعيف، ما يبالي، بل يفرح بأن يسأل الناس في المساجد وغير المساجد، ما عنده انتباه لما أعطاه الله من القوة على العمل.\nوبعض الناس عنده أموال راكدة مُعطَّلة، أو في الربا، هذا بلاءٌ عظيمٌ، ينبغي التنبيه والتَّعاون في هذا.","link":"https://binbaz.org.sa/fatwas/4857/ما-دور-الحسبة-في-توجيه-النشاط-الاقتصادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0491.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":438,"question":"انتشر في الوقت الحاضر السُّفور والاختلاط، وبالذات في الأسواق والأماكن العامَّة، فما موقف المُحتسب من ذلك؟ وما الطريق المناسب للقضاء على هذه المُنكرات؟ وما دور المُتطوع في ذلك؟","title":"ما السبيل تجاه مظاهر المنكرات المنتشرة؟","answer":"الجواب: أسباب هذه المنكرات: السُّكوت وعدم التَّعاون، والبحث مع الدولة في هذا جارٍ، نسأل الله أن يُوفِّق الهيئة ويُعينها على أداء الواجب، ولكن السكوت من الناس والتَّغاضي والإعراض هو من أسباب البلاء، يعني: الهيئة ما تعمّ الناس، ما هي شمسٌ تعمّ الناس، أولًا: قلَّة، وثانيًا: الشر كثير، وثالثًا: قد يضعف بعض الأعضاء عن القيام بالواجب؛ لأسبابٍ كثيرةٍ.\nفالواجب التعاون، أنتم سمعتم الآيات: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71]، مَن الذي يُخرجك من هذه الآية؟ أنت يا فلان، وأنت يا فلان، ما الذي أخرجك من هذه الآية؟ أنت مؤمن؟ حاسب نفسك، وهكذا أمُّك وأختك وزوجتك، مَن الذي أخرجها؟ ليش ترى منكرات في... من يجلسون معها، وفي بيتها، وفي الطريق، ولا تقول لهم شيئًا، ما الذي منعها؟ ولو ردّ عليك، لو قيل: ما عليك منه؟ ماذا يضرُّك؟ أو قيل: أنت يا الذي فيك وفيك ماذا يضرُّك؟ أما سبقك الرسل لهذا؟ أما سبقوك؟ أنت مسبوقٌ، لك أسوة.\nفالسكوت هو البلاء، والإعراض هو البلاء، تجده يرى المرأة الكاشفة ولا يقول شيئًا، يرى المدخن ولا يقول له شيئًا، يرى الحالق ولا يقول له شيئًا، وهكذا ساكت، جنبه أخوه في البيت ما يُصلي، أو جاره ما يُصلي ولا يقول له شيئًا، لماذا سكت؟ تقول: ما هو مطيعني؟ ولو ما أطاعوك قل، لكن لا تكن وحدك، إذا تيسر اذهب أنت واثنان وثلاثة من إخوانك، أحسن لكم، وأنفع لكم، وأقوى للكلمة.\nوماذا يضرُّ إذا ذهبتم جميعًا ونصحتم هذا وهذا؟ أو خرجتم من البيت، أو من المدرسة، أو من المعهد، أو من المسجد جماعة، تجولتُم في السوق للأمر بالمعروف والنَّهي عن المنكر، ما هو واحد، جماعة، حتى يُهابوا، يخرج جماعةٌ، يمتنع السَّفيه من الكلام والفاسق، لكن الواحد قد يُجترئ عليه، لكن إذا كانوا جماعةً –ثلاثة، أربعة- يخرجون لهذا الأمر حسبةً لله من المسجد، من البيت، يأتون جميعًا للسوق الفلاني، والسوق الفلاني، والحارة الفلانية؛ ليُنكروا المنكر، ويدعوا إلى الله، ما المانع؟ الدولة منعت؟ ما تمنع الدولة من هذا، لكن بالحكمة والكلام الطيب والأسلوب الحسن، ما هو بالمضاربة، لا مع النساء، ولا مع الرجال، ولا مع الكافر، حتى الكافر ليس له أن يُظهر شعاره في بلادنا، حتى الكافر يعلم بالإشارة أو بالكلام حتى يفهم، أو إذا تيسر معكم مَن يُجيد اللغة الإنجليزية أو غيرها، يكون معكم في التَّجول حول الإنجليزيين، حول الباكستانيين، حول الهنود، يعني: حول أصحاب اللغات الأخرى.\nالمقصود أنا أنصح دائمًا ألا يكون واحدًا، ما يمشي واحدٌ، يكونوا جماعة، هذا أشجع للقيام بأمر الله، وأهيب عند العاصي، وأقرب إلى النجاح، هذا الذي أنصح به الجميع، لكن لو كان واحدًا يُنكر حسب الطاقة، ولو واحد، لا يقل: أنا واحد، لكن إذا تيسر يكون معه ثانٍ أو ثالث أو رابع أو أكثر يكون هذا أحسن، اثنان ثلاثة أنفع، أربعة أنفع، هكذا في الزيارة لإخوانهم، ينصحونهم، ويُوجهونهم.","link":"https://binbaz.org.sa/fatwas/4862/ما-السبيل-تجاه-مظاهر-المنكرات-المنتشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0496.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":738,"question":"يقول السَّائل: أنا شابٌّ مسلمٌ والحمد لله، ولكن لي أبٌ لا يُصلي، هل أمكث معه في المنزل أم أهجره وأتركه؟ أفيدوني مأجورين، مع العلم أني طالبٌ أدرس في الثانوية، ولا أملك مالًا ولا دينارًا.","title":"حكم هجر منزل الأب الذي لا يصلي؟","answer":"الجواب: المشروع لك أن تبقى مع والدك، وأن تنصحه كثيرًا، وتعتني به كثيرًا، وتُحسن إليه، ولعلَّ الله يهديه بأسبابك، قال الله جلَّ وعلا في كتابه العظيم: وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَى وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ ۝ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:14- 15]، فأمر بأن يصاحب الوالدين الكافرين معروفًا، وهما كافران.\nفعليك أن تصحب والدك بالمعروف، وأن تُحسن إليه، وتنصحه كثيرًا، وتُعينه في الخير، ولا تُعينه في الشر، ولا تُقاطعه، ولا تخرج من عنده، بل عليك أن تنصحه كثيرًا وتُعينه في الخير، وتصبر على الأذى حتى يُفرّج الله ؛ لأنَّ الله قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا، ولم يزل الصحابةُ  في علاج بعض الصَّحابة الذين لهم آباء وأمهات تأخَّر إسلامهم، لم يزالوا في علاجٍ معه حتى هداهم الله: كأبي هريرة مع أمه، وسعد بن أبي وقاص مع أمه، حتى هداهما الله على يدي ابنيهما.","link":"https://binbaz.org.sa/fatwas/20614/حكم-هجر-منزل-الاب-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0548لي أب لا يصلي هل أمكث معه في المنزل أم أهجره فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":768,"question":"هل إنكار المُنكر مُقتصرٌ على المعنيين من أهل الحِسبة، أم هو عامٌّ لجميع المسلمين؟ وما حكم مَن قال لي وأنا أُنكر عليه: لا تأمر بالمعروف، ولا تنهَ عن المنكر حتى يأذن لك السلطانُ؟","title":"هل إنكار المنكر يقتصر على رجال الحِسبة؟","answer":"الجواب: الشيخ: ليس خاصًّا بالسلطان، ولا خاصًّا بالمعينين، بل هو عامٌّ كما تقدم في الكلمة، الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فهو فرضٌ على كل مؤمنٍ، وعلى كل مؤمنةٍ حسب الطاقة، لكنه في حقِّ ولاة الأمور، وفي حقِّ مَن عيَّنهم ولاة الأمور، في حقِّهم يكون أشدَّ وجوبًا، وأشد فرضًا، ولكن مثلما تقدَّم لا بدّ من كون الآمر والنَّاهي ذا علمٍ، وذا بصيرةٍ، حليمًا فيما يأمر به، وفيما ينهى عنه، رفيقًا، لا يُسبب مشاكل وفتنًا، بل تكون عنده الرزانة والصَّبر والحلم والرِّفق.\nس: الأخ يسأل عن السلام على مَن أفشى المُنكرات في الأسواق، وعن إنكار كل منكرٍ يُشاهده في السوق، هل يجب عليه الإنكار أم لا؟\nالشيخ: نعم، يُنكر على حسب طاقته، إذا كان يستطيع يُنكر باللسان، وإن كان يستطيع باليد -كأهل الحسبة- يُنكر باليد، ولو كثرت المنكرات لا ييأس، يكون عنده ظنٌّ حسنٌ، وعنده رجاءٌ بالله، ولا يملّ، بل يرجو ما عند الله من المثوبة، وإذا كان معه بعضُ إخوانه يكون أحسن: اثنان، ثلاثة، أربعة، يتعاونون في نصيحة الناس، وإنكار المنكر، والأمر بالمعروف بالرفق والكلام الطيب، يكون هذا أجدى وأنفع من الواحد.","link":"https://binbaz.org.sa/fatwas/20698/هل-انكار-المنكر-يقتصر-على-رجال-الحسبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0596هل أنكار المنكر مقتصر على المعنيين من أهل الحسبة أم هو عام لجميع المسلمين؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":775,"question":"يُلاحظ تحمس كثيرٍ من الشباب لإنكار المنكر، ولكنَّهم لا يُحسنون الإنكار، فما نصيحتكم وتوجيهاتكم لهؤلاء؟ وما الطريقة المُثْلَى في إنكار المُنكر؟","title":"ما الطريقة المُثْلى في إنكار المنكر؟","answer":"الجواب: نصيحتي لهم أن يتثبَّتوا في الأمر، وأن يتعلموا أولًا؛ حتى يتيقَّنوا أنَّ هذا معروف، وهذا منكر، حتى يعلموه بالدليل، ثم يكون الإنكار بالرفق والكلام الطيب والأسلوب الحسن، حتى يُقبل منهم، وحتى لا يُفسدوا أكثر مما يُصلحون، فإنه إذا أنكر بالأسلوب الشَّديد والعنيف لم يُقبل منه في الغالب، وأفضى إلى النزاع بينه وبين صاحبه، ثم قد تطول المسألة وترتفع إلى ولاة الأمور، فيُمنع لسوء أدبه، ولسوء تصرفه.\nفالواجب على الدَّاعي إلى الله والآمر بالمعروف والنَّاهي عن المنكر أن يسلك الطريق السوي، بالأسلوب الحسن، بالرفق، بالرحمة، بالعطف، يقول الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِي الْأَمْرِ [آل عمران:159]، يقول: هداك الله يا أخي، هداك الله، ما يجوز هذا الكلام، ما يجوز هذا الفعل، يا أخي، اتَّقِ الله، دع هذا.\nوقد قال الله لموسى وهارون عليهما الصلاة والسلام لما بعثهما إلى فرعون اللَّعين الطَّاغية الذي يقول: أنا ربكم الأعلى، ماذا قال لهما؟ قال لهما ما تقرؤونه في كتاب الله: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44].\nهكذا الأسلوب الجيد، مع أن يكون عاملًا بما يقول، يُعرف عنه العلم والعمل، والسيرة الحميدة، والأخلاق الفاضلة، ومع ذلك يرفق في الكلام في الأمر وفي النَّهي جميعًا، حتى تكون آثاره صالحةً، وعاقبة ما يقوم به حميدةً، وحتى يتأسَّى به الآخرون في عمله الطيب، وحتى ينفع الله به الأمَّة، ويكون بالكلام: بالآيات والأحاديث.","link":"https://binbaz.org.sa/fatwas/20691/ما-الطريقة-المثلى-في-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0588ما هي الطريقة المثلى في إنكار المنكر ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":776,"question":"ما كيفية النَّهي عن المنكر بالقلب؟ هل هو ببُغضه بقلبه ويبقى جالسًا مع  أهل المعصية؟ أو كيف يكون الإنكار بالقلب؟","title":"كيف يكون إنكار المنكر بالقلب؟","answer":"الجواب: مثلما تقدم، يُنكر بقلبه ولا يجلس معهم، إذا جلس معهم كفعل بني إسرائيل ما صار منكرًا، لكن إذا أنكر عليهم لا يُجالسهم في منكرهم، ويكون معهم على منكرهم، بل يُنكر عليهم ذلك، ويبغض المنكر، ويُفارق أهله، ولا يكون جليسًا لهم إلا إذا جاءهم للنُّصح والتَّوجيه والإرشاد والتَّعليم، أو لمصلحةٍ عامَّةٍ للمسلمين، أو نحو ذلك، لا يتّخذهم أصحابًا وأصدقاء وهم على المنكر، على المنكر الظاهر يعني.","link":"https://binbaz.org.sa/fatwas/20689/كيف-يكون-انكار-المنكر-بالقلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0587ما كيفية النهي عن المنكر بالقلب أو كيف يكون الأنكار بالقلب ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":777,"question":"فضيلة الشيخ، سمعتُ من بعض العلماء: أنَّ بعض العلماء عدَّ الأمر بالمعروف والنَّهي عن المنكر ركنًا من أركان الإسلام، فهل هذا صحيحٌ؟","title":"هل الأمر بالمعروف من أركان الإسلام؟","answer":"الجواب: نعم، قاله بعضُ أهل العلم، لكن لم يرد فيه نصٌّ واضحٌ في هذا، وإنما هو من أعظم فرائض الإسلام، فالأركان خمسة معروفة بيَّنها النبيُّ ﷺ، يقول ﷺ: بُني الإسلام على خمسٍ يعني: على خمس دعائم شهادة أن لا إله إلا الله، وأنَّ محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، هكذا قال النبيُّ ﷺ، هذه هي الدَّعائم التي نصَّ عليها الرسولُ ﷺ.\nولكنه في الحقيقة دعامة من الدعائم، وفرضٌ من الفروض، لكن لا يُقال: إنه هو السادس؛ لعدم الدليل على ذلك، لكنه دعامة من الدعائم، وفرضٌ من الفروض العظيمة، كما أنَّ الجهاد في سبيل الله دعامةٌ من الدعائم، وهكذا ترك المحارم التي حرَّمها الله على عباده دعامة من الدعائم لا بدّ منها، وفرض من الفروض لا بدّ منها.\nفكل ما أوجب الله علينا؛ علينا أن نستقيم عليه، وكلّ ما حرَّم الله علينا؛ علينا أن نستقيم على تركه، هذا كله من الفرائض، وإذا سميت دعامةً أو ركنًا من أركان الإسلام بمعنى أنه فرضٌ من فروض الإسلام فلا مشاحةَ في الاصطلاح.","link":"https://binbaz.org.sa/fatwas/20686/هل-الامر-بالمعروف-من-اركان-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0586عدَّ بعض العلماء أن الأمر بالمعروف والنهي عن المنكر من أركان الإسلام فهل هذا صحيح.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":796,"question":"كما نعلم في وقتنا الحاضر أنَّ هنالك جهةً مُختصةً مُكلَّفةً من ولي الأمر بالقيام بهذا الأمر –يعني: واجب الأمر بالمعروف والنهي عن المنكر- فهل يسقط بذلك هذا الواجب عن البقية وجزاكم الله خيرًا؟","title":"حكم الأمر بالمعروف لغير رجال الحِسبة","answer":"الجواب: تقدَّم في البحث أنَّ الأمر بالمعروف والنهي عن المنكر فرضٌ على الكفاية، إذا قام به مَن يكفي سقط عن الباقين، وصار في حقِّ الباقين سنةً، فإذا لم يقم به مَن أُسند إليه أثم الجميع؛ لأنه واجب عليهم، فرض كفايةٍ مُوجَّه إلى الجميع، وفرض على الجميع. فإذا كنت في قريةٍ لم ينكر المنكر غيرك، فأنت الواجب عليك أن تُنكره؛ لأن عندك العلم، أو في قبيلةٍ، وإذا كان معك غيرُك فمَن أنكره منكم حصل به الواجب، وإن تركتُموه أثمتم جميعًا، وكل واحدٍ منكم عليه أن يُبادر بأداء الواجب، فمَن أدَّاه منكم سقط عن إخوانه الذين معه، إذا امتثل المُنْكَر عليه وحصل المقصود.","link":"https://binbaz.org.sa/fatwas/20802/حكم-الامر-بالمعروف-لغير-رجال-الحسبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0630حكم الأمر بالمعروف والنهي عن المنكر لغير رجال الحسبة؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":797,"question":"ما الشروط الواجب توفرها في الشخص الآمر بالمعروف والناهي عن المنكر؟","title":"ما شروط الآمر بالمعروف الناهي عن المنكر؟","answer":"الجواب: أهمها العلم، أهمها أن يكون عالمًا بما يأمر به، عالمًا بما ينهى عنه. ومن جملة ذلك كما ذكر أهلُ العلم: الحلم والرفق، يكون حليمًا فيما يأمر به وينهاه، رفيقًا في ذلك، لا يستفزّه الغضب، ولا تأخذه العجلة، بل يرفق، ولا يعجل، ولا يغضب، بل يحلم عند المناقشة والبحث والإنكار. فأهم الأمور: العلم، أن يكون على بصيرةٍ فيما يأمر به وينهى عنه، مع الحلم والرفق، وعدم العجلة في الأمور والشدة والغِلْظَة.","link":"https://binbaz.org.sa/fatwas/20800/ما-شروط-الامر-بالمعروف-الناهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0629ما هي الشروط الواجب توفرها في الشخص الآمر بالمعروف والناهي عن المنكر؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":798,"question":"إنَّ كثيرًا من الشباب يدعونني أن أشترك معهم في الدعوة إلى الله، وهم من جماعةٍ تُسمَّى \"جماعة التبليغ\"، فما رأيكم في ذلك؟ هل أشترك معهم أم لا؟","title":"ما المنهج الصحيح تجاه جماعات الدعوة؟","answer":"الجواب: الجماعة كثيرون، جماعات متنوعة، فلا مانع من الاشتراك معهم في الخير والدعوة إليه، لا في كل شيءٍ، مَن دعاك إلى الخير تشترك في الخير: جماعة التبليغ، أو أنصار السنة، أو جماعة الإخوان المسلمين، أو جماعة المسلمين في قُطْرٍ آخر، أو جماعة الدَّعوة في قُطْرٍ آخر، أو ما أشبه ذلك من الأسماء، أو المركز الإسلامي، أو الاتحاد الإسلامي، أو اتحاد المسلمين، بأي اسمٍ سمّوه، إذا دُعيتَ إلى ذلك فشارك في الخير، ولا تُشارك في الشر، أجبهم إلى ما طلبوا فيما يتعلق بالشرع المطهر، وأنكر عليهم ما خالفوا من الشرع المطهر، واجعل نفسك واسطةَ خيرٍ، وداعيةَ خيرٍ، تحثُّهم على الالتزام بأمر الله، وتُحذرهم من التَّفرق والاختلاف، فلا تكن معهم مطلقًا، ولا عليهم مطلقًا، بل معهم في الخير، وعليهم فيما أخطأوا فيه حتى يهتدوا ويلتزموا.","link":"https://binbaz.org.sa/fatwas/20798/ما-المنهج-الصحيح-تجاه-جماعات-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0627المنهج الصحيح في الانضمام إلى الجماعات الإسلامية.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":805,"question":"فضيلة الشيخ، حفظكم الله، لقد قلتُم أنَّ الأمر بالمعروف والنَّهي عن المنكر فرضُ كفايةٍ، ويرى آخرون أن الأمر بالمعروف والنَّهي عن المنكر واجبٌ على كل مسلمٍ ومسلمةٍ بقدر ما أعطاه الله من العلم والاستطاعة، فكيف نُوفِّق بين الرأيين؟","title":"حكم الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: ما في خلاف بين أهل العلم أنه فرض كفايةٍ، ولكنه واجبٌ على المسلم، إذا لم يقم غيره بهذا الواجب تعيَّن عليه، فإذا كنتَ مثلًا في حيٍّ من الأحياء، أو مجتمع من الاجتماعات، فرأيتُ منكرًا: رأيت إنسانًا رفع كأس الخمر ليشرب، فسبقك واحدٌ وأنكره، فأراق صاحبُ الكأس خمره وامتثل وقال: جزاك الله خيرًا، هل بقي لإنكارك محلٌّ أنت؟ ما عاد بقي له محله، زال المنكر، أو تمشي أنت وصاحبٌ لك، فرأى إنسانًا واقفًا بعد الأذان، فسبقك وقال: يا أخي، اتَّقِ الله، الصلاة، الصلاة، فمشى وذهب إلى المسجد، فماذا بقي لإنكارك أنت؟ هل حصل المطلوب أو ما حصل المطلوب؟\nفمَن قال: إنه فرض عينٍ، مراده فرض عينٍ عند عدم وجود مَن أنكر، وأما إذا أنكر زال المحذور، فهو فرض كفايةٍ، معناه: إذا قام به مَن يكفي سقط عن الباقين، فإذا ما قام به وجب عليك: أنتم ثلاثة مررتُم على منكرٍ، ما أنكر الاثنان اللَّذان تظنّهما أفضل منك مثلًا أو أقوى منك؛ تعيَّن عليك، فإذا أنكر أحدُهما لم يتعين على الباقي إذا زال المحذور وحصل المقصود، أما إذا ما زال المحذور يُنكر الثاني والثالث والرابع والخامس حتى يزول المحذور.\nفمَن قال: إنه فرضٌ على كل مسلمٍ، يعني: فرض على كل مسلمٍ عند عدم وجود مَن قام بالواجب هذا، هذا مُراده، فلا معارضة.","link":"https://binbaz.org.sa/fatwas/20791/حكم-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0621حكم الأمر بالمعروف والنهي عن المنكر؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":815,"question":"ما توقعاتكم للدعوة مُستقبلًا على ضوء الواقع الذي نعيشه اليوم، وبالنظر إلى الشُّرور التي تُكاد للمُسلمين يومًا بعد يوم؟","title":"ما التوقعات المرجوّة لمستقبل دعوة الإسلام؟","answer":"الجواب: كل مؤمنٍ عرف الواقع، وتبصَّر في الواقع، وعرف الناس اليوم، يتوقع كلَّ خيرٍ في المستقبل، ويحسن ظنّه بالله ، ويرجو أن الإسلام ينمو في الشعوب كلها، وأن هذا النشاط الشَّبابي وغير الشبابي يُرجى فيه الخير العظيم، فهناك بحمد الله يقظةٌ في كل مكانٍ: في البلاد العربية، وفي غيرها، حتى في بلاد الغرب: في أمريكا وأوروبا، وحتى في بلاد الروس، حتى في بلاد الصين.\nفالحركة بحمد الله مُنتشرة، واليقظة عظيمة، لكنها مختلفة بالنسبة إلى أقطار الدنيا، فهي تُبَشِّر بالخير، وتدل على خيرٍ، ويظهر منها والحمد لله أن المستقبل للإسلام وأهله، وأن الناس بخيرٍ، مع كثرة أعداء الإسلام وما يكيدون له من المكائد، لكن هذه اليقظة وهذه الحركة الجديدة تُبَشِّر بخيرٍ عظيمٍ، ويُرجى لها نماء كبير، وعاقبة حميدة، ولكنها في حاجةٍ شديدةٍ إلى التَّكاتف والتَّعاون، والقيادة الصالحة، والصبر والمصابرة، وعدم اليأس، وعدم التَّسرع في الأمور، فلا بدّ من صبرٍ ومُصابرةٍ، ولا بدّ من عنايةٍ بالعلم، ومُذاكرةٍ في العلم، ولا بدّ من أناةٍ وعدم عجلةٍ، وتعاون بين الحركات: من جمعيات ومراكز إسلامية ودعاة، لا بدّ من التعاون: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103].\nوالرسول عليه الصلاة والسلام قال: بدأ الإسلام غريبًا، وسيعود غريبًا كما بدأ، فطُوبى للغُرباء؛ الذين يصلحون إذا فسد الناس، وفي اللفظ الآخر: يُصلحون ما أفسد الناسُ، فهؤلاء الغُرباء اليوم يُرجى لهم الخير العظيم في الصلاح والإصلاح.\nوالواجب على كل مسلم –ولا سيما أهل العلم- في كل مكانٍ أن يعضدوا هذه الحركة، وأن يُعينوها  ويدعموها بكل ما يستطيعون: من كلامٍ، ومالٍ، وكتبٍ صالحةٍ، وغير هذا من وجوه الدعم، حتى تنشط وتقوى، مع ترشيد الجاهل، وتعليم مَن حاد عن الصواب، وتنبيه مَن أفرط أو فرَّط، لا بدّ من التعاون؛ لأن بعض الناس قد يحمله حبُّه للخير ونشاطه فيه إلى الغلو والإفراط والزيادة، وبعضٌ آخر قد يحمله ضعفُ إيمانه وقلَّةُ علمه على الجفاء والتَّساهل.\nفيجب على أهل العلم والإيمان التوسط في الأمور، والأخذ بأيدي المسلمين -ولا سيما شبابهم- إلى الطريق الوسط: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ [الأنعام:153]، وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا الآية [البقرة:143]، فلا مع الغُلاة، ولا مع الجفاة، ولكن مع أهل الاعتدال والاستقامة.","link":"https://binbaz.org.sa/fatwas/20846/ما-التوقعات-المرجوة-لمستقبل-دعوة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0642ما هي توقعاتكم في الدعوة إلى الله مستقبلاً ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":838,"question":"ما حكم إزالة منكرٍ يترتب عليه قطع رحم؟","title":"ما حكم إزالة منكرٍ يترتب عليه قطع رحم؟","answer":"الجواب: ما يلزم من إنكار المنكر قطيعة الرحم، إذا كان لا يُصلي تهجره، وهو القاطع هو، لستَ القاطع أنت، هو القاطع؛ لأنه فعل ما يُوجب هجره، وهكذا إذا كان يتعاطى على وليمته بالمُنكرات، فهجرت وليمتَه ولم تُجب دعوتَه؛ لأنه يشرب عليها الخمر، هو القاطع، ما هو أنت القاطع، القاطع مَن فعل المنكر، وليس القاطع مَن هجره، فليس هذا قطيعةً، ولكن طاعةً لله ولرسوله، وإنكارًا للمنكر، وهجرًا لمَن يستحق الهجر.\nوقد هجر النبيُّ ﷺ والمسلمون كعب بن مالك وصاحبيه خمسين ليلةً، وهجره من أقاربه الكثير، وهم أقارب؛ طاعةً لله ولرسوله، فلم يُسَمِّ هذا قطيعة.","link":"https://binbaz.org.sa/fatwas/20873/ما-حكم-ازالة-منكر-يترتب-عليه-قطع-رحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0668ما حكم إزالة منكر يترتب عليه قطع رحم؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":868,"question":"كيف يستطيع المسلمُ أن يرجع في دعوته في بيته ويُؤثر فيهم؟","title":"كيف يكون المسلم داعيةً في بيته؟","answer":"الجواب: المقصود أنَّ عليه أن يعمل في بيته بطاعة الله وشرع الله، عليه أن يلزم شرع الله، وأن يكون قدوةً لأهل بيته بالعمل بطاعة الله، والحذر من محارم الله؛ حتى يقتدوا به، فإذا كان صادقًا يلتزم بشرع الله في أعماله وأقواله حتى يتأسَّى به أولادُه وإخوانه وزوجته ونحو ذلك، وإذا خالفوه يُعالج الموضوع بالحكمة، يُعالجه بالكلام الطيب، والأسلوب الحسن. وإذا كان يستطيع أن يُؤدِّب بعضَ أولاده أو زوجته إذا خالفوه فيما أوجب الله أدَّبهم بالتأديب المناسب الخفيف الذي يُعينهم على طاعة الله، ويُعينهم على ترك محارم الله؛ فالإنسان يضرب كما قال النبيُّ ﷺ: واضربوهم عليها لعشرٍ الأولاد، وقال في النساء: واضربوهنَّ، فإذا رأى أنَّ من الحكمة أن يضرب المرأة على أن تُؤدي ما أوجب الله، وأن تدع ما حرَّم الله؛ فله ضربها الضَّرب الخفيف الذي لا يبرح، إذا استطاع ذلك، وظنَّ أنَّ هذا يُفيد، وهكذا مع أولاده إذا استطاع ذلك. لكن أهم الأمور أن يكون قدوةً حسنةً: أن يُسارع في الخيرات، ويستقيم على الطاعات، حتى يُشاهدوا منه الفعل الطيب، والكلام الطيب، حتى يتأسَّوا به.","link":"https://binbaz.org.sa/fatwas/20903/كيف-يكون-المسلم-داعية-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0698كيف يكون المسلم داعية في بيته؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":905,"question":"ما الوسائل السَّهلة لجمع كلمة المسلمين، أو الكفيلة بجمع كلمة المسلمين، تحت راية التوحيد؟","title":"ما سُبُل جمع كلمة المسلمين على التوحيد؟","answer":"الجواب:\nلا طريق إلى ذلك إلا بالدَّعوة إلى الله، والتَّفاهم، والحكمة، والكلام الطيب، وكثرة الدعاة الذين يدعون عن علمٍ وبصيرةٍ، وتجولهم في البلاد، وقيام العلماء بما أوجب الله عليهم من ذلك في أي مكانٍ.\nومن أسباب ذلك أيضًا: توفيق الله لولاة الأمور حتى يُلزموا الناسَ بالحقِّ، وحتى يدعوهم إليه، وحتى يُعاقبوا مَن ترك ما أوجب الله عليه، كما كان في عهد السلف الصالح.\nفإذا قام الأمراءُ والعلماءُ بواجبهم من الدَّعوة والتَّوجيه والإلزام بالحقِّ اجتمعت كلمةُ المسلمين، وزال عنهم الشرُّ، واستقاموا على الحقِّ، وما دام الدُّعاة قليلين، والعلماء قليلين، ومع قلَّتهم يقلّ منهم مَن يدعو ويُوجّه ويُرشد ويُعلّم، وما زال ولاةُ الأمور على حالهم المعروفة؛ فاجتماع المسلمين على الحقِّ فيه بُعْدٌ، إلا أن  يُغيّر الله الحال إلى ما هو خيرٌ منها وأحسن، كما جاءت به الأحاديث في آخر الزمان، وأنَّ الله جلَّ وعلا يجمعهم على الحقِّ حين ينزل رسوله عيسى عليه الصلاة والسلام، فلا يقبل إلا الإسلام، ويُهلك الله في زمانه الأديان كلها، ويقتل الخنزير، ويكسر الصليب، ويضع الجزية، ولا يقبل إلا الإسلام. وهكذا ما جاء في عهد المهدي قبيل عهد المسيح: من عموم العدل، وكثرة الخير بسبب الدعوة والتعليم والتَّوجيه، وإقامة الحق، والإلزام بالحدود، ومنع الناس من الباطل.\nوهنا بحمد الله الآن في أول هذا القرن وفي آخر القرن الماضي صارت حركةٌ عظيمةٌ، وحياةٌ جديدةٌ، ويقظةٌ بحمد الله إسلامية، نسأل الله أن يُباركها، وأن ينفع بها المسلمين، وأن يُعين القائمين بها على أداء الواجب، وأن يُبصّرهم، وأن يرزقهم القادة الطيبين الصَّالحين.","link":"https://binbaz.org.sa/fatwas/20938/ما-سبل-جمع-كلمة-المسلمين-على-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0734ما هي الوسائل السهلة الكفيلة لجمع كلمة المسلمين تحت راية التوحيد؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة"]},{"id":1049,"question":"الطفل الذي يُولد من امرأةٍ زُرع في رحمها البويضة المُلقحة خارج الرحم من امرأةٍ غيرها ورجلٍ غريب؟","title":"حكم البويضة المُلقّحة من غير الزوج","answer":"الجواب: إذا زُرعت فيها النُّطفة ليست من زوجها فهو في حكم الزنا، فالولد يُنسب إليها، الولد لها هي فقط، ولا يُنسب إلى أبيه الذي هو بحكم الزاني، ولا إلى أمه التي لا أساسَ لها إلا أنها زُرعت منها البُويضة، يكون للتي ولدته: إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ [المجادلة:2]، يُنسب إلى أمه التي ولدته، والنُّطفة التي نُزعت من الشخص الأجنبي والمرأة الأجنبية ليس لهما فيها نصيبٌ. ولا يجوز هذا العمل، هذا ما يجوز، وقد درس هذا مجمعُ الفقه أيضًا وقرر تحريم هذا، أنه لا يجوز إلا إذا كان من زوجٍ فقط، أما من شخصٍ أجنبيٍّ أو امرأةٍ أجنبيةٍ فهذا لا يجوز، لا بدّ أن يكون من مائه ومائها فقط: من ماء الزوج، وماء المرأة فقط.","link":"https://binbaz.org.sa/fatwas/21106/حكم-البويضة-الملقحة-من-غير-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0902الطفل الذي يولد من أمراءة زُرِعً في رحمها البويضة الملقحة من أمراءة غيرها ورجل غير زوجها.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":1095,"question":"هل المسائل العملية المُشتبهة: كالعُذر بالجهل -ونعوذ بالله من ذلك- يُوجب الخلاف فيها ووقوع الهجر والبغضاء بين أصحاب المُعتقد السَّلفي الواحد؟","title":"حكم التباغض بسبب الخلاف في المُشتبهات","answer":"الجواب:\nالواجب في هذا الأسلوب الحسن، وحُسن الظن، وعدم العنف والشدة، فالكل طالبٌ للحقِّ، والله يقول جلَّ وعلا في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول في حقِّ أهل الكتاب: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46] وهم كفَّار، نهانا أن نُجادلهم إلا بالتي هي أحسن وهم كفَّار، كيف بإخواننا؟!\nالواجب الجدال بالتي هي أحسن، وحسن الظن، وحمل أخيك على أحسن المحامل، حتى يهتدي، وحتى يقبل الحقَّ، لا تيأس، ولا تهجر، ولكن عليك بالمجادلة بالتي هي أحسن، وحسن الأسلوب، والصبر، والتحمل، وعدم الغضب، حتى يظهر الحقُّ للجميع، والحق ضالَّة المؤمن، وليس من شرط ذلك أن تظهر أنت، عليك بطلب الحقِّ، والجدّ في طلب الحق، سواء غَلبتَ أو غُلبتَ، سواء ظهر الحقُّ على يديك، أو على يد أخيك، عليك بالإخلاص، وأن يكون هدفك ظهور الحقِّ، سواء معك أو مع أخيك.\nهذا هو شأن المؤمن: يحرص على ظهور الحق من طريقه أو من طريق إخوانه، ومتى ظهر الحقُّ خضع له، وأجاب إليه، ولم يتكبَّر، ولم يستمر في باطله، ويلج في باطله.\nومن أهم الأمور: العناية بالأسلوب الحسن، وحسن الظن، وعدم سوء الظن، واختيار الكلمات الطيبة، والصبر على ما قد يقع من أخيك من أذى، أو كلمات نابية، أو غير هذا، حتى تصلوا جميعًا إلى الحقِّ، وأنتم بحمد الله تُريدونه وتطلبونه.\nأما إذا ساءت الأخلاقُ، وساءت الظنون، وساء الكلام، فإنَّ هذا من أسباب ضياع الحقِّ، ومن أسباب الفرقة والاختلاف التي ذمَّها الله وعابها. نسأل الله السَّلامة.","link":"https://binbaz.org.sa/fatwas/21156/حكم-التباغض-بسبب-الخلاف-في-المشتبهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0952هل المسأئل العلمية المشتبهة يوجب الخلاف فيها ووقوع الهجر والبعضاء؟ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1096,"question":"ما دور المسلم فيما يجري من الأحداث العظام على الأرض: بسقوط النظام الشيوعي في أوروبا الشرقية، وحركات التَّحرر في شعوب العالم؟ أليس الوقت مناسبًا لكي ينطلق الدُّعاة من المسلمين لهذا الدين إلى هؤلاء المساكين؟ ولكن كيف؟","title":"ما دور المسلم فيما يجري من أحداث بالعالم؟","answer":"الجواب:\nلا شكَّ أنَّ هذا من نِعَم الله، هذا الانهيار -سقوط الدول الشيوعية- لا شك أنَّ هذا من نعم الله العظيمة، فإنها تتابعت السقوط والانهيار، هذا من رحمة الله جلَّ وعلا، ولا شكَّ أنه يُوجِب على أهل الإسلام الجدّ والنشاط في دعوة أولئك، وشرح الإسلام لهم، ببعث الدعاة، والكتب النافعة، والمصاحف.\nوالمسلمون أولى بهذا من نشاط الآخرين من النصارى وغيرهم، يجب على أهل الإسلام، وعلى ملوك الإسلام، وعلى علماء الإسلام أن ينشطوا في هذا الأمر العظيم.\nونُبشِّركم أنَّ الجهود في هذا إن شاء الله مبذولة منا ومن غيرنا، ونسأل الله أن ينفع بالأسباب، الجهود مبذولة منا، ومن الرابطة، ومن غيرنا من أهل العلم، ونسأل الله أن يُبارك في الأسباب، وأن ينفع بالأسباب.\nوالواجب على كل عالمٍ وكل مَن له قدرة أن يُشارك وأن يُساهم بما أعطاه الله من علمٍ ومالٍ وجاهٍ وغير ذلك، والله لا يُضيع أجر مَن أحسن عملًا .","link":"https://binbaz.org.sa/fatwas/21155/ما-دور-المسلم-فيما-يجري-من-احداث-بالعالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0951ما دور المسلم فيما يجري من الأحداث العظام على الأرض؟ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1129,"question":"لا شكَّ أنَّ من إحياء التراث الإسلامي كما تفضلتم: الدَّعوة إلى الكتاب والسنة، وتبليغها للناس جميعًا، بماذا تنصحون الشباب الإسلامي في هذا العصر؟","title":"ما النصيحة للشباب المسلم في هذا العصر؟","answer":"الجواب:\nننصحهم أولًا بالعناية بالعلم، وأن يكونوا على بصيرةٍ، فإذا حصلت لهم البصيرة فالواجب عليهم الدَّعوة، فإنَّ هذا الدين علمٌ وعملٌ ودعوةٌ وصبرٌ، كما قال : وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر].\nذكر الشيخ محمد رحمه الله في كتابه الصغير \"ثلاثة الأصول\" أنه يجب على المسلم هذه الأربعة: العلم، والعمل، والدعوة، والصبر، والمقصود مَن هو أهلٌ لذلك عليه أن يتعلم ويعمل، ثم عليه أن يدعو ويصبر، كما دلَّت عليه الآية: وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، فلا بد من بصيرةٍ: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، فيدعو إلى ما يعلم، يعلم الصلاة وأحكامها يدعو إلى الصلاة وأحكامها، يعلم الزكاة مع ذلك يدعو إلى الزكاة وأحكامها، إذا كان على بصيرةٍ: الصيام، الحج، الجهاد، برّ الوالدين، صلة الرحم، يدعو إلى كل ما يعلم على بصيرةٍ، يحذر من الزنا، من اللواط، من شرب الخمر؛ لأنه يعلم أحكام هذه الأشياء: من الربا، من قذف المحصنات.....\nلا يتكلم في شيءٍ إلا عن علمٍ وبصيرةٍ، كما قال الله جلَّ وعلا في كتابه العظيم: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [الأعراف:33]، فجعلها في الذِّروة، جعلها أعلى؛ لأنَّ الآية فيها التَّرقي من الأدنى إلى الأعلى، فأعظم الذنوب الشِّرك، ثم جعل فوقه هنا القول على الله بغير علمٍ؛ لأنَّ الشرك من القول على الله بغير علمٍ، ويدخل في القول على الله بغير علم أشياء كثيرة، فوجب على العبد أن يحذر ذلك.\nوأخبر في سورة البقرة أن الشيطان يدعو إلى هذا ويأمر به، قال سبحانه: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ  ۝  إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [البقرة:168- 169]، هذه حال عدو الله، يدعونا إلى الفحشاء والسوء والقول على الله بغير علمٍ، فوجب الحذر من ذلك.","link":"https://binbaz.org.sa/fatwas/21203/ما-النصيحة-للشباب-المسلم-في-هذا-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0999لاشك أن من أحياء التراث الإسلامي الدعوة إلى الله والسنة وتبليغها للناس فماذا تنصون الشباب في ذلك.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1165,"question":"قد يُشاهد الشابُّ في منزله مخالفةً شرعيةً، ويجد صعوبةً في الإنكار، وصعوبةً أشدّ في السُّكوت عن هذه المُخالفة، فهل من توجيهٍ نحو الأسلوب الذي ينبغي أن يسلكه الشابُّ تجاه هذه المُخالفات؟","title":"ما الأسلوب الصحيح للإنكار في البيوت؟","answer":"الجواب:\nلا يجوز للشابِّ، ولا غير الشابِّ، لا يجوز له السُّكوت، بل يُنكر حسب طاقته، سواء كان شابًّا أو فتاةً أو كهلًا أو شيخًا أو عجوزًا، على الجميع الإنكار، والله يقول جلَّ وعلا في كتابه العظيم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فجعل هذا الخُلُق من أخلاق المؤمنين والمؤمنات جميعًا، قال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110]، ولعن كفَّار بني إسرائيل لتضييعهم هذا الواجب، فقال سبحانه: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ  ۝  كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ [المائدة:78- 79].\nوقال النبيُّ ﷺ: إنَّ الناس إذا رأوا المنكر ولم يُغيِّروه أوشك أن يعمَّهم الله بعقابه خرجه الإمام أحمد بإسنادٍ صحيحٍ عن الصديق ، وقال أيضًا عليه الصلاة والسلام: مَن رأى منكم مُنكرًا فليُغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان خرجه مسلمٌ في \"صحيحه\" عن أبي سعيدٍ الخدري .\nفعلى الشابِّ وعلى غيره الإنكار حسب الإمكان، بالأسلوب الحسن، والطريقة المناسبة التي يراها أنجع وأنفع: على أبيه، وعلى أمه، وعلى إخوانه وأخواته، وأخواله وأعمامه، وغيرهم، على أهل بيته بالطريقة التي يراها أنجع، مع الأب لها حال، ومع الأم لها حال، ومع الأخوال والأعمام لها حال، ومع الإخوة لها حال، ومع الزوجة لها حال، ويحرص على أن يكون معه غيرُه من إخوته يُساعدونه إذا هداهم الله، حتى تكون الكلمةُ واحدةً، لكن بالأسلوب الحسن، ولا سيما مع الوالدين، يتأدَّب مع الوالدين، ولا يتكلم إلا بكلامٍ طيبٍ ومعقولٍ؛ لأنَّ الله قال في حقِّ الكافِرَيْنِ: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، فكيف بالمسلِمَيْنِ؟!\nيا أبتِ كذا، يا أمي، يا أماه كذا وكذا، هذا لا يجوز، وأنا أخاف عليكما من سخط الله، أخاف عليكما من عقوبة ذلك، فيما يرى من المنكر: كالتَّخلف عن الصَّلوات، سماع الأغاني والملاهي، السَّبّ والشَّتم، إلى غير هذا من المنكرات، ولا يغفل، ولا يسكت، ولكن بالحكمة، والكلام الطيب، والأسلوب الحسن، وتحري الأوقات المناسبة، فإذا أمكن أن يكون معه غيرُه من خالٍ أو خالةٍ، أو عمٍّ أو عمَّةٍ، أو أخٍ يساعد معهم يكون ذلك أنفع.","link":"https://binbaz.org.sa/fatwas/21218/ما-الاسلوب-الصحيح-للانكار-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1014ما هو الأسلوب الأنسب إذا وجد منكر أو مخالفة في بيته؟ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1184,"question":"هل يجوز الجلوس مع أهل المعاصي بقصد دعوتهم إلى الله تعالى وتغيير المُنكر؟","title":"حكم الجلوس مع أهل المعاصي لدعوتهم","answer":"الجواب:\nنعم، إذا جلس بينهم للدَّعوة والتَّوجيه إلى الخير فهذا مأجورٌ ومشكورٌ، النبي كان يمرُّ على القبائل من الكفرة ويدعوهم إلى الله في منى، وهكذا في مكة: يأتي مجالسهم ويدعوهم إلى الله، هذا مأجورٌ، هو جهادٌ إذا كان بهذا القصد.  أما جلوسه معهم للصحبة والتَّلذذ بالأكل والشرب والمضاحكة فلا، أما إذا كان يجلس معهم أو يقف عليهم للدَّعوة والتَّوجيه والإرشاد والكلام الطيب والاحتساب والصبر والأسلوب الحسن؛ فهذا عمل الأنبياء.","link":"https://binbaz.org.sa/fatwas/21248/حكم-الجلوس-مع-اهل-المعاصي-لدعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1146هل يجوز الجلوس مع أهل المعاصي بقصد دعوتهم وتغيير المنكر؟ ابن باز فتاوى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1187,"question":"بعض الإخوة الذين يدعون إلى الله قد يختلفون فيما بينهم في بعض الأمور، فما رأيكم؟","title":"ما الحكم والتوجيه فيما يقع من اختلاف الدعاة؟","answer":"الجواب:\nيدعون إلى الله فيما يتَّفقون عليه، ويدرسون ما أشكل عليهم من جهة الأدلة، أو مع أهل العلم الذين هم أعلم منهم، حتى يتَّفقوا؛ لأنَّ النزاع قد يضرُّ، فيدعون إلى الله فيما اتَّفقوا عليه، ولا يختلفون عند الناس، ويدرسون ما اختلفوا فيه حتى يتَّفقوا، أو يسألون مَن هو أعلم منهم إذا خفيت عليهم الأدلةُ، لعلَّهم ينجحون ويتَّفقون، وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21245/ما-الحكم-والتوجيه-فيما-يقع-من-اختلاف-الدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1149بعض الدعاة يختلفون فيما بينهم فما رأي سماحتكم؟ ابن باز فتاوى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1194,"question":"يشتكي كثيرٌ من إخواننا المسلمين من بلاد شرق آسيا وشبه القارة الهندية من سُوء معاملة الشباب المُلتزم لهم، وأخشى أن يكون ذلك سبب احتقارهم لهم وعدم احترامهم، مع أنهم مسلمون، وقد نهى النبيُّ ﷺعن ذلك، نرجو من سماحتكم التَّوجيه.","title":"ما النصيحة المناسبة بحُسن الخلق في الدعوة؟","answer":"الجواب:\nالواجب على الدُّعاة إلى الله في أي مكانٍ، سواء كانوا شبابًا أو شيبًا أو كهولًا، الواجب عليهم أن يرفقوا بالناس، وألا يحتقروهم، بل عليهم أن يُعلِّموهم ويُرشدوهم ويرحموهم، لعلهم يقبلون منهم، ولعلهم يهتدون، يقول النبيُّ ﷺ في الحديث الصحيح: مَن يُحْرَم الرفق يُحرم الخير كله، ويقول عليه الصلاة والسلام: إنَّ الرفقَ لا يكون في شيءٍ إلا زانه، ولا يُنزع من شيءٍ إلا شانه، ويقول عليه الصلاة والسلام: اللهم مَن ولي من أمر أمتي شيئًا فرفق بهم فارفق به، اللهم مَن ولي من أمر أمتي شيئًا فشقَّ عليهم فاشقق عليه.\nفالواجب على الدعاة أن يرفقوا بالكافر والعاصي، ولا يعجلوا، ولا يعنفوا، بل بالدَّعوة بالتي هي أحسن، بالرفق، بالحكمة، والدعاء له بالهداية، لعله يستجيب، يقول الله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول سبحانه: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ يعني: اليهود والنَّصارى إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] يعني: الظالم المتعدي يُعامل بما يستحقّ، أما ما دمت تدعوهم ولم يظلموك فجادل بالتي هي أحسن، وارفق بهم.\nوقال جلَّ وعلا في وصف نبيه محمد ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]، ولما بعث الله موسى وهارون إلى فرعون قال لهما: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44].\nفالواجب على الدُّعاة إلى الله في باكستان، أو في بنغلاديش، أو في الهند، أو في أي مكانٍ، أو في المملكة هنا، أو في أي مكانٍ: الرفق، والكلام الواضح الطيب، والجدال بالتي هي أحسن، والدعاء لهم بالهداية، جاء رجلٌ إلى النبي ﷺ فقال: يا رسول الله، إنَّ دوسًا قد عصت وأبت الإسلام، فادع عليهم، فقال ﷺ: اللهم اهدِ دوسًا وائتِ بهم، اللهم اهدِ دوسًا وائتِ بهم، فهداهم الله وجاءوا إلى المدينة مسلمين؛ فلا بد من الرفق.","link":"https://binbaz.org.sa/fatwas/21238/ما-النصيحة-المناسبة-بحسن-الخلق-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1156نصيحة للدعاة إلى الله بحسن الخلق؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1197,"question":"نلاحظ هذه الأيام تزايد نشاط أعداء الله من العلمانيين وغيرهم لكيد شباب الصَّحوة، ولكن لا بدَّ للشباب من التَّثبت والركود وحساب كل شيءٍ، حتى لا يُستدرجوا إلى ما لا تُحمد عقباه، نرجو من سماحتكم توجيه النَّصيحة إلى إخواننا في ذلك؟","title":"كيف يُنصح الشباب بالتثبت وتجنب الاندفاع؟","answer":"الجواب:\nنعم، يجب على الشباب وغير الشباب، يجب على أهل العلم، وعلى كل مؤمنٍ التَّثبت في الأمور وعدم العجلة، وهكذا يجب على كل مؤمنةٍ التَّثبت في الأمور وعدم العجلة، فإذا رأى ما يُخالف الشرع المطهر أو سمع به أنكره حسب طاقته مع الشخص، ينصحه، المرأة مع المرأة ومع غيرها تنصحها، المرأة تنصح وتأمر بالمعروف وتنهى عن المنكر كالرجل، مع أخيها، ومع أبيها، ومع أولادها، ومع جيرانها، ومع غيرهم، المؤمنون شيءٌ واحدٌ، المؤمنون إخوة: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، والعَجَلة شرُّها عظيم، وعاقبتها وخيمة، وفي الحديث: العَجَلة من الشيطان، وفي الحديث الصحيح: مَن يُحرم الرفق يُحرم الخير كله.\nفالواجب على مَن رأى شيئًا من المنكر في الطريق أو في السوق أن يُنكره بالكلام الطيب: يا عبدالله، يا أمة الله، هذا لا يجوز، الواجب عليك يا عبدالله كذا، الواجب عليكِ يا أمة الله كذا، هدانا الله وإياكم، وفَّقنا الله وإياكم؛ لأنَّ هذا يُقرّب القلوب ويدعوها إلى القبول، أما: يا فاجر، يا خبيث، يا كذا، هذا يُسبب النّفرة والشَّحناء، وربما أفضى إلى المجادلة والمقاتلة.\nفالواجب على المؤمن والمؤمنة في مثل هذا المقام الرفق والحكمة: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وهي العلم وَالْمَوْعِظَةِ الْحَسَنَةِ الترغيب والترهيب وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] عند الشُّبهة، والجدال بالتي هي أحسن حتى ولو كان كافرًا، بالتي هي أحسن، قال تعالى: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ، وأهل الكتاب هم اليهود والنصارى إِلَّا الَّذِينَ ظَلَمُوا [العنكبوت:46]، إلا مَن ظلم وتعدَّى عليك وسبَّك، هذا ترفع بأمره، تشكوه إلى ولاة الأمور حتى يأخذوا حقَّك منه، حتى لا تكون فتنة.\nوالمقصود من هذا كله أن الواجب التناصح، والأمر بالمعروف، والنهي عن المنكر بالحكمة، والكلام الطيب، والأسلوب الحسن، لا بالعنف والشدة، ولا بالألفاظ القبيحة الشنيعة المنفرة.","link":"https://binbaz.org.sa/fatwas/21235/كيف-ينصح-الشباب-بالتثبت-وتجنب-الاندفاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1159نصيحة للشباب المسلم في التثبت والركود في الحكم على الأمور؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1294,"question":"نرى أثناء عملنا كأطباء في العيادات بعض النِّساء المُتبرجات، فهل يجب علينا وجوبًا نصحهنَّ؟","title":"هل يلزم الطبيب نصحُ المُراجِعة المتبرجة؟","answer":"الجواب:\nنعم، يجب عليكم وعلى المدير وجوبًا النُّصح والمنع أيضًا، مَن له قدرة كالمدير عليه المنع، وأن يلبسن لباسًا ليس فيه تبرج، ويتسترن، ويحتجبن، ويعتنين بذلك حتى لا يَفتن ولا يُفتنَّ، هذا واجبٌ، تلبس لباسًا ليس فيه فتنة، وتكون تغطي وجهها: إما بالخمار وإلا بالبرقع، لا يظهر إلا العين، وتكون كذلك مُعتنيةً بيديها، ما يكون فيها ما يفتن الناس، ولا رجليها، أن تكون مستورةً، حتى تكون بعيدةً عن أسباب الفتنة.\nويجب على المسؤول الذي هو المدير ومَن ينوب عنه أن يمنعها من ذلك، وعلى الطبيب أن ينصحها، وأن يحذِّرها من هذا العمل، والله يقول: وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، تبرج الجاهلية:  إبداء بعض المحاسن: من رأسٍ، أو وجهٍ، أو صدرٍ، أو قدمٍ، أو غير هذا.","link":"https://binbaz.org.sa/fatwas/21343/هل-يلزم-الطبيب-نصح-المراجعة-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1086نرى نحن الأطباء بعض المتبرجات في العيادات فهل يجب علينا نصحهم؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1307,"question":"رجلٌ يقول: أنه يوجد في مجال عمله كفَّار من الهندوس والبوذيين والنَّصارى وغيرهم، فكيف يتعامل معهم في السلام والمُصافحة؟","title":"ما كيفية التعامل مع زميل العمل غير المسلم؟","answer":"الجواب:\nيتعامل معهم على الشريعة: لا يبدؤهم بالسلام، وإذا بدؤوا يردّ عليهم وينصحهم ويُعلِّمهم ويُوجِّههم إلى الخير، لما يسَّر الله له وجودهم يُوجِّههم إلى الخير، يدعوهم إلى الله، ويُعلِّمهم، يقول النبي ﷺ: مَن دلَّ على خيرٍ فله مثل أجر فاعله، ويقول ﷺ: لأن يهدي الله بك رجلًا واحدًا خيرٌ لك من حمر النعم. فإذا سلَّموا ردَّ عليهم، وإذا صافحوه صافحهم، لا يبدؤهم، ويقول له إذا رأى المصلحة في ذلك: كيف أولادك؟ كيف حالك؟ هداك الله، وفَّقنا الله وإياك، وما أشبه ذلك مما يُقربه إلى الخير. لكن لا يتَّخذهم أصحابًا، إنما يدعوهم إلى الله، ويُعلمهم بالكلام الطيب والرفق، والله يقول: وَقُولُوا لِلنَّاسِ حُسْنًا [البقرة:83]، ويقول جلَّ وعلا: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]، ويقول الله لموسى وهارون لما بعثهما إلى فرعون: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44]، ويقول سبحانه: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46]، وهم اليهود والنصارى، فلا بدّ من إحسان القول والرفق؛ حتى يَقْبل الحقّ، أو تُعْذِر إليه وتكون أديتَ ما عليك.","link":"https://binbaz.org.sa/fatwas/21362/ما-كيفية-التعامل-مع-زميل-العمل-غير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1105يوجد في مجال عملي كفار فكيف نتعامل معهم في السلام والمصافحة؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1412,"question":"بعض الجماعات الإسلامية تَدَّعي بأنها ملتزمة بالكتاب والسنة، وكلهم متفرقون؟","title":"ما ضابط الاجتماع وعدم التفرق بين الدعاة؟","answer":"الجواب:\nيُنصحون، على من يعرف حالهم من أهل العلم نُصْحُهم؛ حتى يجتمعوا على الحق. أما يكونوا أحزابًا وفِرَقًا ما يصلح.\nس: ما هو ضابط الاجتماع؟\nج: على الكتاب والسنة، إذا كانت دعوتهم كلهم على الكتاب والسنة لا يختلفون، هذا الضابط.","link":"https://binbaz.org.sa/fatwas/21507/ما-ضابط-الاجتماع-وعدم-التفرق-بين-الدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط الاجتماع على الكتاب والسنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1424,"question":"إذا كان بعض الناس يخالفون السُّنة هل يجب علينا أن ننصحهم؟ وكيف تكون النصيحة؟","title":"ما كيفية التعامل مع مَن يخالفون السُّنة؟","answer":"الجواب:\nالنصيحة بالرفق، تنصحه بالرفق، تُعَلِّمه، إذا رأيته يسبل إزاره تنصحه، رأيته ما يلعق أصابعه تُعَلِّمه، رأيت يأكل باليسار تُعَلِّمه، رأيته يفعل أشياء أخرى مما لا توافق الشرع تنصحه، لكن بالكلام الطيب والأسلوب الحسن، كما قال ربنا : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125].\nس: النصيحة هل تكون سرية أو جهرية؟\nج: على حسب الحال، إن كان عند الناس بينك وبينه، وإن كان بينك وبينه ترفع صوتك، وإن كنتم حول الناس تُسِرّ حتى لا تكون سببًا لرد النصيحة؛ حتى يكون أقْبَل للنصيحة.","link":"https://binbaz.org.sa/fatwas/21519/ما-كيفية-التعامل-مع-من-يخالفون-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع من يخالفون السنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1426,"question":"بعض الشباب ذُهِبَ إليهم ونُصحوا ووُجِّهوا بأن يدعوا إلى توحيد الله ، فغضبوا وحزنوا وضاقت صدورهم بنا، فهل حفظك الله نبقى معهم أم يُتركوا؟","title":"ما كيفية الدعوة الصحيحة لفئة الشباب؟","answer":"الجواب:\nيُعلَّمون ويُنصحون، فالتوحيد هو الأول، فإذا كان المسلمون على التوحيد يُعلمونهم ما يجهلون في صلاتهم، وفي صومهم.  أما إذا كانوا في أناسٍ عندهم شرك فيبدؤون بالتوحيد، يُعلِّمونهم التوحيد أولًا؛ لأن الأعمال ما تصحّ إلا بعد السلامة من الشرك. أما إذا كانوا مثل هذا المجتمع السعودي أو أشباهه –في مجتمع إسلامي طيب- فيدعونهم إلى ما يظنون أنهم قصَّروا فيه، أو يخفى عليهم، ويُنَبِّهونهم عليه إذا كانوا أهل توحيدٍ، يُنَبِّهونهم على الأشياء التي تخفى عليهم: في صلاتهم، في صومهم، في زكاتهم، في حجِّهم، في معاملاتهم، أما إذا كانوا في قومٍ كفار فيُبْدَؤون بالتوحيد، ويُحذِّرونهم من الشرك.\nس:... يقولون: أنتم تُنَفِّروننا وتُنَفِّرون غيرنا؟\nج: الدعوة إلى التوحيد ليست تنفيرًا إذا كانت في مجتمعٍ فيه شرك، هكذا دعا الأنبياء، بدؤوا بالدعوة إلى التوحيد، فالرسول ﷺ بدأ بالدعوة إلى التوحيد، وظلَّ عشر سنين كلها دعوة إلى التوحيد قبل أن تُفرض الصلاة.","link":"https://binbaz.org.sa/fatwas/21521/ما-كيفية-الدعوة-الصحيحة-لفىة-الشباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعوة إلى الله في المجتمع المسلم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1438,"question":"إذا كان هناك جماعة في اليمين تدعو إلى الله ، وجماعة أخرى في اليسار تدعو إلى الله ، ولكن اليمنى تَسُبّ اليسرى، واليُسرى تَسُبّ اليمنى، فما العمل عندئذٍ؟","title":"حكم الاختلاف والتفرُّق بين جماعات الدعوة","answer":"الجواب:\nالواجب نصيحتهم حتى يجتمعوا، وتحذيرهم من الفرقة، حتى يتفاهموا ويزول الإشكال، أما التناقض هذا فيُنَفِّر الناس من الدعوة، حتى يقول العامي: \"مَن معه الحقّ؟!\"، هذه فتنة! فالواجب الاجتماع والتعاون وإزالة الخلاف بالطرق الشرعية، فعلى العلماء وأهل الخير أن ينصحوهم ويتوسَّطوا بينهم؛ حتى يزول الخلافُ، وتكون الدعوةُ واحدةً.\nس: هل ينقاد لجماعةٍ دون أخرى؟\nج: إذا كان عنده علمٌ ينقاد للتي معها الحقّ، ويكون معها على الطائفة الأخرى حتى تستجيب.","link":"https://binbaz.org.sa/fatwas/21534/حكم-الاختلاف-والتفرق-بين-جماعات-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اختلاف الجماعات الداعية إلى الله وتحذير كل من الأخرى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1440,"question":"هل الواجب علينا العمل على إلغاء هذه الجماعات التي شتت الشملَ وصارت فوضى؟","title":"ما الموقف الصحيح من الجماعات المختلفة؟","answer":"الجواب:\nالواجب السعي في إلغائهم حتى يكونوا كتلةً واحدةً، وحتى تكون دعوتهم واحدةً، فعلى ولاة الأمور وعلى أهل الحل والعقد أن يتوسَّطوا بالطرق الشرعية حتى تجتمع كلمتُهم، وحتى يزول الخلافُ بينهم؛ لأنَّ الخلاف يضرّ المدعوين: لا يدرون مَن معه الحق؟!\nس: بالنسبة للجماعات التي تنتمي إلى الكتاب والسنة، والذي دخل الشيطانُ بينهم وافترقوا، كلهم يُعادون على حسب جماعتهم، ويُوالون على حسب جماعتهم، ثم يسُبّ بعضُهم البعض؟\nج: مثلما قلنا: الواجب على أهل العلم وعلى القادة أن يحلوا مشاكلهم، وأن يجمعوهم، ويُزيلوا ما بينهم من الإشكال، حتى تكون كلمتهم واحدةً، وإلا فهذا شرٌّ عليهم وعلى غيرهم، والله يقول: وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ وَأُولَئِكَ لَهُمْ عَذَابٌ عَظِيمٌ [آل عمران:105]، فلا بدّ من الاجتماع، يقول سبحانه: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103]، يجب الاجتماع والتعاون، ويجب على السلطة الحاكمة وعلى أهل العلم أن يبذلوا وسعهم في جمع الفرق، ثنتان أو ثلاث فرق أو أربع يجمعوهم حتى يُزيلوا الخلافَ الذي بينهم، حتى لا تكون شبهةً للجُهَّال.\nس: بالنسبة للاجتماع: كيف في مثل هذه الحالة للإنسان أن ينتمي إليهم؛ لأنَّه يكون هناك بغضٌ فيما بينهم، كل واحدٍ يبغض الثاني؟\nج: يجب أن ينتموا إلى الكتاب والسنة، للإسلام، لا ينتموا لزيدٍ ولا لعمرٍو، يجب أن يكونوا كلهم تبعًا للكتاب والسنة، وخَدَمًا للكتاب والسنة، ولا يتعصَّب لرئيسه، ويرحل لرئيسه، ولا يتشبَّهون بالمنافقين، أو بالخوارج، أو بالمعتزلة، لا، الواجب أن يكون هدفهم اتِّباع الكتاب والسنة، ليس لهم هدفٌ سوى هذا.\nس: أعني يا شيخ: الشخص الفردي من المسلمين إذا حصلت مثل هذه الحالة كيف يكون موقفه؟ هل ينتمي إلى الأولى أم إلى الثانية أم إلى الثالثة أو يكون محايدًا؟\nج: يسأل مَن يطمئن إليه حتى يعرف الحق، يسأل العلماء الذين يطمئن إليهم، ولو بالسفر من بلدٍ إلى بلدٍ، حتى يسأل: مَن الحق معه؟ ما هو الحق؟ ما هو الطريق؟ ما هو السبيل؟ حتى يُدَلَّ على الخير، لا بد أن يسأل.","link":"https://binbaz.org.sa/fatwas/21536/ما-الموقف-الصحيح-من-الجماعات-المختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الموقف من الجماعات المختلفة والمتفرقة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1469,"question":"كيف يمكن التوفيق بين هذه الأشياء وما يجري في عالمنا الإسلامي الآن من القتل والضرب والحقد؟","title":"ما علاج غُربة الإسلام وما يقع من فتن؟","answer":"الجواب:\nهذا من غربة الإسلام.\nس: ما العلاج؟\nج: العلاج التناصح، والتعاون على البر والتقوى بين المسلمين، وبين دعاة الحق، وبين أهل العلم، وبين العقلاء، هذا هو الواجب؛ فالله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]. وكان بين الأوس والخزرج دماءٌ عظيمة ووحشة وقتال، فلمَّا هداهم الله للإسلام وتعاونوا على البِرِّ والتقوى؛ أزال ذلك بسبب ما أعطاهم الله من الإيمان والهدى والتقوى، وهكذا بين العرب، فالقبائل يغزو بعضُها بعضًا، ويقتل بعضُها بعضًا، فلمَّا هداهم الله للإسلام وعرفوا تحريم ذلك؛ كفَّ بعضُهم عن بعضٍ. فلا علاج لهذا إلا بالدين، فإذا فقدوا الدين جاءت الكوارث، وجاء البلاء -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/21566/ما-علاج-غربة-الاسلام-وما-يقع-من-فتن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/غربة الإسلام وعلاجها.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1588,"question":"إنكار المنكر: رجلٌ في سيارةٍ يمرُّ على ناسٍ يُدَخِّنون ويُنكر عليهم وهو ماشٍ؟","title":"كيفية إنكار المنكر ممن رآه أثناء قيادة سيارته","answer":"الجواب:\nجزاه الله خيرًا، يقول: ترى هذا ما يجوز، ترى هذا مُحَرَّم.\nس: لا يؤشِّر لهم؟\nج: لا، يُنبههم ويُوضِّح الأمر، فيقف عليهم ويقول: يا إخواني، ترى هذا ما يجوز، ترى أنَّ الدخان محرَّم، مثلما يقول لهم: الغيبة محرمة، ومثلما يقول لهم: الخمر محرَّم، فيُبَيِّن لهم، ما هو خاطفٌ، لا بدّ أن يثبت ويقف ويُلاحظهم ويُعلِّمهم.","link":"https://binbaz.org.sa/fatwas/21691/كيفية-انكار-المنكر-ممن-راه-اثناء-قيادة-سيارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار على من يأتي منكرا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1600,"question":"كيف يدعو الرجلُ والديه؟","title":"كيف يدعو الرجل والديه إن كانا عاصيين؟","answer":"الجواب:\nيا أبتي، يا أماه، يا أبا عبدالله، يا أبا فلان، يا أبتاه، يا أماه، يا أم عبدالله، يا أم محمد.\nس: أبواه عاصيان ويريد دعوتهما للهداية؟\nج: يقول: اتَّقِ الله، افعل كذا، دعْ عنك كذا، وينصح: يا أبتِ إن هذا لا يجوز، مثلما قال إبراهيمُ، فينصح والديه: يا أبتِ افعل كذا، يا أبتِ دَعْ عنك كذا، يا أبتِ حافظ على الصَّلوات، فالصلاة عمود الدين، يا أبتِ احذر الدخان، احذر المُسْكِر، احذر الإسبال، فكلّ هذه محرَّمات، وما أشبه ذلك.\nس: يزعل؟\nج: ولو زعل، لكن بالعبارات الحسنة وباللّطف، قُلْ لهما قولًا لينًا.","link":"https://binbaz.org.sa/fatwas/21704/كيف-يدعو-الرجل-والديه-ان-كانا-عاصيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يدعو الرجل والديه إن كانا عاصيين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1627,"question":"مَن له رَحِمٌ ويستغيث بالقبور هل يزوره؟","title":"ما حكم صلة وزيارة مَن يستغيث بالقبور؟","answer":"الجواب:\nإذا كان في وقت أمانٍ وليس بيننا وبينهم حربٌ؛ يُعلِّمه الدِّين وينصحه.\nس: رجل مسلم يزور القبورَ له رَحِم؟\nج: ينصحه، لا يتَّخذه صاحبًا، ينصحه ويُعلِّمه الدين.","link":"https://binbaz.org.sa/fatwas/21732/ما-حكم-صلة-وزيارة-من-يستغيث-بالقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلة من يستغيث بالقبور.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1771,"question":"المعاصي المنتشرة مثل: شرب الدخان، لو يهجر الناس لهذه المعصية؟","title":"حكم هجران من يشرب الدخان ونحوه","answer":"الجواب:\nلا، هذه فيها شبهة، الدخان فيه شبهة، لكن يُنصح من باب النصيحة. أما المعاصي الظاهرة :كشرب الخمر، الزنا، اللواط، الشيء الظاهر الذي ما فيه شبهة؛ يُهجر، وإذا رأى المصلحة في عدم الهجر وأنه يتابع النصيحة فلا بأس، فالنبي ﷺ هجر أقوامًا ولم يهجر أقوامًا، فإذا رأى وليُّ الأمر أو طالبُ العلم أو المؤمنُ أنَّ الهجر يزيد الشرَّ لا يهجر، يستمر في النصيحة، ويُحْمَل ما فعله النبيُّ ﷺ على هذا، فالناس الذين تركهم ولم يهجرهم كان ذلك لأنه رأى أنَّ عدم هجرهم أقرب إلى الخير، فإذا كان الهجر ينفع ويُؤَدِّب ويحصل به المطلوب هجر، فعليه أن يُراعي المصالح والمفاسد، ما هو بالهوى.","link":"https://binbaz.org.sa/fatwas/21878/حكم-هجران-من-يشرب-الدخان-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم هجران من يجاهر بالدخان ونحوه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1866,"question":"مؤاكلة صاحب المنكر ومُشاربته والاستمرار في ذلك مع الاستمرار في الإنكار عليه؟","title":"ضابط مجالسة صاحب المنكر مع الإنكار عليه","answer":"الجواب:\nلا، الواجب على الأقل هجره؛ لأنك إذا واكلته وشاربته ضعف الإنكار، وتساهل معك، ولم يُبالِ؛ لكن مع الإنكار: تَرْك المجالسة.\nس: وإذا كان الإنكارُ في مجلسه دائمًا؟\nج: الإنسان إذا أنكر المنكر لا يكون جليسًا لصاحبه ولا أكيلًا له، أما المجلس العام فلا يضر، في المجلس العام إذا أنكرت المنكر ما يضرك.\nس: إذن الهجر أوْلى؟\nج: إذا اقتضت المصلحة ذلك، وإذا كانت المصلحة تقتضي متابعة الدعوة تُتابع، لكن لا تكون جليسًا له، تتابع الدعوة والإنكار؛ لعل الله ينفع بذلك.\nس: إذن يكون هجرُ العباد لكل حالةٍ بحسبها؟\nج: نعم، بحسب المصلحة الشرعية.\nس: إذا كان في بيتٍ واحدٍ والأب لا ينكر الإنكار المطلوب، مثلًا: مجموعة إخوان بعضهم صالحون؟\nج: الصالح يُنكر على الطالح ولو ما أنكر الأب، الأخ الطيب ينكر على أخيه الذي باشر المعصية، يُنكر عليه ويُوجِّهه إلى الخير.\nس: ولكن بعض الصالحين يستطيعون الانفراد ببيتٍ مستقلٍّ وآخرين لا يستطيعون؟\nج: يُنكر حسب طاقته، ولو بقي في البيت، إذا رأى المصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/21975/ضابط-مجالسة-صاحب-المنكر-مع-الانكار-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مؤاكلة ومُشاربته صاحب المنكر مع الإنكار عليه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1870,"question":"كيف يكون الإنكار باللسان؟","title":"كيف يكون الإنكار باللسان واليد؟","answer":"الجواب:\nالإنكار باللسان تقول: اتَّقِ الله، هذا لا يجوز، راقب الله، هذا الإنكار باللسان. وباليد: إذا كانت \"ملاهي\" تكسرها، صورة تكسرها، اجتماع على باطلٍ تُفرِّقه إذا كنت تقدر، مثل صاحب البيت، ومثل رجل الحسبة، ومثل الأمير، فهؤلاء لهم قدرة.","link":"https://binbaz.org.sa/fatwas/21979/كيف-يكون-الانكار-باللسان-واليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار باللسان كيف يكون.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1872,"question":"إذا أنكر بقلبه ولم ينكر بلسانه ولا بيده، هل يكون بريئًا من الإثم؟","title":"هل يكفي الإنكار بالقلب عن اللسان واليد؟","answer":"الجواب:\nإذا كان عاجزًا عن اليد واللسان بَرِئ، أما إذا كان يقدر ما يبرأ.","link":"https://binbaz.org.sa/fatwas/21981/هل-يكفي-الانكار-بالقلب-عن-اللسان-واليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبرأ من أنكر بقلبه ولم ينكر بلسانه ولا بيده.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1874,"question":"كثر حُلَّاق اللحى يمنةً ويسرةً، فهل يُنكر على كلِّ حالق لحيةٍ، أم كل بحسبه؟","title":"كيف يكون الإنكار في حال تفشي المنكر؟","answer":"الجواب:\nأما سمعت الحديث: مَن رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه؟ كل بحسب طاقته، الأمير له شأن، والعالم له شأن، وربّ البيت له شأن، والجيران فيما بينهم لهم شأن، كل على حسب طاقته.","link":"https://binbaz.org.sa/fatwas/21983/كيف-يكون-الانكار-في-حال-تفشي-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار في حال تفشي المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1878,"question":"ما الفرق بين الدعوة إلى الله والأمر بالمعروف والنهي عن المنكر؟","title":"ما الفرق بين الدعوة والأمر بالمعروف؟","answer":"الجواب:\nكلها دعوة إلى الخير، والأمر بالمعروف والنهي عن المنكر فيه إلزام، وهو أشد وأقوى.","link":"https://binbaz.org.sa/fatwas/21987/ما-الفرق-بين-الدعوة-والامر-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الدعوة إلى الله والأمر بالمعروف والنهي عن المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1879,"question":"بالنسبة للكتيب أو الشريط هل يقوم مقام النصيحة المباشرة؟","title":"هل يقوم الكتيب والشريط مقام النصيحة؟","answer":"الجواب:\nنعم، الشريط الطيب ينفع الله به، إذا وزَّعه على الناس من أهل العلم المأمونين، طيب، هذه نصيحة.","link":"https://binbaz.org.sa/fatwas/21988/هل-يقوم-الكتيب-والشريط-مقام-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعدد أساليب الدعوة إلى الله.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1880,"question":"إنكار المنكرات المُعلنة هل يُشترط فيه الإسرار كما يُشترط في النصيحة، أم أنَّ المنكر المُعْلَن يُنكر علنًا دون إسرار؟","title":"ما كيفية إنكار المنكرات العامة المُعْلَنة؟","answer":"الجواب:\nإذا كان بين الناس يُنْكَر علنًا، أما بينك وبين صاحبه الذي كان منه تتكلَّم بينك وبينه، تنصحه، أما إذا فعله عند الناس فيُبَيَّن عند الناس أنَّ هذا منكر ولا يجوز، حتى لا يغتَرَّ به أحدٌ، أما إذا رأيتَه يفعل المنكر فعليك أن تنصحه بينك وبينه، إذا رأيته وحده تقول له: يا عبدالله، هذا منكر. ونحو هذا الكلام الطيب، والأسلوب الحسن، والرفق، كما قال ربك: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، لكن إذا كان يفعله عند الناس تُبين له أنَّ هذا منكر، وأنه لا يجوز هذا العمل، مثل: مَن يشرب الدخانَ عند الناس، ومَن يشرب الخمر عند الناس، سبَّاب، لعَّان، يُنكر علنًا.\nس: المقصود المنكرات العامة المُعْلَنة، هل تُنكر علنًا؟\nج: نعم تُنكر علنًا، ما دامت مُعلنةً تُنكر علنًا.\nس: ما يُشترط فيها الإسرار؟\nج: يبين للناس أنها مُنكرة، الذي يُجاهر في الأسواق بالمنكرات يُنكر عليه.","link":"https://binbaz.org.sa/fatwas/21989/ما-كيفية-انكار-المنكرات-العامة-المعلنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية إنكار المنكرات العامة المعلنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1882,"question":"هل هذا (الأمر بالمعروف والنهي عن المنكر) يدخل في أنواع الدعوة إلى الله؟","title":"هل الأمر بالمعروف من الدعوة إلى الله؟","answer":"الجواب:\nلا شكَّ أنَّ من الدعوة إلى الله: الأمر بالمعروف والنهي عن المنكر، فعطفها في قوله جل وعلا: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ .. [آل عمران:104] هذا من عطف الخاص على العام، فالذي يدعو إلى الله، أو يأمر بالمعروف، أو ينهى عن المنكر، ثم يخالف قوله ما يدعو إليه داخل في هذا الوعيد -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21991/هل-الامر-بالمعروف-من-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأمر بالمعروف والنهي عن المنكر من أنواع الدعوة إلى الله.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1883,"question":"أيّهما أخفّ: ترك الإنكار على النفس والإنكار على الناس، أم الإنكار على الناس وعدم الإنكار على النفس؟","title":"كيف يكون الإنكار على النفس وعلى الناس؟","answer":"الجواب:\nيجب على المؤمن إنكار المنكر على نفسه وعلى غيره، إذا رأى المنكر يُجاهد نفسه حتى يدع المنكر، ويجاهد غيره في ترك المنكر، يعني: يكون نشيطًا في محاربة المنكر من جهة نفسه حتى يستقيم على الحقِّ، ومن جهة دعوة الناس إلى الخير وإرشادهم وأمرهم بالمعروف ونهيهم عن المنكر، يجمع بين الأمرين.\nس: إذا علم من نفسه نَتَنَها وخُبْثَها وأنه إذا أنكر على الناس لم يُنكر على نفسه؟\nج: يجاهد نفسه، عليه المجاهدة: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنْكُمْ .. [محمد:31]، لا بدّ من مجاهدة النفس حتى تلتزم أمر الله.\nس: يأمر بالمعروف ثم لا يأمر الناس بصلاة الفجر ويترك صلاة الفجر؟\nج: الباب واحد، أو يأمر الناس بالبعد عن الخمر ويشرب الخمر، أو ينهى الناس عن التدخين ويدخن، أو ينهى الناس عن حلق اللحى ويحلق، الباب واحد، هذا منكر واحد، وفضيحة عليه -نسأل الله العافية- وتشبُّه بأعداء الله من اليهود وأشباههم.\nس: يُجاهد نفسه في تقصيره مع أنه مُقصِّرٌ ويأمر الناس؟\nج: يأمر الناس ولو قصَّر، ويستحي ويجاهد نفسه لعله لا يبرز بشيءٍ منكر، ولا يقل: أنا لا آمر ولا أنهى لأن عندي معصية. لا، يأمر وينهى ولو عنده معصية، ويجاهد نفسه؛ لعل الله يتوب عليه.","link":"https://binbaz.org.sa/fatwas/21992/كيف-يكون-الانكار-على-النفس-وعلى-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في إنكار المنكر على النفس وعلى الناس.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2018,"question":"الشورى لولي الأمر تكون مُلْزِّمة أو مُعَلِّمة؟","title":"هل الشورى مُلْزِّمة أو مُعَلِّمة؟","answer":"الجواب:\nلا...، واجبة، الله يقول: وَأَمْرُهُمْ شُورَى بَيْنَهُمْ [الشورى:38]، ويقول وَشَاوِرْهُمْ فِي الْأَمْرِ [آل عمران:159] إذا اشتبهت الأمور يعني. أما إذا كان في نص لا يحتاج اشتباه الأمور، لو درى عمر عن حديث عبدالرحمن بن عوف ما شاور الناس، واضح، الشورى في الأمور المشتبهة.","link":"https://binbaz.org.sa/fatwas/22134/هل-الشورى-ملزمة-او-معلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الشورى ملزمة أو معلمة.mp3","categories":["السياسة الشرعية","قضايا معاصرة"]},{"id":2102,"question":"رجل شُكِيَ أمرُه إلى الهيئة بعد أن دُعي باللين فبعدها أرسل أهله إلى الدَّاعي وقال: إن رفعت الدَّعوى أو الشكوى إلى الهيئة فسترى بماذا يُعاقب. فهل هذا يُترك لأنَّ المنكر سيَؤُول إلى منكرٍ أم يُستمر في الإنكار عليه؟","title":"هل يترك الإنكار على مَن يُخشى أذاه؟","answer":"الجواب:\nلا، يُنصح، عليه النصيحة مع الجماعة جيرانهم، فالجيران لا يسكتون عن حاله، فيتعاونون على نصيحته وتوجيهه إلى الخير حتى لا تقع فتنة..... على كل حال، إذا كان يخشى أو يظن أنه قد يفعل؛ يسقط عنه الواجب، لكن في مثل هذا يكون من جماعةٍ أحسن، لعله ينتبه، ولعله يستفيد، فإذا كان من جماعة فهو أقرب إلى النّجاح.","link":"https://binbaz.org.sa/fatwas/22220/هل-يترك-الانكار-على-من-يخشى-اذاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أدى إنكار المنكر إلى منكر أشد.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2208,"question":"إذا لم يكن يعرف حال الجيران هل يعتزلهم ثم يدرس أحوالهم قبل مُخالطتهم؟","title":"حكم مخالطة الجيران إذا لم يُعرف حالهم","answer":"الجواب:\nيدرس أحوال المجتمع وينظر في المصلحة، فإذا اقتضت المصلحةُ وعظهم وتذكيرهم ومخالطتهم فعل ذلك، وإذا رأى أنَّ المصلحة تقتضي اعتزالهم اعتزلهم، فعليه أن ينظر إلى الأمر الذي وقع بالناس، فالناس في حاجةٍ إلى التّوجيه والإرشاد والتعليم، والأمر بالمعروف والنّهي عن المنكر، لكن إذا لم يكن في المسألة حيلة فليعتزل.","link":"https://binbaz.org.sa/fatwas/22331/حكم-مخالطة-الجيران-اذا-لم-يعرف-حالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مخالطة الجيران إذا لم يكن يعرف حالهم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2217,"question":"المُتَكَبِّر كيف يتواضع معه المُتواضع؟","title":"كيف يكون التعامل مع المُتَكَبِّر؟","answer":"الجواب:\nيُجاهد نفسه في التّواضع.\nس: أقصد: كيف يتعامل المُتواضع مع المُتكبر؟\nج: ينصحه ويُوجهه إلى الخير.\nس: لكن يستمر في تواضعه حتى مع المُتكبر؟\nج: نعم، مع كلِّ أحدٍ، وينصحه.\nس: بعض الناس إذا نصحته قال: عليك بنفسك؟\nج: ولو، قل له: عليَّ بنفسي، وعليَّ بك، أنا مأمورٌ بك، فالله جلَّ وعلا يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فأنا مسؤولٌ عنك.","link":"https://binbaz.org.sa/fatwas/22340/كيف-يكون-التعامل-مع-المتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع المتكبر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2261,"question":"كيف يكون الجمعُ بين أن يرى منكرًا فينتقم لله ، وأن يُنْكِر بالحكمة واللّين والموعظة الحسنة؟","title":"كيف يُجمع بين الرفق وبين الانتقام لله تعالى؟","answer":"الجواب:\nيُنكر بالحكمة، وهذا من الغضب لله: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، لا يسكت، أما إذا كان في حقِّ نفسه فلا بأس أن يُسامح ويسكت.","link":"https://binbaz.org.sa/fatwas/22384/كيف-يجمع-بين-الرفق-وبين-الانتقام-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الانتقام لله وإنكار المنكر بالحكمة واللين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2288,"question":"مَن قال: \"إنَّ أشرف وظيفةٍ على وجه الأرض هي وظيفة الرسل، وهي الدَّعوة إلى الله، وليست المراتب وغيرها\"، فهل يُعتبر هذا من إهانة الأمير؟","title":"هل اعتبار الدعوة أشرف وظيفة إهانة للأمير؟","answer":"الجواب:\nلا، ليست إهانةً، فدعوة الرسل لا شكَّ أنها مهمةٌ جدًّا عن الأمراء والعلماء، ودعوة الرسل واجبةٌ على الأمراء والعلماء جميعًا، فهي واجب الجميع.","link":"https://binbaz.org.sa/fatwas/22411/هل-اعتبار-الدعوة-اشرف-وظيفة-اهانة-للامير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أشرف وظيفة وظيفة الرسل الدعوة إلى الله فهل يُعتبر هذا من إهانة الأمير.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2333,"question":"إذا فرح الإنسانُ ببَلْوَى تُصيب مسلمًا بقضاء الله؛ لأنَّه شديد الأذى والتَّمرد والمعاصي؟","title":"حكم الفرح بالبلاء يصيب مسلمًا شديد الأذى","answer":"الجواب:\nهذا ينصح له، ويُوجِّهه إلى الخير، يقول له: اتَّقِ الله، يقول الله: وَالْعَصْرِ ۝ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر]، ويقول النبيُّ ﷺ: الدين النَّصيحة، فإذا علم من أخيه نَقْصًا نصحه ووجَّهه إلى الخير بالأسلوب الحسن.\nس: إذا كان يرفض كلَّ أنواع النَّصيحة؟\nج: ولو، هذا الذي عليك: النصيحة، فإن قَبِلَ وإلا فقد أدَّيْتَ ما عليك.\nس: وإذا كان يستخدم هذه النّعم في الشر والمعاصي؟\nج: تدعو له بالهداية.","link":"https://binbaz.org.sa/fatwas/22457/حكم-الفرح-بالبلاء-يصيب-مسلما-شديد-الاذى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرح ببلاء أصاب مسلما شديد الأذى والتَّمرد والمعاصي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2518,"question":"مَنْ له جيران لا يصلون إلا في رمضان؟","title":"ما يفعل مَنْ له جيران لا يصلون إلا برمضان؟","answer":"الجواب: إذا كان له جيران لا يصلون إلا في رمضان أو في بعض الأوقات يُنكر عليهم ويعلّمهم وينصحهم، فإن أبوا يرفع بأمرهم إلى الجهات المختصة –الهيئة- حتى تقوم بالواجب، لكن بعد النصيحة. وإذا تيسر يذهب إليهم مع بعض إخوانه؛ لأن الواحد قد لا يبالون بذلك، إذا كانوا جماعة اثنين ثلاثة يجتمعون ويذهبون وينصحون، قد يكون يعني عملهم أشد أثرًا وأنفع، فيشوف بعض إخوانه يذهب إليهم ينصحهم يوجّههم يخوّفهم من الله حتى يصلوا مع الناس لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وقوله ﷺ للأعمى لما استأذنه قال ليس له قائد يقوده إلى المسجد، فهل له من رخصة يصلي في بيته؟ فقال النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم: قال: فأجب فالواجب على من يسمع النداء أن يجيب، وأن يحضر مع المصلين ويصلي في المسجد مع الناس، ولا يجوز التخلف عن ذلك ولا التشبُّه بأعداء الله المنافقين، لكن من فعل ذلك فقد أعلن المعصية، فلا بدّ ترفع بأمرهم إذا لم تنفع النصيحة، والله يصلح أحوال المسلمين جميعًا.","link":"https://binbaz.org.sa/fatwas/22648/ما-يفعل-من-له-جيران-لا-يصلون-الا-برمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جيرانه لا يصلون إلا في رمضان.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2545,"question":"إنكار القلب هل يمنع حدوث العقاب العام؟","title":"هل يمنع إنكار القلب حدوث العقاب العام؟","answer":"الجواب: ما يكفي، لا بدّ من إنكاره بالفعل والقول مع القدرة، أما الذي ما يقدر يكفيه القلب.\nس: هذا يمنع العقوبة؟\nالشيخ: عنه هو، العقوبة عنه هو، يعني ما يُعاقب يوم القيامة، لكن تَعُمُّه العقوبات العامة.\nس: الذي يستطيع يغيّر بلسانه وغيّر بقلبه، لو عُذّب هل يشمله العذاب؟\nالشيخ: قد تَعُمُّه العقوبات ويُبعثون على نيّاتهم وعلى أعمالهم الطيبة.\nس: لكن لو كان يستطيع يغيّر هذا المنكر بلسانه؟\nالشيخ: يستحق العقاب، إذا لم يفعل يستحق، نسأل الله العافية.\nس:... الإنكار العلني، القلب ما يكفي؟\nالشيخ: نعم.\nس: القلب ما يكفي؟\nالشيخ: لا، القلب حَدُّه بس النجاة إذا كان عاجزًا.","link":"https://binbaz.org.sa/fatwas/22676/هل-يمنع-انكار-القلب-حدوث-العقاب-العام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمنع إنكار القلب حدوث العقاب العام.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2690,"question":"إذا كان أحدُ المسلمين أخوه في الله أو قريبه يتهجم عليه دائمًا ويسبُّه ويغلط عليه بدون سبب، فكلما قاطعه ورجع إليه تكرر منه هذا، فهل يستمر في المقاطعة إنْ لم يُجْدِ معه الطِّيب؟","title":"حكم قطيعة القريب المؤذي بعد نصحه","answer":"الجواب: إن تيسرت النصيحة فهو أوْلى، يناصحه لعل الله يهديه، فإذا كان الاتصال به يفضي إلى شر؛ فلا يتصل به والحمد لله، إذا كان رجلًا لئيمًا فاسقًا لا يبالي ولا ينفع معه النصيحة؛ يقطع، الحمد لله، أقل أحواله السُّنِّية.\nس: ولا يعتبر من الشحناء؟\nالشيخ: لا لا، ما فيه شيء، هو الظالم.","link":"https://binbaz.org.sa/fatwas/22829/حكم-قطيعة-القريب-الموذي-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قريبه يؤذيه فقاطعه فنصحه فزاد في إيذائه ولم يجدِ معه الطيب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2750,"question":"رجل أندنوسي يريد الدخول في الإسلام هل يَجِدُّ الأخوة في إدخاله في الإسلام وإنهاء إجراءاته أم يتثبتون من حاله؟","title":"هل يجب التَّحقق من قصد من أراد أن يُسْلِم؟","answer":"الجواب: ينبغي أن يُسارع في مساعدته وتشويقه للإسلام وترغيبه وتسهيل أمره من باب التعاون على البر والتقوى.\nس: ولا يفتش عن النوايا؟\nالشيخ: لا، أمره إلى الله، ينبغي أن يُحمل على أحسن المحامل؛ تشجيعًا للدخول في الإسلام.","link":"https://binbaz.org.sa/fatwas/22898/هل-يجب-التحقق-من-قصد-من-اراد-ان-يسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد الدخول في الإسلام فهل يحمل على أحسن المحامل أو يتثبت.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2772,"question":"ضابط إظهار الدين أن إذا قابل من أهل تلك البلاد يقول: أنتم كفار؟","title":"كيف يكون إظهار الدين في بلاد الكفار؟","answer":"الجواب: إظهار الدين: كونه يصلي ويصوم ويدعو إلى الله ويأمر بالمعروف ويعلم الناس الخير، يعلم الناس التوحيد، ويعلم الناس الشرك، وما هو بلزوم يقول للناس: أنتم كفار، يدعو إلى الله وبس ويكفي، هذا إظهار الدين.","link":"https://binbaz.org.sa/fatwas/22920/كيف-يكون-اظهار-الدين-في-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط إظهار الدين في بلاد الكفار.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2813,"question":"بعض أشرطة الدعاة مؤثرة وكانت سببًا في هداية عدد كبير بعد سماعهم الشريط، هل يشترك في الأجر موزع الشريط ومحل التسجيلات كمثل الذين يدخلون بالسهم الواحد الجنة؟","title":"مَنْ يدخل في أجر الشريط والوسائل الدعوية؟","answer":"الجواب: الأقرب -والله أعلم- أن صاحب الشريط على أجره، والذي يوزعه على الناس له أجره، كلهم دعاة خير، إذا كان شريطًا صالحًا مفيدًا، فصاحبه على أجر والموزع له مثل الذي ينشر الكتب وينقل المحاضرات إلى الناس، يكتبها ويوزعها على الناس، شركاء في الأجر.","link":"https://binbaz.org.sa/fatwas/22962/من-يدخل-في-اجر-الشريط-والوساىل-الدعوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كانت هدايته بسبب بعض أشرطة الدعاة المؤثرة فهل يحصل الأجر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2816,"question":"الدعوة تكون للأقرب فالأقرب؟","title":"هل تجب الدعوة للأقرب فالأقرب أو عامة؟","answer":"الجواب: مع الأقرب، ومع غيرهم، لكن إذا بدأ بالأقرب هذا من أهم المهمات، لكن لا يمنعه هذا من كونه لا يدعو إلى الله ولو الأبعدين إذا انتهز الفرصة، إذا تيسّر له أن يدعو.","link":"https://binbaz.org.sa/fatwas/22965/هل-تجب-الدعوة-للاقرب-فالاقرب-او-عامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكون الدعوة للأقرب فالأقرب أو عامة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2845,"question":"الآمرون بالمعروف والناهون عن المنكر يعتبرون من المجاهدين؟","title":"هل يُعَدُّ الآمرون بالمعروف مِن المجاهدين؟","answer":"الجواب: ما في شك؛ جِهادٌ عظيم.","link":"https://binbaz.org.sa/fatwas/22998/هل-يعد-الامرون-بالمعروف-من-المجاهدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعتبر الآمر بالمعروف والناهي عن المنكر مجاهدا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3062,"question":"إذا كان منكر يمكن تغييره: كثير من الناس يترك المنكر يقول: أنا ما أبلّغ عن فلان؟","title":"ما حكم تبيلغ ولي الأمر بالمنكر لتغييره؟","answer":"الجواب: إذا كان يستطيع يجب عليه، إذا كان يستطيع تغيير المنكر يجب عليه: لإمرته. أو لأنه هيئة. أو لأنه صاحب البيت.  أو ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/23222/ما-حكم-تبيلغ-ولي-الامر-بالمنكر-لتغييره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبلغ ولي الأمر بالمنكر الذي يمكن تغييره.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3283,"question":"بالنسبة للكفّار الذين يكونون في بلاد المسلمين: مدى إظهار العزة في مقابلهم، هل هو العبوسُ في وجوههم؟","title":"هل مِنْ عِزة المؤمن العبوسُ في وجه الكفّار؟","answer":"الجواب: لا، لا.\nس: أوْ لهم حكم المُسْتأمنين؟\nالشيخ: تَضطرُّهم إلى أضيق الطريق ولا تبدأهم بالسلام بس، هذا يكفي، وإن بدؤوا رددت عليهم.\nس: هل يُعَبِّس في وجوههم؟\nالشيخ: لا، لا يُعَبِّس في وجوههم ولا يُغَيِّر شيئًا، يدعوهم إلى الله، دعوتهم إلى الله من باب الخير، لكن لا يبدأهم، وإذا رأى أن يبدأهم: كيف حالك؟ كيف أنت يا فلان؟ كيف أولادك؟ لعلهم يقبلون إلى الخير ؛ طيب.\nس: لكن مَنْ عُرِف منه الصُّدود؟\nالشيخ: الذي عرف منه الصدود يُنصح فلا يصير خيرًا منك، أنت صِرْ خيرًا منه بالدعوة إلى الله والتوجيه إلى الخير والنصيحة، فأنت على أجر.","link":"https://binbaz.org.sa/fatwas/23447/هل-من-عزة-المومن-العبوس-في-وجه-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من إظهار عزة المؤمن أمام الكفار العبوس في وجوههم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3285,"question":"هل من التَّسَتُّر مثلًا إذا رأيت شخصًا يفعل منكرًا ألا تُفَضِّح أمره، أي تسكت عنه؟","title":"متى يُشرع السِّتر أو الكشف عمّن أتى منكرًا؟","answer":"الجواب: إذا كان في صلة خاصة سرية يُسْتَر عليه ويُنْصَح.  أما إذا كان بين الناس فهو الذي فضح نفسه.  أما إذا كان دخلت عليه في بيته أو في محل خاص ورأيته؛ تَسْتُر عليه وتنصحه.","link":"https://binbaz.org.sa/fatwas/23449/متى-يشرع-الستر-او-الكشف-عمن-اتى-منكرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من التستر عدم فضح أمر العاصي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3308,"question":"بعض الناس إذا مَرَّ بحَلِيق أو مدخّن لم يسلّم عليه؟","title":"حكم السلام على العصاة والجلوس معهم","answer":"الجواب: المشروع أنه يسلّم ويعلّمه وينصحه ويوجهه إلى الخير، ويعلمه ما جَهِل. س: يعني ما يمنع أنه يسلّم...؟ الشيخ: يسلم، وينصحه من عرفت ومن لم تعرف، يقول: يا أخي ترى هذا ما يجوز، والواجب عليك إعفاء اللحية، الواجب عليك ترك التدخين، ترك شرب المسكر. س: كثرة يا شيخ.. يتيسر له الوقفة مع كل واحد؟ الشيخ: حسب الطاقة، حسب الطاقة. س: لكن السلام؟ الشيخ: الظاهر يسلّم، ولَوْ من عرفت ومن لم تعرف؛ عموم، لأنه قد يكون جاهلًا ما قام عليه الحجة. س: لكن يأثم لو جلس معهم من دون نصح؟ الشيخ: هو الذي يظهر، إذا كان جالس أهل المنكر ولم يَنْهَهُم شريكٌ لهم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23474/حكم-السلام-على-العصاة-والجلوس-معهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السلام على العاصي والجلوس معه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3443,"question":"التجسس على أهل الريب، إذا عُلم أن هذا البيت يشتبه فيه خنا، وفيه خمور، أو غيره؟","title":"حكم التجسُّس على أهل الرِّيَب","answer":"الجواب: الظاهر أنه لولي الأمر أن يتعاهد المسؤولين إذا عرف بالأمارات، والعلامات حتى يزال..... من جنس ما جرى لابن صَيّاد، ولحماية المسلمين من الشر، والفساد، وليس من التجسس إذا عرف ذلك بالبيّنات، أو بالأمارات الظاهرة؛ لأن هذا فيه وقاية المسلمين من شرهم، والقضاء على أسباب الفساد.\nس: الرَّيب أو الرِّيَب؟\nالشيخ: الرِّيَب جمع ريبة، التهم يعني.","link":"https://binbaz.org.sa/fatwas/23618/حكم-التجسس-على-اهل-الريب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التجسس على أهل الريب.mp3","categories":["السياسة الشرعية","قضايا معاصرة"]},{"id":3921,"question":"إذا كان الإنسان بسبب الأمر بالمعروف والنهي عن المنكر يسبون والديه؟","title":"حكم مَنْ يؤدي أمرُه بالمعروف لسبِّ والديه","answer":"الجواب: ما يضر، الأمر بالمعروف والنهي عن المنكر ولو سبوا، الإثم عليهم.","link":"https://binbaz.org.sa/fatwas/24139/حكم-من-يودي-امره-بالمعروف-لسب-والديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل تتعلق بحديث إنّ من أكبر الكبائر أن يلعن الرجل والديه..mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3961,"question":"إذا رأى منكرًا عند المضيف ينصحه؟","title":"ما الحكم لمن رأى منكرًا عند المضيف؟","answer":"الجواب: ينصحه نعم. إذا رأى منكرًا عنده ينصحه، مثل ما نصح سلمان أبا الدرداء.","link":"https://binbaz.org.sa/fatwas/24188/ما-الحكم-لمن-راى-منكرا-عند-المضيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا رأى منكرًا عند المضيف.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4003,"question":"هل يجوز للمسلمين مخالطة المشركين واليهود؟","title":"هل يجوز للمسلم مخالطة المشركين واليهود؟","answer":"الجواب: إذا كان للمصلحة، للدعوة.","link":"https://binbaz.org.sa/fatwas/24236/هل-يجوز-للمسلم-مخالطة-المشركين-واليهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلمين مخالطة المشركين واليهود.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4004,"question":"بعض العصاة إذا نُصح أو أُمر يقول لمن نصحه: عَلّم في المسجد؟","title":"حكم من لم يقبل النصيحة وكيف يُعامل؟","answer":"الجواب: هذا من جنس عمل المنافقين، يُنكَر عليه، ويُعلّم: لا يجوز لك هذا الكلام، الله يقول سبحانه: وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ [البقرة:206] الواجب أنه يقبل الحق، ويقول: جزاك الله خيرًا، إن شاء الله أو أسأل الله أن يعينني، أسأل الله أن يغفر لي أو يوفقني.  هكذا ينبغي لمن وُعظ، ولا يرد بالكلام السيئ، أو يقول خل عنا دينك، أو رح المسجد علم، كل هذا مكابرة ومصادمة للحق، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24237/حكم-من-لم-يقبل-النصيحة-وكيف-يعامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أساليب العصاة عند النصيحة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4104,"question":"الجار إذا نُصح ولم يقبل النُّصح، هل يَنقل من المكان هذا إذا استطاع وإلا يصبر عليه؟","title":"هل الأفضل الانتقال عن جار السوء أم الصبر؟","answer":"الجواب: يعمل بالأصلح؛ إن كان في بقائه في محله خيرٌ فيصبر على نصحه، ويُذكّر الناس، ويدعو إلى الله، وإن كان في انتقاله إلى محلٍّ آخر أصلح انتقل.","link":"https://binbaz.org.sa/fatwas/24344/هل-الافضل-الانتقال-عن-جار-السوء-ام-الصبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التعامل مع جار السوء.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4113,"question":"إذا رؤي الرجل يعمل بعمل أهل النار، ما يفسّق، أو على ظاهره؟","title":"ما حكم مَنْ رؤي يعمل بعمل أهل النار؟","answer":"الجواب: يُنصح، ينصحه ويدعوه إلى الخير؛ الدين النَّصيحة.","link":"https://binbaz.org.sa/fatwas/24355/ما-حكم-من-روي-يعمل-بعمل-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا رؤي الرجل يعمل بعمل أهل النار.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4193,"question":"إذا كان يذهب إلى المستشفى لزيارة مريض، ويوجود في المستشفى منكر لا يستطيع إنكاره، هل يذهب؟","title":"حكم الذهاب لمكان به منكر لا يستطيع إنكاره","answer":"الجواب: يذهب له، ينكر حسب طاقته.","link":"https://binbaz.org.sa/fatwas/24450/حكم-الذهاب-لمكان-به-منكر-لا-يستطيع-انكاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إنكار المنكر حسب الطاقة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4243,"question":"بعض الناس يستعمل طريقة في الدعوة أنه يدعو إلى فضائل الأعمال، ويترك الدعوة إلى التوحيد يقول يفرِّق بين الناس ؟","title":"ما حكم زعم أن الدعوة للتوحيد تفرِّق الناس؟","answer":"الجواب: لا لا، هذا غلط، هذا من جهله. إذا كان يدعو المشركين يبدأ بالتوحيد، أما إذا كان يدعو المسلمين يرغّبهم في الثبات على الحق وعلى طاعة الله ورسوله ﷺ  والحذر من المعاصي؛ لأنهم موحدون. أما إن كان يدعو أهل الشرك يبدأهم بالدعوة إلى التوحيد وترك الشرك، هذه التي بدأ بها النبي ﷺ وأمر الصحابة أن يبدؤوا بها؛ لأن الشرك أعظم الذنوب، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24510/ما-حكم-زعم-ان-الدعوة-للتوحيد-تفرق-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الحكمة الدعوة إلى فضائل الأعمال، وترك الدعوة إلى التوحيد.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4245,"question":"إذا علم أن رجلًا عاصٍ في المعاملات لكن يُشك في شركياته؟","title":"كيفية دعوة شخص يُشك في وقوعه بالشرك؟","answer":"الجواب: يعلمون هذا وهذا، ينهونه عن الشرك ويحذرونه من المعاصي كلها، يحذرونه من الشرك والمعاصي جميعها، هذا وهذا، إن كان عندهم معاصٍ ولكن يُشك في إسلامهم يوضح لهم الإسلام والدعوة إلى التوحيد، ويُبيّن لهم أيضًا الحذر من المعاصي.\nس: يستدرج في الحديث معهم؟\nج: هذا وهذا.","link":"https://binbaz.org.sa/fatwas/24513/كيفية-دعوة-شخص-يشك-في-وقوعه-بالشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في دعوة المدعوين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4266,"question":"جنود النصارى لا يجلس لدعوتهم للإسلام؟","title":"حكم دعوة المشركين للإسلام وهم بمجلس خمر","answer":"الجواب: واليهود كذلك، كلهم يدعون للإسلام، اليهود والنصارى.\nس: أقصد وقت فرغتهم يجلسون على كراسٍ ويدار بينهم الخمر فهل يُدْعَون أو يُتركون؟\nج: إذا كان ما هناك حيلة إلا هذا الوقت يجيئهم، يبين لهم أن الله خلقهم لعبادته، وأن الله أوجب عليهم اتباع محمد ﷺ وهو خاتم الأنبياء، وأن الله حرم عليهم الخمر، وحرم عليهم الزنا، وحرم عليهم كذا، هذا دين الإسلام. المقصود دعوتهم إلى التوحيد أولًا، أول شيء يدعوهم إلى توحيد الله، واتباع محمد ﷺ، ويبين لهم أن من محاسن الإسلام تحريم هذا الشيء المنكر.","link":"https://binbaz.org.sa/fatwas/24536/حكم-دعوة-المشركين-للاسلام-وهم-بمجلس-خمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعوة المشركين للإسلام، حال دوران بينهم الخمر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4298,"question":"جلساء السوء إذا كانوا من الإخوة ومعك في منزل واحد، ماذا يكون في مثل هذه الحالة؟","title":"ما يفعل من ابتُلي بجلساء السوء من الأقارب؟","answer":"الجواب: تدعوهم إلى الله، إن كان عندهم شيء من المعاصي أو الشرك تدعوهم إلى الله، ترشدهم، فإن استقاموا وإلا ابتعد عنهم لا يجروك إلى الباطل.\nس: ترحل من المنزل الذي هم فيه؟\nج: إن كنت تخشى على نفسك أن يجروك إلى باطلهم.\nس: حتى الوالد كذلك؟\nج: حتى الوالد.","link":"https://binbaz.org.sa/fatwas/24571/ما-يفعل-من-ابتلي-بجلساء-السوء-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلساء السوء من الأقارب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4345,"question":"بعض الناس تنكر عليهم ويزيد.. مثلاً مطوّل على المسجل يزيد المسجل، إذا صار يدخن يبخ في وجهك؟","title":"بم يُنصح من يتعرض للأذى عند إنكار المنكر؟","answer":"الجواب: تدعو له بالهداية، بعض الناس سفيه لا يزيده الإنكار إلا شرًّا؛ لكن ينبغي للمؤمن أن يكون أعقل منه، يحلم يصبر، ويقول: الله يهديك، الله يعيذك من الشيطان، حتى يكون خيرًا منه.","link":"https://binbaz.org.sa/fatwas/24620/بم-ينصح-من-يتعرض-للاذى-عند-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعرض للأذى والسخرية عند إنكار المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4361,"question":"هل تجب النصيحة في ذلك؟","title":"كيف تكون النصيحة في البُعد عن الرياء؟","answer":"الجواب: إذا كنت تعلم ما في قلبه فانصحه.\nس: الظاهر أنه دائمًا يعني؟\nج: لا. تنصح عمومًا أنه يجب الحذر من الرياء وبس، ولا تقول هذا يرائي، فأنت لا تعلم ما في قلبه. تقول لإخوانك الذين تخشى عليهم: ترى الرياء ما يجوز، والواجب إخلاص العمل لله؛ في قراءته، في صلاته، في صدقاته، في عيادة المريض، في كل شيء، يقصد وجه الله، من باب التناصح.","link":"https://binbaz.org.sa/fatwas/24638/كيف-تكون-النصيحة-في-البعد-عن-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النصيحة للمرائي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4400,"question":"هذا رجل معه في العمل يذب عليه الشبه دائما، آخر شبهة يقول: لو تعمل عمل الشيطان، والرسول ﷺ قال: لولا أن أشق على أمتي دائما يذب على هذا الشخص الشبه، ماذا يعمل معه؟","title":"حكم مخالطة مثيري الشٌّبهات","answer":"الجواب: يتركه، يقول له: لا تتكلم معي.\nالطالب: يهجره؟\nالشيخ: إذا كان يتكلم معه بشيء يؤذيه، يقول له: لا تكلم معي يا أخي.\nس: هذا يقول: لو تعمل عمل الشيطان، والرسول ﷺ قال: لولا أن أشق على أمتي؟\nج: لولا أن أشق لأمرتهم بالسواك وأيش فيه؟\nالطالب: الرسول قالها.\nالشيخ: وأيش يقول له؟\nس: قصده في تناقض، لا تقولون لو، وهو قال في الحديث: لولا.\nج: لا، هذا شيء وهذا شيء، هذاك إذا جرى المقدور قال: لو فعلت كذا، لو أتيت الطبيب لكان كذا، لو سافرت كان كذا، هذا الذي ممنوع يقول: قدر الله وما شاء فعل، أما هذا غير لولا أن أشق على أمتي لأمرتهم بالسواك يعني لولا المشقة لفعلت هذا، رحمة الله جل لعباده هذا ما فيه معارضة.\nس: هذا يُهْجَر؟\nج: لا، يُعَلَّم، ويُوَجّهه.","link":"https://binbaz.org.sa/fatwas/24677/حكم-مخالطة-مثيري-الشبهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مخالطة مثيري الشٌّبه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4520,"question":"حالق اللحية مظهر للمعصية هل يردّ عليه السلام؟","title":"ما المنكرات التي يُهجر أصحابها؟ وما الضابط؟","answer":"الجواب: هذا منكر ظاهر يستحقّ الهجر، لكن بعد أن يُنصح ويُعلم أنَّ هذا ما يجوز، وأنه منكر، حتى إن بعض الناس يراها لا بأس بهذا؛ لأنهم رأوا الناس قد كثر فيهم هذا الشيء، فقد يشتبه على بعض الناس، لكن يُعلَّم ويُوجَّه ويُبين له الحقّ؛ لأنَّ وقوع الناس في ذلك بكثرةٍ قد يُسبب التباس الأمر على الناس، نسأل الله العافية. س: الهجر على إطلاقه لكل أحدٍ؟ ج: إذا كان فيه مصلحة، أما إذا كانت المصلحة تقتضي عدم هجره لمصلحة المسلمين، ما هو لأجل أن يأكل معه ويشرب معه، لا، بل لمصلحة المسلمين فلا بأس، لا يهجره، بل يُنكره ويُداوم في النَّصيحة. س: إذا كان الهجرُ لا يردعه؟ ج: ولو ما يردعه ما فيه خير أن يُجالس ويُؤاكل، أما إذا كان عدم الهجر فيه مصلحة للمسلمين، مصلحة دينية. يقول ابنُ عبدالقوي رحمه الله: فالمسألة فيها أقوال ثلاثة: الهجر سنة مطلقًا، وقيل: واجبًا مطلقًا، وقيل بالتفصيل: إن ردع وجب، وإن لم يردع لم يجب. س: هذه بلوى عمَّت، فلو هُجر كلُّ رجلٍ حلق لحيته أو عصى يُهجر أغلب الناس؟ ج: على كل حالٍ الواجب [على] الإنسان [أن] يعتني بما هو أصلح، يُجاهد نفسه ويعمل ما هو أصلح، لا لهواه، ولكن للمصلحة الشرعية، وإلا البلاء لا شكَّ أنه عظيم. س: من مصالح المسلمين هدايته؟ ج: يعني: ما هو لأجل محبته، أو لأجل قرابته، أو لأجل كذا، بل للمصالح الإسلامية، مُراعاة للمصالح الإسلامية. س: يعني قصد هدايته وتحبيبه؟ ج: نعم، أو دفع منكرًا منه، أو دفع أذى عن المسلمين، أو نحوها.","link":"https://binbaz.org.sa/fatwas/24800/ما-المنكرات-التي-يهجر-اصحابها-وما-الضابط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رد السلام على حالق لحيته، وهجر أصحاب المنكرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4813,"question":"من رفض السنة تكبرًا يُدعى عليه؟","title":"هل يجوز الدعاء على من رفض السنة عنادًا؟","answer":"يُدعى له بالهداية، وإن دعا عليه بالعقوبة فكما قال النبي ﷺ: لا استطعت؛ لأنه تكبّر.","link":"https://binbaz.org.sa/fatwas/25213/هل-يجوز-الدعاء-على-من-رفض-السنة-عنادا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدعا على من رفض السنة عنادًا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4823,"question":"هل يزول الهجر بالسلام أم بعود الحال إلى ما كان عليه من قبل؟","title":"بماذا يزول هجر المسلم لأخيه؟","answer":"الهجر يزول بالسلام، وكماله بأن تعود الحالة كما كانت أولًا، لكن ظاهر قول النبي ﷺ: خيرهما الذي يبدأ بالسلام يزول عنه.","link":"https://binbaz.org.sa/fatwas/25228/بماذا-يزول-هجر-المسلم-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بماذا يزول هجر المسلم لأخيه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4824,"question":"صاحب المعصية هل يجوز هجره أكثر من ثلاثة أيام؟","title":"حكم هجر صاحب المعصية أكثر من ثلاثة أيام","answer":"المعاصي لها شأن، والبدع؛ أن يُهجر حتى يتوب إذا أظهرها، هذه في حقِّ الإنسان مع أخيه، في حقوق الدنيا، حقوق الأخوة، أما إذا أظهر المعاصي فهذا يُهجر حتى يتوب.","link":"https://binbaz.org.sa/fatwas/25229/حكم-هجر-صاحب-المعصية-اكثر-من-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز هجر صاحب المعصية أكثر من ثلاثة أيام.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4828,"question":"إذا كان هناك ميت كثير الفساد، ونُحذر أصحابه الذين بقوا أن انتبهوا مثلًا من أفعال فلان؟","title":"هل يجوز تذكير الناس بفساد من مات؟","answer":"إذا كان الفساد ظاهرًا والمعاصي ظاهرةً؛ لا بأس، النبي ﷺ لما مرّ عليه بجنازةٍ فأثنوا عليها شرًّا قال: وجبت، ما أنكر عليهم، وهذا محمولٌ على أنَّ معاصيه ظاهرة، فالذي معاصيه ظاهرة ما له غيبة، ليس له غيبة.","link":"https://binbaz.org.sa/fatwas/25245/هل-يجوز-تذكير-الناس-بفساد-من-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز تذكير الناس بفساد من مات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4830,"question":"حكم النَّصيحة؟","title":"ما حكم النَّصيحة؟","answer":"واجبة فيما يجب، ومُستحبَّة فيما يُستحب، واجبة في ترك المنكرات، ومُستحبة في المستحبَّات.","link":"https://binbaz.org.sa/fatwas/25250/ما-حكم-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم النَّصيحة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4835,"question":"النصيحة الواجبة مقيّدة بطلب النصيحة أم ببذلها من دون طلب؟","title":"هل النصيحة مقيدة بطلبها أم تُبذل دون طلب؟","answer":"يقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة فإذا علمت أن أخاك فعل شيئًا يريد النصح؛ ينبغي أن تنصحه، وإذا استنصحك فانصح له، الأمر آكد. يعني قال: ما تقول في كذا وكذا؟ لا تغشه، وإلا فأنت تبدأه بالنصيحة ولو ما استنصحك، سنة مؤكدة. تبدأه بالنصيحة، إذا رأيته قد يقع في شيء يضره انصحه، أو سلعة ما تناسبه أو مغشوشة، الشيء الذي ترى فيه المصلحة لأخيك تنصحه فيه، وقد تجب، تختلف الأحوال.","link":"https://binbaz.org.sa/fatwas/25261/هل-النصيحة-مقيدة-بطلبها-ام-تبذل-دون-طلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النصيحة الواجبة مقيدة بطلب النصيحة أم ببذلها من دون طلب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4964,"question":"لو كان في شريط يقول مثلًا: قال الله تعالى، مثلًا، يحط قبلها: قال الله تعالى؟","title":"هل يستعيذ المحاضِر للآية أم يكفي \"قال الله\"؟","answer":"الجواب: إذا كان ذكر آية ما في بأس.\nس: يقول: قال الله تعالى، أو يقول: أعوذ بالله من الشيطان الرجيم؟\nالشيخ: قال الله تعالى كذا وكذا، أو يقول: أعوذ بالله من الشيطان، قال الله كذا وكذا، إذا تعوّذ أحسن أفضل فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ [النحل:98].","link":"https://binbaz.org.sa/fatwas/27664/هل-يستعيذ-المحاضر-للاية-ام-يكفي-قال-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستعيذ المحاضِر للآية أم يكفي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5002,"question":"إذا رأى الوالي أن يحبس عن الرعية أرزاقَهم ومصالحهم لمصلحةٍ يعلمها..... فيمنعها عنهم لفترةٍ معينةٍ لكي ينضبطوا في بعض الأمور؟","title":"حكم حبس أرزاق الناس لمصلحةٍ مدةً معينة","answer":"الجواب: له الاجتهاد فيما يراه مصلحةً.","link":"https://binbaz.org.sa/fatwas/28739/حكم-حبس ارزاق-الناس-لمصلحة-مدة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حبس أرزاق الناس لمصلحة مدة معينة.mp3","categories":["السياسة الشرعية","قضايا معاصرة"]},{"id":5004,"question":"الوالدان عند الإنكار عليهما: ألا يَرِدْ أبدًا التَّعنيف؟","title":"هل يجوز التعنيف في الإنكار على الوالدين؟","answer":"الجواب: لا، باللُّطف، فالله قال في حقِّ الكافِرَيْنِ: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا  [لقمان:15]، وقال في حقِّهما: فَلَا تَقُلْ لَهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا [الإسراء:23].","link":"https://binbaz.org.sa/fatwas/28763/هل-يجوز-التعنيف-في-الانكار-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز التعنيف في الإنكار على الوالدين؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5073,"question":"قصور الأفراح يحصل بها بعض المُنكرات، فهل لطلبة العلم زيارتهم ووعظهم وإرشادهم والبيان لهم؟","title":"كيف يكون النصح والإنكار بقصور الأفراح؟","answer":"الجواب: ينبغي استغلال هذه الفرصة، الدُّعاة وأهل العلم يزورون هذه القصور وقت الاجتماع، ويلقوا فيهم النَّصائح والتوجيهات، بسبب الاجتماع الذي يجمع الجمَّ الغفير من الجاهل وطالب العلم من النساء والرجال، اغتنام هذه الفرصة بالتوجيه والتَّذكير والنَّصيحة أمرٌ مطلوبٌ، ينبغي لأهل العلم -ولا سيَّما خواص الدعاة إلى الله- أن يحضروها ويُنبهوا ويعظوا ويُذَكِّروا، وهكذا بقية الاجتماعات، وسائر الاجتماعات إذا أمكن ذلك، فهو فيه خيرٌ عظيمٌ.","link":"https://binbaz.org.sa/fatwas/29383/كيف-يكون-النصح-والانكار-بقصور-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يكون النصح والإنكار بقصور الأفراح؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5076,"question":"شخصٌ يدعو ويأمر بالمعروف وينهى عن المنكر، ولكن لا يُسْمَع له، فما نصيحتكم لهذا الشَّخص؟","title":"ما التوجيه لمن ينصح للناس دون استجابة؟","answer":"الجواب: لا يضرُّه ذلك، لكن عليه أن يتحرى الأسلوب النافع؛ لأني أخشى أن يكون عدم النفع من سوء أسلوبه وغِلَظِه وعُنفه، لكن يُغيّر أسلوبه، وينظر في أسباب عدم النَّفع: ليش، لا بدّ أن يحاسب نفسه: إما أنه صاحب معاصٍ، يحتقرونه لأنه صاحب معاصٍ، يقول ولا يعمل، وهذه علَّة عليلة عظيمة، وإما أنه لا يُحسن أسلوب الدَّعوة، وإما لأسبابٍ أخرى، فلينظر، وليُحاسب نفسه، ويتَّقي الله، فلم يُخفق إلا بسبب ذنبٍ من ذنوبه، هذا في الغالب.  وقد لا يُسمع له ولو كان أصلح الناس، لكن يُحاسب نفسه وينظر، فإن وجد شيئًا فليُعالجه، وإن كان ما وجد شيئًا فالحمد لله، ولا يضرُّه ذلك، النبي ﷺ مكث في مكة دهرًا طويلًا -ثلاث عشرة سنة- ما أجاب له إلا القليل، ولا يضرُّه هذا، مثلما سمعتم في حديث ابن عباسٍ: يقول ﷺ: عُرضت عليَّ الأمم، فرأيتُ النبيَّ ومعه الرهيط، كان في رواية مسلم: الرهيط بالتصغير: ثلاثة أو أربعة أو خمسة، والنبي معه الرجل والرجلان، والنبي وليس معه أحدٌ بعض الأنبياء ما أطاعه أحدٌ بالمرة، ما قبلوا منه، بل قتلوه، فيأتي يوم القيامة وحده، ما معه أحدٌ، ما تبعه أحدٌ من أمَّته كلها، ولا يضرُّه، هذا أدَّى ما عليه، والحمد لله.","link":"https://binbaz.org.sa/fatwas/29416/ما-التوجيه لمن-ينصح-للناس-دون-استجابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما التوجيه لمن ينصح للناس دون استجابة؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5094,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، ما هي مبادئ وأسس الدعوة إلى الله؟ وما هي طرقها؟","title":"ما مبادئ وأسس الدعوة إلى الله؟","answer":"الجواب: المبادئ معروفة: أولاً: المؤمن يجتهد في نفسه، ويتعلم، ويتبصّر، ويتفقه. وإذا رزقه الله العلم وتفقه في دينه فإن المبدأ في ذلك: أن يدعو إلى الله؛ بتعليم الناس، وبإرشاد الجاهل وتعليمه، وتوجيهه إلى الخير، وأمره بالمعروف، ونهيه عن المنكر، كما قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]. المبدأ الأول: أن تتلقى العلم، وأن تتعلم وتتبصّر، وتعتني بالقرآن وحفظه وتدبّر معانيه، والسنة عن النبي ﷺ، حتى تحفظ منها ما تيسر، وتشتغل على أهل العلم، وتسأل أهل العلم، وتذاكر أهل العلم؛ حتى تكون على بينة. فإذا عرفت ما شرع الله لك، وما أوجب عليك، وما حرَّم عليك؛ تدعو إلى الله، فتكون ممن قال الله فيهم: وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] وممن قال فيهم: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، وممن قال فيهم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. تنفع نفسك، وتنفع الناس بالحكمة والكلام الطيب، قال تعالى: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]. فتدعو إلى الله بالكلام الطيب، وترشد إليه، وتعلم الناس الخير، وتنهاهم عن الشر، هكذا ينبغي لك.","link":"https://binbaz.org.sa/fatwas/29998/ما-مبادى-واسس-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 14.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5100,"question":"سائل آخر يقول: فضيلة الشيخ عبد العزيز بن باز، السلام عليكم ورحمة الله وبركاته:أولاً: أُشهد الله أنني أحبك من أجله، وأسأل الله أن يطيل في عمرك وينفع بك جميع المسلمين.ثانيًا: إن أمتنا في الوقت الحالي تحتاج إلى العمل الصادق الدائم وليس إلى كثرة الكلام والخطب؛ فما هي السبل والطرق التي ترى وتقترح أن تقوم بها المراكز في الخارج لتكون الأقلية المسلمة في المجتمعات الغربية قرآنًا يسير على الأرض ويدعو إلى الإسلام الصحيح؟ وجزاكم الله خيرا.","title":"ما النصيحة للأقليات المسلمة في بلاد الغرب؟","answer":"الجواب: أولاً: أحبك الله الذي أحببتنا له وجعلنا وإياك وسائر إخواننا وسائر المستمعين من المتحابين في الله ، فقد صح عن رسول الله عليه الصلاة والسلام، أنه قال يقول الله يوم القيامة: أين المتحابون بجلالي اليوم أظلهم في ظلي يوم لا ظل إلا ظلي وصح عنه عليه السلام أنه قال: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا على ذلك وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليا ففاضت عيناه متفق على صحته. أما السؤال الثاني: فذلك متعيّن، ولكن الخطب والمحاضرات والمؤلفات والمقالات التي تنشر كلها وسيلة إلى ما ذكرت من العمل؛ فالخطبة والمقالة الجيدة الموفقة إذا نشرت أو وزعت أو أذيعت ينفع الله بها من يشاء، فالله شرع الخطب وشرع الكتب والنصائح حتى ينتفع بها الناس، حتى يستعين بها الناس وحتى يفقهوا دينهم وحتى يتشجعوا على ما ينبغي لهم وعلى ما يُطلب منهم. والواجب على العلماء وعلى المراكز الإسلامية وعلى الجمعيات الإسلامية وعلى كل من له قدرة في نفع العباد أن يمثل ذلك بالعمل لا بالقول فقط؛ فالقول ينفع في محله ولكن الأهم العمل، فالقول المشروع مطلوب، كذكر الله والأمر بالمعروف والنهي عن المنكر والاستغفار والدعاء مطلوب، ولكن ما كان يتعلق بالعمل فالمطلوب العمل: كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ [الصف:3] فلا بدّ من العمل فيما يتعلق بالعمل من صلاة وصوم وجهاد وحج وزكاة وغير هذا من وجوه العمل، فلا بدّ من القول في محله ولا بد من العمل في محله، ومن صفات المنافقين أنهم يقولون ما لا يفعلون، فلا يجوز للمسلم أن يقول ما لا يفعل بل يقول ويفعل، يكون صادقًا في قوله صادقًا في عمله، وعلى الحكام المسلمين أينما كانوا أن يُعْنَوا بأمر الله، فإن الزبدة العظيمة من ولاية الحاكم على المسلمين أن يوجههم إلى دين وأن يلزمهم بأمر الله وأن يعينهم على طاعة الله وأن يمنعهم مما يخالف شرع الله، هذه الزبدة المقصودة من الولاية، المقصود من الولايات سواء كانت الولاية مُلكية أو رئاسة جمهورية أو إمارة أو غير هذا من الأسماء، المقصود من الولايات إقامة أمر الله في أرض الله، المقصود هو إقامة أمر الله في أرض الله؛ لتوجيه الناس إلى الخير وإلزامهم بما أوجب الله ومنعهم عما حرم الله وإقامة الحدود عليهم فيما أوجب الله إقامته، هذا هو الواجب. ووصيتي لجميع إخواني، في كل مكان، في مراكز إسلامية، في جمعيات إسلامية، في معاهد، في مدارس، في أي عمل كانوا، وفي أي مكان كانوا، وصيتي للجميع أن يتقوا الله، وأن يلتزموا بأمر الله، وأن يعتنوا بتوجيه عباد الله إلى دين الله، وأن يكونوا دعاة خير ودعاة هدى، فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: من دل على خير فله مثل أجر فاعله وقال لعلي  لما بعثه إلى خيبر لدعوة اليهود: فوالله لأن يهدي الله بك رجلا واحدًا خير لك من حمر النعم والله يقول في كتابه العظيم: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] ويقول سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] فجعلهم هم أهل الفلاح حصره فيهم؛ لعظم ما قاموا به من الدعوة والأمر بالمعروف والنهي عن المنكر وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]. هذا هو واجب المسلمين؛ الدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر أينما كانوا، وبهذا يكون الإنسان من خير الأمة، بهذا يكون المؤمن والمؤمنة من خير الأمة بهذا العمل الجليل، بالدعوة إلى الله والأمر بالمعروف والنهي عن المنكر والاستقامة على الحق، والله المستعان.","link":"https://binbaz.org.sa/fatwas/30008/ما-النصيحة-للاقليات-المسلمة-في-بلاد-الغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 25.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5102,"question":"وصلنا من الأخوات سؤال يقول: يا فضيلة الشيخ إذا أرادت المرأة العمل في مجال الدعوة في المجتمع فما هي الكتب التي تنصحون بقراءتها ومناقشتها بين النساء سواء للمتعلمات أو الجاهلات بشكل مبسط؟","title":"ما الكتب التي يُنصح بها في الدعوة إلى الله؟","answer":"الجواب: أهم شيء القرآن الكريم، تعليم القرآن وما تيسر منه؛ لأنه كتاب الله فيه الهدى والنور: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] فنصيحتي لأخواتي الدعاة إلى الله من النساء أن يعنين بالقرآن الكريم تفقهًا وتفيقهًا وتعليمًا للنساء، وما يتعلق بالسور القصيرة، وأهم ذلك الفاتحة؛ تعليم الفاتحة ومعانيها؛ لأنها أم القرآن، وفيها: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]  وفيها اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] هذا من أهم ما يبين معنى الصراط المستقيم ما هو، معنى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] معنى صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:7]. وهكذا ما في كتاب الله من الأحكام والبيان، كل على حسبه، لطالبات العلم شيء، وللعامة من النساء شيء آخر، ثم تعليم العقيدة: ما معنى لا إله إلا الله، ما معنى شهادة أن محمدًا رسول الله؛ حتى يعرفن الله على بصيرة وحتى يعلمن معنى لا إله إلا الله، وأنه لا معبود حق إلا الله؛ فيخلصن العبادة لله وحده من صلاة وصوم وصدقة، وغير ذلك كله لله وحده. ثم تعليم الصلاة: كيف تصلي، والطهارة: كيف تطهر من الجنابة، من الحيض، من النفاس، كيف الطهارة الصغرى من الأحداث التي توجب الطهارة. كيف تصوم، كيف تزكي مالها وحليها، كيف تحج إذا جاء الحج. كيف تطيع والديها، كيف تطيع زوجها وما حق زوجها عليها، إلى غير هذا. ومن الكتب التي تناسب قراءتها: ما ألف في أمر النساء وشأن النساء وما في كتاب الله من شأنهن وما جاءت به السنة بشأنهن في \"بلوغ المرام\" مثلًا كتاب صغير مختصر مفيد، عمدة الحديث في أحاديث الرسول ﷺ، عمدة الفقه للموفق ابن قدامة، \"ثلاثة الأصول\" للشيخ محمد بن عبد الوهاب، \"كتاب التوحيد\"، \"العقيدة الواسطية\"، وما أشبه هذه من الكتب الصغيرة التي تنفعهن وتفيدهن، أو ملخص منها حتى يستفيد منهن العامة والطالبات الصغيرات اللآتي يحتجن إلى ذلك ولم يتعلمن في المدارس. أما من يتعلم في المدارس الطيبة فسوف يستفيد من المنهج الذي عنده والمقررات التي عنده، ولكن لا مانع من الزيادة أن تكون الداعية تزيد الطالبة علمًا وتفقيهًا وتوجيهًا، وتعلم العامية ما يلزمها مما لا يسعها جهله في إخلاص العبادة لله بالصلاة بالطهارة في الزكاة في الصيام كما تقدم، في حق الزوج، في حق الوالدين، في حق الأقارب، في حق الجيران وما أشبه ذلك. ومن أحسن الكتب أيضًا وإن كان مطولًا بعض الطول: \"زاد المعاد في هدي خير العباد\" لابن القيم فإنه كتاب مفيد ونافع، وهكذا \"فتح المجيد شرح  كتاب التوحيد\" كتاب مفيد أيضًا في العقيدة، وهكذا \"آداب المشي إلى الصلاة\" مختصر مفيد في الصلاة وفي الزكاة وفي الصيام للشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه، هذه كتب مختصرة مفيدة.","link":"https://binbaz.org.sa/fatwas/30010/ما-الكتب-التي-ينصح-بها-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 27.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5134,"question":"سائل يقول: إنني رجلٌ أقوم بالدعوة والإرشاد والأمر بالمعروف والنَّهي عن المنكر، وإنكار المنكرات على الناس، ولكن هناك مَن يتصدَّى لي ويقول: إنَّك تتدخل فيما لا يعنيك، وإنك تُثير فتنةً، فما الحكم في ذلك؟","title":"ما كيفية مواجهة التثبيط عن الدعوة إلى الله؟","answer":"الجواب: إذا كان عندك علمٌ وتدعو إلى الله على بصيرةٍ فلا تلتفت إلى مَن ثَبَّطك، تدعو إلى الله، تعلِّم الناس، تأْمُرْ بالمعروف، تنهَ عن المنكر، مع الحلم والصبر والاحتساب وطيب الكلام، كما قال الله جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، وقال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110]، وقال سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]. فاستمر على ذلك ما دام عندك علمٌ، فاستقم على ذلك، ولا تلتفت إلى مَن ثبَّطك، لكن عليك بالحكمة، وعليك بقال الله ورسوله، وضع الأشياء في مواضعها، والحلم والصبر، وعدم العجلة في الأمور، وعليك بالرفق وطيب الكلام.","link":"https://binbaz.org.sa/fatwas/30049/ما-كيفية-مواجهة-التثبيط-عن-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 70.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5137,"question":"سائل يقول: ما هي كتب العقيدة الصَّحيحة التي تنصحون طالب العلم باقتنائها وقراءتها؟ وكيف تُوجهون الداعية الذي يدعو أناسًا من أهل البادية من العامَّة الذين يحتاجون إلى تعلم أصول العقيدة؟","title":"ما واجب الدعاة تجاه العامَّة في تعليم العقيدة؟","answer":"الجواب: أعظم كتب العقيدة وأنفعها: كتاب الله \"القرآن\"، فيه الهدى والنور، فنوصي الجميع رجالًا ونساءً، كبارًا وصغارًا: أن يعتنوا بالقرآن، وأن يجتهدوا في حفظه، والإكثار من تلاوته، فهو كتاب العقيدة، وهو كتاب الهُدى، وهو الشافع المفيد النافع، كما قال جلَّ وعلا: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]. وهو الصراط المُستقيم، فنُوصي جميع المسلمين في كلِّ مكانٍ: جميع الرجال والنساء، العرب والعجم، نوصي الجميع بأن يلزموا هذا القرآن، وأن يُعظِّموه ويعملوا به، ويُكثروا من تلاوته أينما كانوا، من المصحف وعن ظهر قلب، وأن يُنفذوا أوامره، وينتهوا عن نواهيه. هو كتاب العقيدة، وهو كتاب العمل، وهو كتاب الهدى، وهو كتاب السَّعادة، فيه كل خير، وفيه الدَّعوة إلى كل خيرٍ، وفيه الدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وفيه القصص عن الماضين، عن الخير والشر، أخبر عن الماضين من أهل الخير، وعن الماضين من أهل الشر. فعلى المؤمن والمؤمنة أن يأخذوا منه ما دلَّ عليه من الخير، وأن يحذروا ما حذَّر منه من الشر. ثم كتب الحديث: كالصَّحيحين، والسنن، والمسانيد المُعتمدة، فأهل العلم يخرجون الأحاديث، ويُعلِّمون الناس وينشرونها بينهم. ثم كتب العقيدة المعروفة لأئمة أهل السنة والجماعة، الكتب الطيبة المعروفة يُستعان بها، ويُنتفع بها في تعليم الناس الخير، كتب السلف الصالح المعروفة، مثل: كتب شيخ الإسلام ابن تيمية وابن القيم رحمهما الله، وغيرهم من أهل العلم المعروفين بحُسن العقيدة، ومثل كتب الشيخ محمد بن عبدالوهاب رحمه الله، وأئمة الدعوة الإسلامية في نجد، لما يسَّر الله هذه الدَّعوة في القرن الثاني عشر، كتبوا وجمعوا فيها ما ينفع الله به الناس، مثل: كتاب \"التوحيد\"، و\"الثلاثة الأصول\"، و\"كشف الشُّبهات\"، و\"آداب المشي إلى الصلاة\"، ورسائل المشايخ في \"الدرر السنية\"، و\"فتح المجيد شرح كتاب التوحيد\" للشيخ سليمان، هذه الكتب العظمية، و\"العقيدة الواسطية\" لشيخ الإسلام ابن تيمية، و\"التدمرية\"، و\"منهاج السنة\"، و\"الحموية\"، و\"العقيدة الطحاوية\" وشرحها لابن أبي العز، و\"لمعة الاعتقاد\" لصاحب \"المغني\"، إلى غيرها من الكتب الطيبة، كتب السلف الصالح التي تُعين على الخير، وتنشر الحقَّ، وتُعلم الناسَ الخير. فأهل العلم يدلّون عليها ويفيدون الناس منها، لكن أصل الجميع والأصل العظيم \"القرآن\"، يجب على الجميع العناية بالقرآن، فهو الأصل الأول، وهو الذي بيده الهدى والخير. فعلى المسلمين أن يعتنوا بالقرآن أعظم عناية، رجالًا ونساءً، كبارًا وصغارًا، فهو كتاب الله، فيه الهدى والنور، وفيه الدلالة على كل خيرٍ، والتحذير من كل شرٍّ. ثم أحاديث الرسول ﷺ وسنته الصَّحيحة: كالبخاري، ومسلم، وغيرها من الكتب الصَّحيحة التي جمعت في هذا الباب، مثل: \"المنتقى\" و\"بلوغ المرام\" و\"عمدة الأحكام\"، وغيرها من الكتب المُؤلفة في الحديث، والتي اعتنى أهلها بالحديث الصحيح، وبيان ما ضعف منها وما صحَّ، فهذه تنفع الأمة، فعلى طالب العلم أن يعتني بها، ويستفيد منها، ويُعلم الناسَ الخير، يُعلم العامَّة، ويُوصل العامَّة إلى الحقِّ والهُدى والصَّلاح.","link":"https://binbaz.org.sa/fatwas/30052/ما-واجب-الدعاة-تجاه-العامة-في-تعليم-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 73.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5210,"question":"هذا يسأل عمَّا أصاب المسلمين اليوم من الذلِّ والهوان والفُرقة والاختلاف وطمع الأعداء بهم.","title":"ما أسباب فُرقة المسلمين وتسلُّط الأعداء عليهم؟","answer":"الجواب: لا أعلم سببًا لهذه الذلة وهذا التَّفرق إلا عدم استقامتهم على دين الله، وعدم تحقيقهم لشريعة الله، وعدم اعتصامهم بحبل الله جميعًا، فإنَّ الله جلَّ وعلا وعد عباده المؤمنين المُستقيمين بالنصر والتأييد، قال جلَّ وعلا: وَلَيَنْصُرَنَّ اللَّهُ مَنْ يَنْصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ  ۝  الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ [الحج:40- 41]، وقال : يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ [محمد:7]، وقال سبحانه: وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ الآية [النور:55]، فالله وعدهم بالنصر والاستخلاف إذا آمنوا وعملوا الصَّالحات، إذا نصروا دين الله، إذا أمروا بالمعروف ونهوا عن المنكر، ولا فعل بهم اليوم ما وقع؛ من الاختلاف، والتأخُّر عن نصر دين الله، والجهاد في سبيله، والأمر بالمعروف، والنَّهي عن المنكر. هذا هو السر في تأخُّر المسلمين وذلّهم، هو عدم اعتصامهم بحبل الله، وعدم التعاون على البر والتقوى، وعدم قيامهم بالواجب من الأمر بالمعروف والنَّهي عن المنكر، ونصر دين الله، وعلى حسب قيام مَن قام منهم بذلك حصل له بعضُ النصر، فدولتنا السعودية لما قامت ببعض الواجب حصل لها من النصر والخير والطُّمأنينة والأمن ما لم يحصل لغيرها، ولو أنها قامت بكل الواجب وعُنيت بكل الواجب لرأيتم من النصر والتَّأييد والعزة العظيمة والسَّعة الباهرة ما لا يخطر في البال، ولكن بسبب ما فرّطنا فيه وبسبب نقصنا وتقصيرنا في بعض الأمور وبعض الواجب؛ حصل ما حصل من النقص فيما عندنا. وهكذا الدول الأخرى؛ كل دولةٍ بحسب حالها، فكل دولةٍ عندها شيءٌ من خيرٍ، وشيءٌ من إيمانٍ، وشيءٌ من تقوى يحصل لها بعضُ الخير، وكلما زاد شرُّها وفسادُها زاد بلاؤها، وزاد الفسادُ فيها، وزاد اختلال الأمن فيها، إلى غير ذلك؛ جزاءً وفاقًا: وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] .","link":"https://binbaz.org.sa/fatwas/30154/ما-اسباب-فرقة-المسلمين-وتسلط-الاعداء-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 186.mp3","categories":["قضايا معاصرة"]},{"id":5240,"question":"سؤال يقول: ما مدى حدود واجب الفرد في مجال الحسبة؟ هل هي فرض عينٍ لكل فردٍ؟","title":"ما واجب كل مسلم في الأمر بالمعروف؟","answer":"الجواب: كما تقدم: فرض، فرض، فرض على كلِّ واحدٍ إذا لم يوجد مَن يقوم مقامه، أما إذا وُجد مَن يقوم مقامه صارت في حقِّه سنةً، لكن أنت في قريةٍ، أو في حيٍّ من الأحياء، أو في قبيلةٍ ما عندك أحدٌ يُنكر المنكر، أنت رأيت المنكر بنفسك، عليك أن تُنكر المنكر حسب الطاقة: إما باليد، أو باللسان، حسب الطاقة، أقل شيءٍ القلبُ، إذا خفتَ الضرب والقتل كفى القلب، وإلا فالواجب اليد كالحسبة، رجل الحسبة حسب التعليمات التي لديه، في الرجل مع أولاده حسب الطاقة، مع زوجته حسب الطاقة، أمير القرية في بلده، في قريته، في قبيلته شيخ القبيلة حسب طاقته، وهكذا كل بحسبه، أما أن تمر بالمنكر وتقول: هذا على الهيئة، الهيئة ما سوّت شيئًا، ولا تعلمه أيضًا، ما هو في جهتها، ولا في حيِّها، مثلًا: ما عندك مركز، أو عندك مركز وغفل، أنت رأيت المنكر: إما أن تُنكر المنكر، وإما أن ترفعه إلى مَن يُنكره إذا عجزت وتقول: جرى كذا، وجرى كذا من المنكرات الظَّاهرة. ومن هذا ما يتعلق بالصَّلوات: كثير من الناس يعرفون جيرانهم لا يُصلون في مسجدهم، ولا يقولون لهم: لماذا؟ أو يزورونهم، يروح اثنان أو ثلاثة، لا تروح وحدك، وحدك قد يُستهان بك، لكن انظر مَن يتيسر معك من الإخوان: اثنان، ثلاثة، تزورونه، أو في الطريق تُوقفونه: يا فلان، يا عبدالله، اتَّقِ الله، ما نُشاهدك -ما نشوفك- في المسجد، أو نسمع صوت المزامير والأغاني في بيتك، وأنتم جيرانه تسمعونه، تقولون له بالكلام الطيب، وتنصحونه، ولعله يستفيد، فإن لم يستجب في المرة الأولى استجاب في الثانية أو في الثالثة أو في الرابعة، أو ترفعون أمره بعد الإعذار إلى مَن يقوم عليه، وهكذا، فالغفلة هي المصيبة، والإعراض هو المصيبة.","link":"https://binbaz.org.sa/fatwas/30650/ما-واجب-كل-مسلم-في-الامر-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 488.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5299,"question":"ما حكم الدعاء للكفار والمبتدعة بالهداية والصلاح، وهل هناك خلاف بين أهل العلم في ذلك، وما الراجح في ذلك؟","title":"حكم الدعاء للكفار والمبتدعة بالهداية والصلاح","answer":"الجواب: الهداية مطلوبة من الجميع، طلب الهداية مطلوب من الجميع من الكافر والعاصي وغيرهما، كُلٌّ بحاجة إلى الهداية، وأنت تقرأ في كل ركعة اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ أنت تطلب الهداية وأنت مؤمن، تطلب الهداية والثبات على الحق والمزيد من الهداية، كُلٌّ محتاج للهداية، النبي ﷺ قيل له: إن دوسًا كفرت وعصت قال ﷺ: اللهم اهدْ دوسًا وائت بهم، اللهم اهد دوسًا وائت بهم، ودعا لكثير من الكفرة فهداهم الله. وإذا كان ظالمًا مؤذيًا دُعي عليه بالهلاك أيضًا، يجوز الدعاء عليه بالهلاك والدعاء له بالهداية، هذا جائز وهذا جائز، ولاسيما إذا آذوا الناس وأضروا الناس؛ فهم أوْلى بأن يدعى عليهم بالهلاك لبُعد هدايتهم، وإذا كانوا كفّوا شرهم دُعي لهم بالهداية وأن الله يهديهم للحق وأن الله يبصّرهم.[1]","link":"https://binbaz.org.sa/fatwas/30949/حكم-الدعاء-للكفار-والمبتدعة-بالهداية-والصلاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 019.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5323,"question":"لقد عملت ما يقارب السنة مع الشيعة الرافضة الاثني عشرية في مدينة القطيف، وجرى خلال هذه المدة بعض النقاش حول بعض الاختلاف بين أهل السنة والشيعة، وكنت آتي بأدلة لما أقوله من كتبهم المعتمدة مثل الكافي وما لا يحضره الفقيه، ومن كتب أهل السنة المؤلفة في الشيعة، وكانوا لا يقبلون لحجة أن هذه الكتب مثل الكافي وغيره ليست صحيحة كلها، وكنت أعطيهم من كلام الخميني ولا يردونه، عمومًا سؤاله كالتالي: أنا الآن انتقلت من عندهم واتفقت أنا وأحدهم أن نكمل النقاش عبر المراسلة، فما رأي سماحتكم، وبماذا تنصحونني في هذا الشأن؟","title":"حكم وكيفية الرد على أهل البدع ومجادلتهم","answer":"الجواب: الشيعة من أخبث أهل البدع، وشرهم الرافضة الإمامية، فإنهم ضد الإسلام وضد أصحاب الرسول ﷺ، فهم عندهم من الشرك والكفر وأنواع الشر ما ليس عند غيرهم، من سب الصحابة والغلو في علي وأهل البيت وأنواع الشرك بالله ، فمثلهم لا يحاجهم إنسان إلا بقال الله وقال رسوله، لا بقول فلان وفلان؛ لكن هم وأمثالهم لا بدّ من مقارعة الحجة بالحجة، وباطلهم يُدمغ بالحجة، قال الله وقال رسوله؛ حتى لا يلبّسوا على الناس بقول فلان وفلان. فالواجب أن يُدعَوا إلى الحق من الكتاب والسنة وبما درج عليه سلف الأمة وهم في الغالب لا يستجيبون؛ لأن كفرهم متعمد مثل اليهود، هم أشبه الناس باليهود، يجادلون بالباطل ويجحدون الحق على بصيرة، ولا يستجيبون لداعي الحق عنادًا وكفرًا وضلالًا، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/30988/حكم-وكيفية-الرد-على-اهل-البدع-ومجادلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 043.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5329,"question":"في بعض الأحيان يمر الإنسان بمنكرات يحترق لها القلب ولا يستطيع الإنكار بسبب ضعف المُنْكِر وقوة الفاعل، فما العمل في هذه الحالة؟","title":"ما حكم عدم إنكار المنكر لقوة الفاعل؟","answer":"الجواب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16] يقول ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان إذا كان في بيئة لا يستطيع الإنكار بيده ولا بلسانه فليجتنبها ولا يحضر المنكر، يبتعد وينكر بقلبه، وإذا كان في بيئة يستطيع الإنكار بلسانه أنكر بلسانه، وإذا كان يستطيع أن يغير بيده كأبي الأولاد والسلطان والأمير والهيئة، على حسب صلاحيته، أنكر بيده حسب ما عنده من الصلاحية.[1]","link":"https://binbaz.org.sa/fatwas/30999/ما-حكم-عدم-انكار-المنكر-لقوة-الفاعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 050.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5333,"question":"ما هو العقاب الذي توعد الله به من رأى منكرًا ولم يغيِّره بلسانه وهو قادر على ذلك؟","title":"ما حكم مَنْ رأى منكرًا ولم يغيِّره؟","answer":"الجواب: مثل ما قال الله في سورة المائدة: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ۝ كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة: 78، 79] موعود باللعن والطرد عن الرحمة، نسأل الله العافية، وفي الحديث الصحيح يقول ﷺ: إن الناس إذا رأوا المنكر ولم يغيّروه أوشك أن يعمّهم الله بعقاب نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31005/ما-حكم-من-راى-منكرا-ولم-يغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 055.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5479,"question":"ما تقول في الأخذ على يد الإمام بظلمه أو بسبب ظلم عامله؟","title":"ما كيفية النصيحة للإمام الظالم؟","answer":"الجواب: هذا كلام ليس بطيبٍ إطلاقًا، ولكن المناصحة والمناصحة، إذا وُجد من الإمام ظلمٌ أو تقصيرٌ يُناصح، ولا يجوز الخروج عليه، على العباد السمع والطاعة بالمعروف، وعدم الخروج عليهم بظلمهم أو معصيتهم، هذا لا يجوز، ولكن المناصحة والتَّوجيه إلى الخير؛ لأنَّ بالخروج يحصل الشر العظيم، وهذا دين الخوارج؛ الخروج على السَّلاطين، وهو دين الخوارج والمعتزلة. أما أهل السنة والجماعة فيرون السمع والطاعة لهم -لولاة الأمور- وإن عصوا، وإن جرت منهم معصية يجب لهم السمع والطاعة، ما لم تروا كفرًا بواحًا عندكم من الله فيه برهان، مع القُدرة أيضًا، كلام المؤلف في هذا فيه نقصٌ وضعفٌ، رحمه الله.[1]","link":"https://binbaz.org.sa/fatwas/31372/ما-كيفية-النصيحة-للامام-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 004.mp3","categories":["السياسة الشرعية","قضايا معاصرة"]},{"id":5629,"question":"والذي يقول أنَّ الهجر دواء، إذا كان ينفع يُستعمل؟","title":"ما ضابط الهَجْر النافع للعاصي والمبتدع؟","answer":"الجواب: هذا هو؛ إن كان ما ينفع ما يُستعمل، دواء، مثلما هجر النبيُّ الثلاثةَ ونفعهم الله بالهجر، ولم يهجر عبدالله بن أُبي وأصحابه؛ لأنهم لا ينفع فيهم الهجر. س: لكن المُبتدع إذا لم يفد فيه النُّصح والتَّوجيه؟ ج: يُهجر. س: وإذا كان الهجرُ ما يُفيد فيه؟ ج: إذا كان في دولةٍ تقوم فيه بأمر الله، وإلا أنت هذا الذي عليك: إما أن تنصح، وإما أن تهجر، أما إذا كان في دولةٍ تُقيم أمر الله يُرفع أمره إلى الدولة، وأما أنت فلا تفعل: لا تقتل، ولا تضرب. س: يُشرع الهجر؟ ج: حتى يتوبَ، ولو سنة، ولو سنتين، ولو عشر سنين، حتى يتوب، مثلما هجر النبيُّ الثلاثة خمسين ليلةً حتى تاب الله عليهم. س: يعني: الهجر ليس له مدَّة؟ ج: إذا كان في المعاصي والبدع. س: على حسب المصلحة؟ ج: على حسب الهاجر؛ فإذا رأى أنَّ عدم الهجر ينفعهم باشرهم ونصحهم، وإذا رأى أن النَّصيحة لا تُفيدهم هجرهم.[1]","link":"https://binbaz.org.sa/fatwas/31626/ما-ضابط-الهجر-النافع-للعاصي-والمبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 004.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5651,"question":"قول الله  في المنافقين إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَاعْتَصَمُوا بِاللَّهِ وَأَخْلَصُوا دِينَهُمْ لِلَّهِ فَأُولَئِكَ مَعَ الْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ اللَّهُ الْمُؤْمِنِينَ أَجْرًا عَظِيمًا  النساء (146)؟","title":"هل للمنافق والجاسوس توبة؟","answer":"الجواب: إذا تابوا تاب الله عليهم، التوبة بابها مفتوح، إذا تاب تاب الله عليه، مثلما قال ﷺ: التوبة تجبّ ما قبلها، ولما ذكر الشرك والزنا والقتل قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا [الفرقان:70]. لكن الجاسوس لا، الجاسوس ما تُقبل توبته؛ لأنه إذا قُبلت توبته صار الجواسيس كثيرين، وإذا أمسكوا قالوا: تبنا، وتعطلت المصلحة، وحصلت المصيبة، الجاسوس لا يُترك، بل يُقتل، كما قتل النبيُّ ﷺ الجواسيس. لكن هذا حاطب فقط؛ لأنه من أهل بدر، وظنَّ أن هذا لا يضرّه، ثم بيَّن الله الأمر بعد ذلك وأوضح الأمر: لا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ [الممتحنة:1]، وبيَّن النبيُّ بعد ذلك، أمر بقتل الجاسوس.[1]","link":"https://binbaz.org.sa/fatwas/31688/هل-للمنافق-والجاسوس-توبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/albidayat walnihaya 001.mp3","categories":["السياسة الشرعية","قضايا معاصرة"]},{"id":5676,"question":"ما حكم من بدل ذهبًا ملبوسًا بذهب جديد، ودفع الفرق؟","title":"حكم تبديل الذهب بذهب مع دفع الفارق","answer":"الجواب: لا يجوز هذا؛ لا بدّ يشتري الذهب الجديد مستقلًا، ثم يبيع الذهب القديم، أو الردئ مستقلًا، مثل ما قال النبي ﷺ في التمر لما قال له بلال: إنا اشترينا صاعًا من التمر الطيب بصاعين من التمر الرديء، فقال: أوه أوه عين الربا، لا تفعل، بل بع بالدراهم، ثم ابتع بالدراهم جديدًا. وهكذا صاحب الذهب الرديء مع الذهب الطيب، يبيع الذهب الرديء أولًا لأخذ الثمن، ثم يشتري به ذهبًا جديدًا، أم يبيع هذا بهذا وزيادة لا؛ لأنه يتقابل ذهب بأقل من ذهب، النبي -عليه الصلاة والسلام-: الذهب بالذهب مثلًا بمثل، سواء بسواء، وزنًا بوزن فلا بدّ أن يبيع الذهب بالذهب وزنًا بوزن، سواء بسواء.","link":"https://binbaz.org.sa/fatwas/983/حكم-تبديل-الذهب-بذهب-مع-دفع-الفارق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_12.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":5702,"question":"عرفنا من فضيلة العلماء معنى الحضارة الحقيقي، ومقوماتها؛ فما هو أقرب طريق، وأسرعه للنهوض بوضع المسلمين البئيس على حد تعبيره؟","title":"أقرب طريق للنهوض بواقع المسلمين","answer":"الجواب:  أقرب طريق، وأيسره، وأنفعه هو التعاون على البر والتقوى، ونشر العلم النافع بين الناس في المعاهد، والمدارس، وإصلاح مناهج التعليم، وتقريب الأخيار من المدرسين، وإبعاد الأشرار، كل هذا من إعداد القوة، وكل هذا من العمل الصالح.\nالعمل الصالح: نشر العلم النافع بين الناس، ونشر المناهج النافعة، ونشر المدارس النافعة، والمعاهد النافعة، والكليات النافعة، وتقريب الأخيار من المدرسين، وغيرهم، وإبعاد الأشرار، والصدق في ذلك من ولاة الأمور، ومن العلماء، ومن أعيان المسلمين، ومن الطلبة. فإذا جاء الصدق في هذا كله جاء الخير العظيم سريعًا، وإذا تخلف هذه الأمور، ولم يرفع بها رأسًا استمر البلاء، والله يقول -جل وعلا-: وَمَا أَصَابَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَن كَثِيرٍ [الشورى:30] فمصيبتنا من كسب أيدينا!  فإذا أصلحنا ما أفسدنا إذا أصلحنا مناهجنا، ومدارسنا، ومعاهدنا، وتعاونا على البر والتقوى مع كبرائنا، وعلمائنا، وقضاتنا، وسائر من له شأن، إذا حصل هذا جاء الخير الكثير، وجاءت السعادة، وجاء النصر المؤزر، بإذن الله .","link":"https://binbaz.org.sa/fatwas/1000/اقرب-طريق-للنهوض-بواقع-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_29.mp3","categories":["الوكالة","قضايا معاصرة"]},{"id":5744,"question":"بعض الشركات المساهمة تفرض الحكومة لها نسبة من الربح 15%، فهل الربح الذي يحصل عليه المساهم في هذه الشركات حلال، أم فيه شيء من الربا؟","title":"حكم أرباح الشركات التي تضمن فيها الحكومة نسبة من الربح","answer":"الجواب: ما فيه شيء، ما تفرضه الحكومة للناس من المساعدات حتى ينشطوا في المشاريع، وحتى لا يخسروا، وحتى يستمروا في ما ينفع المجتمع هذا مساعدة من بيت المال، داخل في باب المعاملات.  فهذه المساعدة للشركة حتى تقوى وتنشط وتستمر، فما يعطى للمزارعين، أو لغيرهم، أو للتجار حتى يجلبوا الأموال النافعة، ما يكون الربح فيه قليل كل هذا مما ينفع المسلمين وليس فيه ربا.","link":"https://binbaz.org.sa/fatwas/1048/حكم-ارباح-الشركات-التي-تضمن-فيها-الحكومة-نسبة-من-الربح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_65.mp3","categories":["قضايا معاصرة","الشركة"]},{"id":5777,"question":"ما حكم العمل في القضاء الذي يحكم بالقوانين الوضعية؟ وكذلك العمل في البنوك الربوية الذي إذا تركها تمكن منها غير المسلمين؟","title":"حكم العمل في البنوك الربوية والقضاء بالقوانين الوضعية","answer":"الجواب: هذا لا يجوز، يجب منع الربا، وعدم الموافقة عليه، والاجتهاد في تطبيق أحكام الله الشرعية في البنوك وغيرها، وهذا يجب على الدول الإسلامية أن تعنى بهذا، وأن تسير البنوك، والمصارف على حكم الله  وأن تبذل الوسع في ذلك حتى تستقيم البنوك في البلاد الإسلامية على شريعة الله، وأن تمنع الربا منعًا باتًا. وهكذا القوانين الوضعية يجب أن تمنع إلا ما وافق منها شرع الله  فيجب على الدول الإسلامية أن يحكموا كتاب ربهم، وسنة نبيهم، وأن يحذروا السير مع أعداء الله في تحكيم القوانين الوضعية التي تخالف شرع الله. هذا من أهم الواجبات عليهم، وليس لهم عذر في ذلك، بل يجب عليهم وجوبًا قطعيًا أن يحكموا شريعة الله، إن كانوا صادقين في دعواهم الإسلام، عليهم أن يحكموا شريعة الله، وعليهم أن يجتهدوا أيضًا في تسيير المصارف على النهج الإسلامي، ومنع المعاملات الربوية، وأن يستعينوا بأهل العلم في ذلك، حتى يضعوا ما ينبغي وضعه للسير عليه في البنوك، وفي غير البنوك من الأشياء التي يتعاطاها الناس، وهي مخالفة للشرع والله المستعان. س:... الشيخ:  هذا معصية عظيمة، وكبيرة، وإذا استحلها كفر، من استحل الربا كفر، من استحل الحكم بغير ما أنزل الله كفر. أما إذا فعلها للهوى وهو يعلم أنه مخطئ عاصٍ أنه ظالم لا يكفر بهذا، يكون عاصيًا ومرتكبًا كبيرة عظيمة، نسأل الله العافية. وعلى المسلم أن يتقي الله، وأن ينصح إخوانه، وأن يوجههم إلى الخير. السؤال: ... موظف في البنك؟ الجواب: لا يعمل، لا يتعاون معهم على الإثم والعدوان.\n\nالسؤال:...  الشيخ: الله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] والله ولي عباده.","link":"https://binbaz.org.sa/fatwas/1103/حكم-العمل-في-البنوك-الربوية-والقضاء-بالقوانين-الوضعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_109.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":5791,"question":"أحد الإخوة يقول: قرأت في مجلة المجتمع، نداء من نساء مسلمات مسجونات في إحدى الدول الإسلامية طلبنا من المسلمين تفجير السجون، والمعتقلات التي فيها حيث انتهكت أعراضهن، وحيث الآن هم حبالى من زنا حيث أجبرن على ذلك داخل السجون، فما هو حكم قتل النفس في تلك الحال، وتلك النسوة اللاتي ابتلين بذلك؟","title":"حكم قتل المسلم نفسه خوفاً من التعذيب","answer":"الجواب: قتل النفس بين الله  النهي عنه، وهكذا رسوله -عليه الصلاة والسلام- والله يقول: وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29]. والنبي ﷺ حذر من قتل النفس، وأخبر عن رجل اشتد به الجرح، فقتل نفسه، فقال: قال الله -جل وعلا-: بادرني عبدي بنفسه حرمت عليه الجنة. فقتل النفس لا يجوز، ولا يحل للإنسان إذا ابتلي أن يقتل نفسه، كما إذا ابتلي بالفاحشة، أو بشيء آخر لا يحل له قتل نفسه، أو بالسجن، ولكن عليها أن تدافع ما استطاعت. وهكذا الرجل قد يبتلى باللواط، أو غيره، فيدافع عن نفسه ما استطاع، ولو أفضى إلى أن يقتل، لكن لا يقتل نفسه هو يدافع، ولا يمكن من نفسه، لا من اللواط، ولا من الفاحشة، فإن قتله صاحب الجريمة؛ فهو شهيد، النبي ﷺ قال: من قتل دون ماله فهو شهيد، من قتل دون دينه فهو شهيد، من قتل دون دمه فهو شهيد وجاءه رجل قال: يا رسول الله، الرجل يأتيني يريد مالي؟ -مال ما هو بنفس- قال: لا تعطه مالك قال: فإن قاتلني قال: قاتله قال: فإن قتلته قال: فهو في النار قال: فإن قتلني، قال: فأنت في الجنة. فدل ذلك على أن المظلوم يقاتل، ويدافع، فإن نجح فالمجرم في النار -نعوذ بالله- وإن لم ينجح المدافع، بل قتل لحكمة من الله بالغة، ولحكمة عظيمة، ولأسرار لا نعلمها فهو شهيد، فقد قتل عمر؛ وهو أفضل الناس بعد الصديق، وبعد الأنبياء، قتل في المحراب وهو يصلي بالناس لحكمة بالغة، سلط عليه رجل كافر يقال له: أبو لؤلؤة من المجوس، لأسباب حُكْمٍ حَكَمَ به عليه عمر، رضي الله عنه وأرضاه.  فالقتل قد يقع للأخيار، وقد يقع لغير الأخيار، قد يقتل الإنسان، ويبتلى كما قتل بعض الرسل، بعض الأنبياء قتل، وهو أشرف الناس، كما أخبر الله في كتابه العظيم عن اليهود أنهم يقتلون الأنبياء بغير حق، وهكذا بعض الأخيار، كعمر، وعثمان، وعلي الثلاثة قتلوا بغير حق، الزبير، وطلحة بن عبيدالله.  المقصود: أن قتل المظلوم أمر معلوم، وصاحبه شهيد، والمجرم إذا قتل فإلى النار، فمن ابتلي في نفسه؛ فعليه الدفاع، وعليه الصبر، والمدافعة بقوة، وإذا أمكن أن يقتل المجرم فليقتل المجرم، إذا لم يندفع إلا بالقتل قتله، وإن اندفع بالكلام كالتحذير من مغبة أهل الجريمة؛ فالحمد لله، وإن لم يندفع إلا بالقتل كخنقة، أو طعنة بالسكين، أو بغير هذا فعل ذلك، وهو برئ منه، وهو إلى النار -نعوذ بالله- أما من غلبه المجرم، وقتله المجرم؛ فهو شهيد، وإلى الجنة.","link":"https://binbaz.org.sa/fatwas/1112/حكم-قتل-المسلم-نفسه-خوفا-من-التعذيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_118.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":5799,"question":"أودعت بعضًا من المال في شركة الذهب، وذلك للبيع والشراء في هذا المال مقابل 1% من الربح للشركة، مع العلم أن الشركة لا تضمن الربح، ولا الخسارة؟","title":"حكم إيداع الأموال بشركة مقابل نسبة من الأرباح","answer":"الجواب:  إذا تعاقدت مع  الشركة على أنها تعمل في ذهبك، أو فضتك، أو في دراهمك الورقية، تعمل بها ولها 1% من الربح، والباقي لك فلا بأس، 1% يعني عشر العشر، لا بأس. إذا عملت الشركة بالبيع والشراء، وحصل فائدة أعطيتها 1000 وحصل من الألف مائة يكون لها ريال من المائة لا بأس. أما أنها تأخذ هي المائة من رأس المال، أو تضمن لك ريالًا في المائة ما يجوز، لكن إذا كان من الربح العمل على أن يكون الربح 1% أو 5% أو 10%، المقصود شيء معلوم فلا بأس، شيء معلوم مشاع.","link":"https://binbaz.org.sa/fatwas/1122/حكم-ايداع-الاموال-بشركة-مقابل-نسبة-من-الارباح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_128.mp3","categories":["قضايا معاصرة","الشركة"]},{"id":5878,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":5880,"question":"في بعض الدول لا يستطيع المسلم أن يهاجر من بلده، وذلك لنظام البلد نفسه، ولا يسمحون له بالخروج منها، فكيف يهاجر من بلده إذا كان يلقى المضايقة في دينه؟","title":"حكم من لم يستطع الهجرة من بلاد الكفر","answer":"الجواب: أما سمعت الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول: لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286].  ويقول النبي ﷺ: إذا أمرتكم بأمر؛ فأتوا منه ما استطعتم فالله يأمر في كتابه العظيم لما ذكر الهجرة قال: إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ [النساء:98] فالمستضعف قد يكون بجهله، وعدم بصيرته في الطرق، وقد يكون لقلة النفقة، وقد يكون لنظام الدولة، يكون نظام الدولة مانعًا من الخروج، فيكون عذرًا له. فإذا وجد طريقًا للهجرة؛ فعل ذلك، والله يعلم ما في الضمائر، ويعلم ما في الحقائق  ومن صدق في طلب الهجرة؛ يسر الله أمره، ومن عجز؛ فهو معذور، فليتق الله في مقامه، وليحرص على الاختلاط بالأخيار، والطيبين من المسلمين، وليبتعد عن الأشرار، فهذا نوع من الهجرة وهو في بلاده.","link":"https://binbaz.org.sa/fatwas/1228/حكم-من-لم-يستطع-الهجرة-من-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_225.mp3","categories":["قضايا معاصرة"]},{"id":5881,"question":"يوجد في بعض المكاتب صور بعض الزعماء، والملوك مبروزة، هل هذه الصور يجوز في هذه المكاتب أن توضع؟","title":"حكم تعليق صور الملوك والزعماء","answer":"الجواب:  هذه الصور مما لا يجوز، وقد نبه ولاة الأمور على ذلك، ونسأل الله لهم التوفيق، فنصب الصور في المكاتب، والدوائر لا يجوز ذلك، ويخشى أن يكون ذلك وسيلة للشرك؛ لأن كثيرًا من الدول غير المسلمة ينصبون هذه الصور في الميادين، في المحلات التي يريدون، ويخشى منها أن يقع فيها الشرك بعد حين، كما فعل قوم نوح.   قوم نوح جاءهم الشيطان لما مات خمسة صالحون، وكانوا على التوحيد، فلما مات فيهم خمسة من الصالحين، وهم: ود، وسواع، ويغوث، ويعوق، ونسرًا، دس عليهم الشيطان لما رأى حزنهم، وبكاءهم عليهم دس عليهم الشيطان، وقال: صوروا صورهم، وانصبوها في مجالسهم حتى تذكروا عباداتهم، وتذكروا أعمالهم، فصورها، ثم طالت حتى عبدوهم من دون الله، نسأل الله السلامة. فيخشى من هذه الصور أن يطول الأمد، أن تعبد من دون الله، ولاسيما مع الجهل الكثير في الناس، ولاسيما مع حب الدنيا، والحرص على التقرب إليها بكل وسيلة.  فالذي نعتقد: أن هذا لا يجوز نصب هذه الصور في المكاتب، ولا في الدوائر، ولا في الميادين، والواجب على ولاة الأمور إزالتها، ونسأل الله أن يوفقهم لذلك، وأن يعينهم على كل خير، وأن يوفقهم لما فيه صلاح العباد، والبلاد.","link":"https://binbaz.org.sa/fatwas/1206/حكم-تعليق-صور-الملوك-والزعماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_202.mp3","categories":["الصور والتصوير","قضايا معاصرة"]},{"id":5887,"question":"في بعض الدول لا يستطيع المسلم أن يهاجر من بلده، وذلك لنظام البلد نفسه، ولا يسمحون له بالخروج منها، فكيف يهاجر من بلده إذا كان يلقى المضايقة في دينه؟","title":"حكم من لم يستطع الهجرة من بلاد الكفر","answer":"الجواب: أما سمعت الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول: لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286].  ويقول النبي ﷺ: إذا أمرتكم بأمر؛ فأتوا منه ما استطعتم فالله يأمر في كتابه العظيم لما ذكر الهجرة قال: إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ [النساء:98] فالمستضعف قد يكون بجهله، وعدم بصيرته في الطرق، وقد يكون لقلة النفقة، وقد يكون لنظام الدولة، يكون نظام الدولة مانعًا من الخروج، فيكون عذرًا له. فإذا وجد طريقًا للهجرة؛ فعل ذلك، والله يعلم ما في الضمائر، ويعلم ما في الحقائق  ومن صدق في طلب الهجرة؛ يسر الله أمره، ومن عجز؛ فهو معذور، فليتق الله في مقامه، وليحرص على الاختلاط بالأخيار، والطيبين من المسلمين، وليبتعد عن الأشرار، فهذا نوع من الهجرة وهو في بلاده.","link":"https://binbaz.org.sa/fatwas/1228/حكم-من-لم-يستطع-الهجرة-من-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_225.mp3","categories":["قضايا معاصرة"]},{"id":5888,"question":"يوجد في بعض المكاتب صور بعض الزعماء، والملوك مبروزة، هل هذه الصور يجوز في هذه المكاتب أن توضع؟","title":"حكم تعليق صور الملوك والزعماء","answer":"الجواب:  هذه الصور مما لا يجوز، وقد نبه ولاة الأمور على ذلك، ونسأل الله لهم التوفيق، فنصب الصور في المكاتب، والدوائر لا يجوز ذلك، ويخشى أن يكون ذلك وسيلة للشرك؛ لأن كثيرًا من الدول غير المسلمة ينصبون هذه الصور في الميادين، في المحلات التي يريدون، ويخشى منها أن يقع فيها الشرك بعد حين، كما فعل قوم نوح.   قوم نوح جاءهم الشيطان لما مات خمسة صالحون، وكانوا على التوحيد، فلما مات فيهم خمسة من الصالحين، وهم: ود، وسواع، ويغوث، ويعوق، ونسرًا، دس عليهم الشيطان لما رأى حزنهم، وبكاءهم عليهم دس عليهم الشيطان، وقال: صوروا صورهم، وانصبوها في مجالسهم حتى تذكروا عباداتهم، وتذكروا أعمالهم، فصورها، ثم طالت حتى عبدوهم من دون الله، نسأل الله السلامة. فيخشى من هذه الصور أن يطول الأمد، أن تعبد من دون الله، ولاسيما مع الجهل الكثير في الناس، ولاسيما مع حب الدنيا، والحرص على التقرب إليها بكل وسيلة.  فالذي نعتقد: أن هذا لا يجوز نصب هذه الصور في المكاتب، ولا في الدوائر، ولا في الميادين، والواجب على ولاة الأمور إزالتها، ونسأل الله أن يوفقهم لذلك، وأن يعينهم على كل خير، وأن يوفقهم لما فيه صلاح العباد، والبلاد.","link":"https://binbaz.org.sa/fatwas/1206/حكم-تعليق-صور-الملوك-والزعماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_202.mp3","categories":["الصور والتصوير","قضايا معاصرة"]},{"id":5890,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":5956,"question":"ما حكم شراء التلفزيون؟ وما حكم اقتنائه، وإدخاله المنزل، واستعماله في البرامج الدينية؟ وهل يجوز لي بيع المسجلات، والتلفزيونات، والراديوهات، والمسجلات، والأشرطة الفاضية، نرجو بيان ذلك؟","title":"حكم شراء وبيع واقتناء التلفاز والمسجل","answer":"الجواب: التلفاز فيه شر عظيم؛ وفيه بعض المصالح، والخير، فالذي ننصح به تجنبه، وعدم اقتنائه لما قد يقع فيه من الشرور من الأغاني، وآلات الملاهي، وبروز النساء السافرات غير محتجبات، وما يقع فيه من بعض المسلسلات الرديئة؛ فهذا هو السبب الذي ينبغي ألا يقتنى من أجله. أما لو قدر أن إنسانًا سيطر عليه، ولم يسمعه منه إلا الطيب، فهذا إذا أمكن لا بأس، لكنه لا يمكن في الغالب؛ لأنه يجر بعضه إلى بعض.  كذلك ما يتعلق بالمسجلات، إذا كان المسجل فيه الأغاني، والمنكرات لا يجوز، أما مسجلات عادية ليس فيها شيء فلا بأس أن يسجل فيها الطيب، والرديء، فالمسجل يباع، ويشترى، لا بأس به، ولكن لا ينبغي أن يسجل فيه إلا الطيب لا يسجل فيه الأشياء الرديئة.  وأما الفيديو كذلك يجب أن يحذر؛ لأن فيه ينظر الأفلام الخبيثة، فينبغي أن يحذر، ولا يقتنى بالكلية؛ لأنه وسيلة إلى شر عظيم، اللهم إلا فيديو يسجل فيه خيرًا ينفع المسلمين في الدعوة إلى الله، والقيام بما ينفع المسلمين، وهذا بين الناس نادر، المرغوب بين الناس هو الشر.","link":"https://binbaz.org.sa/fatwas/1330/حكم-شراء-وبيع-واقتناء-التلفاز-والمسجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_299.mp3","categories":["قضايا معاصرة"]},{"id":5987,"question":"رجل أودع مالًا في بنك من البنوك الربوية آجل، ويقول له لما استلم رأس ماله، أعطاه ربح، فهو حيران في الربح هذا أيش يعمل؟","title":"حكم إيداع المال في البنوك وأخذ الزيادة","answer":"الجواب: البنوك الربوية لا يودع فيها إلا عند الضرورة، فإذا أودع عندهم للضرورة؛ فلا يأخذ الربح، لا يأخذ الفوائد؛ لأنها ربًا، ولا يحل له أن يأخذ الربا. ولكن بعض أهل العلم قالوا: إذا أخذ الفائدة التي ما اشترطها، ولا اتفق معهم عليها، ولكن قالوا: هذه الفائدة لك، إذا أخذها، وصرفها في جهة بر لمواساة فقير، أو إصلاح طريق، أو ما أشبه ذلك من شيء ينفع المسلمين، ولا يأكلها، ولا يخلطها بماله، بل يصرفها في وجه البر، قال بعض أهل العلم: إن  هذا لا بأس به؛ لأجل مصلحة المسلمين؛ ولئلا يأخذها النصارى، وغيرهم، فيصرفونها في معاصي الله، هذا قاله بعض أهل العلم.  .. إذا أخذه، واحتاط، وصرف ذلك في جهة البر، وهو لم يشارطهم، ولم يرض بذلك؛ فهذا له وجه، أما أن يتفق معهم على الربا، أو يأخذ الربا لنفسه، أو لماله، أو يخلطه بماله، فهذا لا يجوز. السؤال: وإن كان عن جهل يا شيخ؟ الجواب:  ولو عن جهل، لا يأخذه.  السؤال: وبعدين أخذه؟ الجواب:  يتصدق به على الفقراء، والمساكين.","link":"https://binbaz.org.sa/fatwas/1364/حكم-ايداع-المال-في-البنوك-واخذ-الزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_322.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":5996,"question":"فضيلة الشيخ إن جنود المسلمين الآن لا يمسون إلا على الأفلام الخليعة، وثقافاتهم الدينية ضحلة جدًا، أليس هذا من التقصير في الأخذ بالأسباب؟ والمسلمون الذين يريدون الجهاد لا يعرفون أن يرموا بحجر؛ لأن في كثير من البلاد السلاح ممنوع شراؤه، وحمله، والتدريب عليه؟ فإذا دعا داع الجهاد فكيف تكون الحالة؟","title":"حقيقة الجيوش العربية والإسلامية وكيفية إعدادهم","answer":"الجواب:  هذا من أعظم الأسباب لعدم الإعداد، الإقبال على الشهوات، وعلى الأفلام الخليعة، وعلى الإذاعات، والتلفزة، والمسجلات الخبيثة، وشغل الوقت بها عن طاعة الله، ورسوله؛ فهذا من أعظم الخسارة، ومن أعظم أسباب تسليط الأعداء، ومن أعظم أسباب حلول العقوبات، نعوذ بالله من ذلك. وكذلك كون الإنسان لا يتدرب، ولا يجد من يدربه على السلاح، وعلى الجهاد في سبيل الله، ويدرب بدنه على حمل السلاح، فهذا أيضًا من المصائب، والنكبات، فيجب على كل دولة أن تدرب رجالها، وشبابها حتى يكونوا عدة صالحة للجهاد، والقتال، وأن لا يهملوا، فإذا استعدوا وقت نزول الكارثة لا ينفع إنما يستعدون قبل ذلك بالإعداد، والتدريب، حتى إذا جاءت الحاجة، ونزلت النازلة، إذا هو صالح للعمل، وصالح للجهاد.  نسأل الله أن يوفق ولاة المسلمين لهذا الأمر، وأن يعدل الشباب، ومن فيه القوة أن يطالب بذلك، ويعتني بذلك، حتى يكون صالحًا للجهاد، وحتى يكون مدربًا إذا جاءت الحقائق، وجاء أعداء الله، أو أريد قتال أعداء الله.","link":"https://binbaz.org.sa/fatwas/1398/حقيقة-الجيوش-العربية-والاسلامية-وكيفية-اعدادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_353.mp3","categories":["الجهاد والسير","قضايا معاصرة"]},{"id":6001,"question":"قرأت مقالًا لأحد العلماء أن ما يمر بالمسلمين من تسلط للأعداء، واحتلال لمقدساتهم أنه فرض عين على كل مسلم في الدفاع عما هم فيه من اضطهاد، فما رأيكم في هذا، أجيبونا، جزاكم الله خيرًا؟","title":"واجب المسلمين في الدفاع عن دينهم وأرضهم","answer":"الجواب: سبق الكلام في هذا، وأن الواجب على المسلمين: التكاتف، والتعاون ضد أعدائهم؛ لإنقاذ بلادهم من أيدي اليهود، وغير ذلك، يجب على المسلمين التكاتف، والتعاون لجهاد أعداء الله؛ لاستنقاذ البلاد التي هي لليهود، ولقتال كل من خرج عن دين الله، ولم يحكم شريعة الله.","link":"https://binbaz.org.sa/fatwas/1393/واجب-المسلمين-في-الدفاع-عن-دينهم-وارضهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_349.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6024,"question":"رجل وضع مبلغًا من المال في بنك من البنوك على سبيل الوديعة، بدون فائدة، ولكنه اكتشف فيما بعد أن هذا البنك يعمل، ويشتغل في مشاريع محرمة؟","title":"حكم إيداع الأموال في البنوك الربوية بدون أخذ فائدة","answer":"الجواب: ينبغي حفظ الأموال، وأن لا تودع في البنوك التي ترابي مهما أمكن، لكن إن اضطر إلى ذلك جعلها عند البنك ليحفظها فقط، ولا يرضى بالربا، ولا يريد الربا، ولا يأخذ الفائدة، فأرجو ألا يكون عليه حرج؛ للضرورة، لحفظ الأموال في البنوك الآن؛لأن بعض الناس لو وضع في بيته؛ يخشى عليه الذهاب، والسرقة. فالحاصل: أنه إذا كانت الضرورة جعل المال فيها للضرورة، ولا يريد فائدة من ذلك؛ فلا شيء عليه. السؤال: والراجحي؟ الجواب: الراجحي ما نعلم فيه، لا بأس، الراجحي، والسبيعي، وأشباههم ما نعلم فيه شيء، ما نعلم إلا خيرًا.","link":"https://binbaz.org.sa/fatwas/1374/حكم-ايداع-الاموال-في-البنوك-الربوية-بدون-اخذ-فاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_332.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":6034,"question":"فضيلة الشيخ أثابه الله، أليس من أسباب تسلط الكفار على المسلمين: عدم رفع راية الجهاد الإسلامي، ورفع راية التوحيد سبب هام، أم لا؟ وكذلك بعثات الشباب إلى الخارج دون أن يفهموا الإسلام فهمًا صحيحًا؛ حتى يصيروا في الخارج مؤثرين، لا متأثرين؟","title":"أسباب تسلط الكفار على المسلمين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، أما بعد: فقد ذكر فضيلة الأخ الشيخ سعود، وذكرت أيضًا أنا بعده أن المذكور هو بعض الأسباب، لا كل الأسباب، الشيخ سعود ذكر بعض الأسباب، وأنا كذلك أيدت ما ذكره من الأسباب، وزدت بعض الشيء من الأسباب، وهناك أسباب أخرى. ولا شك أن من الأسباب في تسلط الأعداء: عدم قيام المسلمين بالجهاد، وإنما تركوا الجهاد بسبب التفرق الذي أشرنا إليه، لما تفرقوا، ولم يجتمعوا على كلمة، بل صاروا أحزابًا، وأقسامًا، لم يتيسر رفع راية الجهاد والاجتماع على الجهاد.  والدولة الصغيرة التي ليس عندها من القوة، والقدرة ما تجاهد به يكون الجهاد في حقها غير متيسر، لكن لو تجمع أولئك القادة، وتعاونوا؛ أمكنهم أن يجاهدوا عدوهم، وأمكنهم أن ينصروا على عدوهم إذا صدقوا، وأخلصوا، ونصحوا لله. فالتفرق، والاختلاف، وعدم الاجتماع هو من أعظم أسباب، ترك الجهاد، وعدم رفع رايته، وكذلك البعثات التي تبعث إلى الخارج من الشباب لا شك أنها من الأسباب التي تضر المسلمين، فإن أغلب الشباب إذا ذهبوا إلى هناك؛ يملي عليهم الأعداء عقائدهم الخبيثة، وأخلاقهم المنحرفة، فيرجع الكثير منهم، أو أكثرهم قد تغيرت عقيدته، وتغير مزاجه، وتغيرت أخلاقه؛ فيصير حربًا على المسلمين، وضدًا للمسلمين، ويكون أيضاً جندًا لأعداء الله على أولياء الله، هذا هو الغالب، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1437/اسباب-تسلط-الكفار-على-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_374.mp3","categories":["قضايا معاصرة","مسائل متفرقة في العقيدة"]},{"id":6049,"question":"فضيلة الشيخ -أثابه الله- أما بعد: ألا ترى أن عدم فهم علماء الإسلام، وطلبة العلم لخطط الكافرين، وتنبيه الناس عليها؛ لكي لا يقعوا فيها، هو من أسباب تسلط الكفار عليهم؟","title":"عاقبة الغفلة عن مكائد الكفار","answer":"الجواب: تقدمت الإشارة إلى هذا أن الغفلة عن إرساليات الكفار، وعن مكائدهم، غفلة المسؤولين من القادة، وبعض العلماء، وبعض الأعيان غفلتهم -لا شك- أنها من أسباب تسلط الأعداء، وانتشار شرهم.  وهكذا إيثار الحظ العاجل، وقد يعلمون مكائدهم، وقد يعرف بعض القادة، ويعرف بعض الأعيان مكائدهم، ولكن يؤثروا حظهم العاجل، وما تمليه عليه نفسه من الباطل على رفض دين الله، بسبب جهله، وانحرافه، وعدم بصيرته، وعدم -أيضًا- قوة إيمانه، أو عدم إيمانه بالكلية، وإنما يدعي الإسلام دعوى، والحقيقة غير ذلك.","link":"https://binbaz.org.sa/fatwas/1448/عاقبة-الغفلة-عن-مكاىد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_376.mp3","categories":["قضايا معاصرة"]},{"id":6052,"question":"يسأل كذلك عن الدجاج المستورد من الخارج سيما أن اللحم غال الآن، وهم في حاجة لأكل الدجاج؟","title":"حكم اللحوم المستوردة بحسب بلادها","answer":"الجواب: اللحم الخارجي أقسام: ما كان من البلاد الشيوعية، والبلاد الوثنية، كالهندوس، والشيوعيين .. هذا لا يؤكل حتى نعلم أنه ذبحه مسلم، أو كتابي، أما ما ورد من بلاد النصارى، كالفرنسية والأمريكان، فالأصل فيه الحل، حتى نعلم أنه ذبح على غير الشرع، وأما إذا كنا لا نعلم؛ فالأصل في ذبائح أهل الكتاب هو الحل، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/1466/حكم-اللحوم-المستوردة-بحسب-بلادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_396.mp3","categories":["قضايا معاصرة","الذكاة والصيد"]},{"id":6075,"question":"فضيلة شيخي ما حكم من يحاول التفريق بين المسلمين بقوله: هذا قبيلي، وهذا خضيري، وهكذا؟ ومن هو القبيلي، ومن هو الخضيري؟","title":"حكم التفريق بين القبيلي والخضيري","answer":"الجواب: هذه مسألة جزئية، ما لها كبير شيء، هذه مسائل بين الناس معروفة، وقبيلي الذي له قبيلة معروفة ينتمي إليها: كالقحطاني، والسبيعي، والتميمي، وشبه ذلك، والقرشي، والهاشمي، وأشباه ذلك، هذا يسمى قبيلي، ويقال: قبلي على القاعدة، ويقال: حنفي، وربعي، وأشباه ذلك نسبة إلى القبيلة التي ينتمي إليها. والخضيري عند الناس، في نجد خاصة، ولا أعرفها إلا في نجد، أما في غير نجد ما أعرف هذه الكلمة، لكن في نجد معروفة، الخضيري عندهم هو الذي ليس له قبيلة معروفة ينتمي إليها، عربي، ولكن ليس له قبيلة معروفة، ليس معروفًا بأنه مثلًا قحطاني، أو تميمي، أو قرشي، لكن هو عربي، ولسانه عربي، ومن العرب، وعاش بينهم، ولو كانت حمولته معروفة، وجماعته معروفة، لكن إذا كان ليس له قبيلة معروفة ينتمي إليها، فيقال له: خضيري. والمولى في عرف العرب هو الذي أصله عبد مملوك، فأعتق، فيقال لهم: موالي، والعجم هم الذين لا ينتسبون إلى العرب، يقال: أعجمي، ويكون من أصله أعجمي، لا كون من أصول عربية، يقال لهم: أعاجم. والحكم في دين الله أنه لا فرق لأحد منهم على أحد إلا بالتقوى، سواء سمي قبليًا، أو خضريًا، أو مولى، أو أعجميًا، كلهم على حد سواء، كلهم، لا فضل لهذا على هذا، ولا هذا على هذا إلا بالتقوى، كما قال النبي ﷺ: لا فضل لعربي على أعجمي، ولا أعجمي على عربي إلا بالتقوى، ولا فضل لأحمر على أسود، ولا أسود على أحمر إلا بالتقوى كما قال الله : يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات: 13]  لكن من عادة العرب قديمًا أنهم يزوجون بناتهم للقبائل التي يعرفونها، ويقف بعضهم عن تزويج من ليس من القبائل التي لا يعرفها، وهذا باق في  الناس إذا كان ليس من قبيلة يعرفها، لم يسمح أن يزوجه بنته إلا إذا كان من قبيلة يعرفها، أو من جنس القبائل العربية التي يعرفونها، وقد يتسامح بعضهم، ويزوج الخضيري، والمولى، والأعجمي، كما جرى في عهد النبي ﷺ فإن النبي ﷺ زوج أسامة بن زيد بن حارثة، وهو مولاه، وعتيقه، زوجه فاطمة بنت قيس، وهي قرشية. وكذلك أبو حذيفة بن عتبة بن ربيعة، وهو من قريش زوج مولاه سالم مولى أبي حذيفة بنت أخيه الوليد بن عتبة، ولم يبال بكونه مولى عتيقًا، وهذا جار في الصحابة، وبعدهم كثير. أما الناس بعد ذلك -خصوصًا في نجد- وفي بعض المواضع الأخرى -الله أعلم بها- قد يقفون عن هذا، ويشددون في هذا الشيء على حسب ما ورثوه من آبائهم، وأسلافهم، وربما خاف بعضهم من إيذاء بعض قبيلته إذا قالوا له: لم زوجت فلانًا، فهذا قد يفضي إلى الإخلال بقبيلتنا، وأن تختلط الأنساب، وتضيع الأنساب إلى غير ذلك. قد يعتذرون بأعذار في الزواج له وجهها في بعض الأحيان، ولا يضر هذا، وأمره سهل، المهم اختيار من يصلح للمصاهرة في دينه، وخلقه، فإذا حصل هذا؛ فهو الذي ينبغي، سواء كان عربيًا، أو أعجميًا، أو مولى، أو خضريًا، أو غير ذلك هذا هو الأساس، وإذا رغب بعض الناس ألا يزوج إلا من قبيلته؛ فلا نعلم حرجًا في ذلك.","link":"https://binbaz.org.sa/fatwas/1494/حكم-التفريق-بين-القبيلي-والخضيري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_424.mp3","categories":["قضايا معاصرة"]},{"id":6077,"question":"سماحة المفتي، السجون الإسلامية تنخر في الشباب المسلم، والعبارات كثيرة.. هذه عبارته، يعني هو يتألم بأن السجون الإسلامية تنخر في الشباب المسلم ...؟","title":"أحوال الناس في السجون تتفاوت بحسب ثبوت تهمتهم","answer":"الجواب: أكثر الولاة اليوم ليس عندهم تحكيم الشريعة الإسلامية فيما يقولون، ويفعلون، فأكثر ولاة الأمور المنتسبين للإسلام لا يحكمون الشريعة الإسلامية، بل حكموا القوانين الوضعية، وحكموا الكثير من أهوائهم، ولم يحكموا شريعة الله  فلا يستغرب أن يكون في السجون من المسلمين من لا يحصى لأسباب كثيرة.  ثم المسلم قد يفعل ما يوجب سجنه، وإن كانت الدولة حاكمة بشرع الله، فالمسلم قد يتعاطى ما يوجب سجنه من عدوانه على بعض الناس، ومن أخذه أموال الناس، وعدم أدائه... حتى يؤدي الدين، ومن عدوانه على .. حتى يقام عليه.. وما يستحق من تعزير، أو حد، أو نحو ذلك، فليس بمستنكر، إنما المستنكر أن يسجن بغير حق، أو يسجن في طاعة الله، ورسوله، هذا هو المستنكر.  أما كون السجون يوجد فيها مسلمون، فهذا من عهد النبي ﷺ وبعده، لا بدّ أن من تعدى الحدود -وإن كان مسلمًا- لا بدّ أن يمسك حتى ينفذ فيه أمر الله، وقد يطول سجنه، وقد يقصر على حسب حال الحاكم، وتنفيذه لشرع الله، وعلى حسب الجريمة قوة، وخفة، إلى غير ذلك من الأسباب.","link":"https://binbaz.org.sa/fatwas/1495/احوال-الناس-في-السجون-تتفاوت-بحسب-ثبوت-تهمتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_425.mp3","categories":["قضايا معاصرة"]},{"id":6084,"question":"فضيلة شيخي ما حكم من يحاول التفريق بين المسلمين بقوله: هذا قبيلي، وهذا خضيري، وهكذا؟ ومن هو القبيلي، ومن هو الخضيري؟","title":"حكم التفريق بين القبيلي والخضيري","answer":"الجواب: هذه مسألة جزئية، ما لها كبير شيء، هذه مسائل بين الناس معروفة، وقبيلي الذي له قبيلة معروفة ينتمي إليها: كالقحطاني، والسبيعي، والتميمي، وشبه ذلك، والقرشي، والهاشمي، وأشباه ذلك، هذا يسمى قبيلي، ويقال: قبلي على القاعدة، ويقال: حنفي، وربعي، وأشباه ذلك نسبة إلى القبيلة التي ينتمي إليها. والخضيري عند الناس، في نجد خاصة، ولا أعرفها إلا في نجد، أما في غير نجد ما أعرف هذه الكلمة، لكن في نجد معروفة، الخضيري عندهم هو الذي ليس له قبيلة معروفة ينتمي إليها، عربي، ولكن ليس له قبيلة معروفة، ليس معروفًا بأنه مثلًا قحطاني، أو تميمي، أو قرشي، لكن هو عربي، ولسانه عربي، ومن العرب، وعاش بينهم، ولو كانت حمولته معروفة، وجماعته معروفة، لكن إذا كان ليس له قبيلة معروفة ينتمي إليها، فيقال له: خضيري. والمولى في عرف العرب هو الذي أصله عبد مملوك، فأعتق، فيقال لهم: موالي، والعجم هم الذين لا ينتسبون إلى العرب، يقال: أعجمي، ويكون من أصله أعجمي، لا كون من أصول عربية، يقال لهم: أعاجم. والحكم في دين الله أنه لا فرق لأحد منهم على أحد إلا بالتقوى، سواء سمي قبليًا، أو خضريًا، أو مولى، أو أعجميًا، كلهم على حد سواء، كلهم، لا فضل لهذا على هذا، ولا هذا على هذا إلا بالتقوى، كما قال النبي ﷺ: لا فضل لعربي على أعجمي، ولا أعجمي على عربي إلا بالتقوى، ولا فضل لأحمر على أسود، ولا أسود على أحمر إلا بالتقوى كما قال الله : يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات: 13]  لكن من عادة العرب قديمًا أنهم يزوجون بناتهم للقبائل التي يعرفونها، ويقف بعضهم عن تزويج من ليس من القبائل التي لا يعرفها، وهذا باق في  الناس إذا كان ليس من قبيلة يعرفها، لم يسمح أن يزوجه بنته إلا إذا كان من قبيلة يعرفها، أو من جنس القبائل العربية التي يعرفونها، وقد يتسامح بعضهم، ويزوج الخضيري، والمولى، والأعجمي، كما جرى في عهد النبي ﷺ فإن النبي ﷺ زوج أسامة بن زيد بن حارثة، وهو مولاه، وعتيقه، زوجه فاطمة بنت قيس، وهي قرشية. وكذلك أبو حذيفة بن عتبة بن ربيعة، وهو من قريش زوج مولاه سالم مولى أبي حذيفة بنت أخيه الوليد بن عتبة، ولم يبال بكونه مولى عتيقًا، وهذا جار في الصحابة، وبعدهم كثير. أما الناس بعد ذلك -خصوصًا في نجد- وفي بعض المواضع الأخرى -الله أعلم بها- قد يقفون عن هذا، ويشددون في هذا الشيء على حسب ما ورثوه من آبائهم، وأسلافهم، وربما خاف بعضهم من إيذاء بعض قبيلته إذا قالوا له: لم زوجت فلانًا، فهذا قد يفضي إلى الإخلال بقبيلتنا، وأن تختلط الأنساب، وتضيع الأنساب إلى غير ذلك. قد يعتذرون بأعذار في الزواج له وجهها في بعض الأحيان، ولا يضر هذا، وأمره سهل، المهم اختيار من يصلح للمصاهرة في دينه، وخلقه، فإذا حصل هذا؛ فهو الذي ينبغي، سواء كان عربيًا، أو أعجميًا، أو مولى، أو خضريًا، أو غير ذلك هذا هو الأساس، وإذا رغب بعض الناس ألا يزوج إلا من قبيلته؛ فلا نعلم حرجًا في ذلك.","link":"https://binbaz.org.sa/fatwas/1494/حكم-التفريق-بين-القبيلي-والخضيري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_424.mp3","categories":["قضايا معاصرة"]},{"id":6101,"question":"ما حكم أخذ الفوائد من البنوك الربوية، وصرفها في وجوه خيرية؟","title":"حكم أخذ الفوائد الربوية وصرفها في وجوه خيرية","answer":"الجواب: لا يجوز للمسلم أن يتفق مع البنوك، ومع غيرها على فوائد؛ لأنها ربا، فالذي أودع عندهم مالًا يودعه على أنه ليس له فائدة، بل لحفظه عند المودع، أو ليتصرف فيه المودع، ويعتبره قرضًا عنده، ثم ...على الحساب الجاري يأخذ حاجاته، ولا يأخذ له فوائد، أما الاتفاق معهم على فوائد فلا يجوز، ولو قال: إنه يصرفها في وجوه خيرية، أو المشاريع الخيرية لا يجوز له هذا. لكن لو قدر أنه جهل هذا الأمر، وقبضها، وما درى، وهو يحسب أنه جائز؛ فإنه لا يردها إلى البنك، ولا يردها إلى المصرف، بل تصرف في الفقراء، والمحاويج، ومثل إصلاح الطرقات، ومثل إصلاح مشاريع تنفع المسلمين ... يشرب منها الناس، أو طرق ينتفع بها الناس، مثل مهر البغي، ومثل حلوان الكاهن، ومثل المكوس التي أخذتها الدولة، ثم هداها الله، وتركتها تصرف في الوجوه الخيرية التي تنفع المسلمين، ومثل المال الضائع الذي ذهب صاحبه، ولم يعرف، وأشباه ذلك لا ترد إلى أصحابها.  وهكذا من أعطاه الكاهن من المال لإخباره بعض المغيبات، ليس له أن يأكله، ولا أن يعيده إلى صاحبه، بل يصرف في وجوه الخير من مواساة الفقير، والمسكين ونحو ذلك، ومثل هذا مهر البغي ما تعطاه المهر لأجل الزنى حرام عليها -نعوذ بالله- لكن لا ترده إلى صاحبه إذا أخذته، لا ترده، ولكن يصرف في جهة أخرى كمواساة الفقير، ولا يخبر أنه كذا وكذا، فهو بالنسبة إلى الفقير، ونحوه حل له؛ لأنه مال ضائع، مال لا صاحب له، لكن الذي أخذه بوجه محرم، فلا يستعمله، وإذا صرفه لفقير، ومسكين حل له؛ لأنه بمثابة المال الضائع الذي يصرف في جهة خيرية تنتفع به.","link":"https://binbaz.org.sa/fatwas/1516/حكم-اخذ-الفواىد-الربوية-وصرفها-في-وجوه-خيرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_446.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":6113,"question":"أخيرًا نفذ حكم الإعدام في ثلاثة أشخاص في الكويت بطريقة الشنق، هل هذا موافق للشرع؟","title":"حكم الإعدام بالشنق","answer":"الجواب: الذي يظهر أن الذي ينبغي في الإعدام ما هو الأسهل، النبي ﷺ قال: إذا قتلتم؛ فأحسنوا القتلة والذي بلغنا أن الشنق غير طيب، وأن فيه تعذيب، فلا ينبغي الشنق، هذا تأسي بأعداء الله، بل ينبغي أن يقتلوا بالسيف؛ لأن قتلة السيف بيد الرجل العارف، والسيف الجيد يريح أكثر، وينهي الموضوع بسرعة، فلا ينبغي أن يقتل بالشنق.","link":"https://binbaz.org.sa/fatwas/1528/حكم-الاعدام-بالشنق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_458.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6139,"question":"هل يجري الربا في غير المطعوم، والذهب، والفضة مثل: رجل يبيع سيارة بسيارتين، وكتابًا بكتابين، وشاة بشاتين؟","title":"جريان الربا في غير المكيلات والموزونات","answer":"الجواب:  لا، هذا ما هو من الربا، الربا في المطعومات .. مما يكال، ويدخر، وفي الموزونات المعتادة المعروفة، أما بيع السيارة بسيارتين، أو سيارة بإبل، أو سيارة ببيت، أو بأرض، أو سيارة بغنم، أو غنم بإبل، لا شيء، لا حرج في هذا.","link":"https://binbaz.org.sa/fatwas/1604/جريان-الربا-في-غير-المكيلات-والموزونات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_498.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6142,"question":"إنني سائق سيارة أجرة هي مصدر رزقي، وقد قضى الله بحكمه، وقدره، وقلبت بها، وتوفي معي أربعة أشخاص منهم: اثنان سامحوني في الدية، واثنان آمنت الدية لدى الدولة حيث إنهما لم يعرفا، هل علي صوم، أو صدقة؟","title":"حكم الكفارة على سائق انقلبت سيارته ومات من معه","answer":"الجواب:  إذا كنت السبب في موتهم؛ فعليك عتق رقبة، في كل واحد مؤمنة، فإن لم تجد؛ صمت عن كل واحد شهرين، عن الأربعة ثمانية أشهر، لكل واحد شهرين متتابعين، إذا كنت السبب مثل إذا كنت أسرعت حتى انقلبت، أسرعت في الطريق حتى صدمت، وانقلبت، أو ما أشبه ذلك، إذا كنت أنت السبب في هذا الانقلاب، أو كنت سكرانًا، أو ناعسًا، أو نائمًا، أو تأكل الحبوب الذي تغير شعور الإنسان، فانقلبت بسبب ذلك؛ فعليك الدية، والكفارة جميعًا. أما إذا كان ما لك تسبب، أمر غلبك من غير تسبب، وأنت تمشي في السير المعتاد، ولم تخالف الطريق، ولم تخالف النظم، بل تمشي وشعورك معك، ولكن قدر أن اختلت بهم السيارة من ذراع، أو غيره، أو بنشر، فحصل انقلاب بسبب ذلك من دون أسباب منك؛ فلا شيء عليك.","link":"https://binbaz.org.sa/fatwas/1610/حكم-الكفارة-على-ساىق-انقلبت-سيارته-ومات-من-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_504.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6145,"question":"أرجو شرح هذه العبارة (شروط النسيئة قبض أحد العوضين المتفاضلين الربويين قبل التفرق) وهل هذا الشرط لتجنب الوقوع في ربا النسيئة، أم هو شرط محرم، أفتونا جزاكم الله؟","title":"شروط بيع الربوي بمثله","answer":"الجواب:  هذا بينه الرسول ﷺ ربا الفضل محرم، مطلقًا في ربا الفضل، وفي ربا النسيئة إذا باع جنسًا بجنسه متفاضلًا؛ صار محرمًا بهذا الشيء، وإذا صار إلى أجل، وهو من جنس واحد؛ اجتمع فيه المعنيان ربا الفضل، وربا النسيئة. فشرط بيع الجنس من جنسه يدًا بيد إذا كان جنسًا بجنس متماثلًا؛ فلا بدّ أن يكون يدًا بيد، وإن كان من غير جنسه متفاضلًا؛ فلا بدّ أن يكون يدًا بيد، فهذا شرط للحل، والإباحة. لا يباع الجنس بغير جنسه مما اجتمع معه الوصف في العلة إلا بشرط التقابض، فإذا باع ذهبًا بفضة؛ فلا بد من التقابض يدًا بيد، أو باع تمرًا بشعير؛ فلا بدّ يد بيد، وإلا حرم ذلك؛ لأنه يصير في حكم النسيئة، وأعظم الربا ربا النسيئة، فإذا لم يتقابضا؛ ألحق بربا النسيئة؛ فحرم. فالله -جل وعلا- حرم النسيئة، فإذا لم يتقابضا؛ فهو ملحق بالنسيئة، وهو وسيلة إلى النسيئة، فلهذا حرم الله -جل وعلا- التفرق قبل التقابض، فلا يجوز بيع الربا بالربوي من جنسه، أو من غير جنسه متفاضلًا إلا يدًا بيد .. سواء كان من جنسه الذهب بالذهب، الفضة بالفضة، والتمر بالتمر، لا بدّ أن يكون يدًا بيد مع شرط التساوي، والتماثل، وإن كان بغير جنسه كالتمر بالشعير، والتمر بالملح، والذهب والفضة؛ فإنه يجوز التفاضل، لكن لا بدّ من يد بيد؛ حتى لا يلتحق بالربا.","link":"https://binbaz.org.sa/fatwas/1600/شروط-بيع-الربوي-بمثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_494.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6151,"question":"ما حكم التأمين على الأموال المستوردة من الخارج؟ كذلك التأمين على الأموال في المخازن ضد الأخطار، والتلف نظير مبلغ يأخذه المؤمن، ويضمنها في حالة التلف أليس هذا من الغرر؟","title":"حكم التأمين على الأموال المستوردة","answer":"الجواب:  التأمين من عقود الغرر من عقود الربا، وهو محرم، سواء كان على الأموال، أو على الصحة، أو على غير ذلك، فالعقود التأمينية محرمة، وإن فعلها الناس ففي هذا الغرر، والربا.","link":"https://binbaz.org.sa/fatwas/1601/حكم-التامين-على-الاموال-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_495.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6190,"question":"أفيد سماحتكم أنني مساهم في البنك الأمريكي، وهو يتعامل بالربا، وعندما علمت ذلك؛ سحبت بعض الأسهم التي تخصني، وفيها بعض النقود من سبب الربا؟","title":"كيفية التصرف بالأموال الربوية","answer":"الجواب: المساهمة في البنوك الربوية لا تجوز، المساهمة في البنوك لا تجوز؛ لأنها تعامل بالربا، والمساهمة فيها من باب التعاون على الإثم، والعدوان. وإذا جاءه ربح من سهمه؛ فينبغي له أن يتصدق بهذا الربح، ولا يجعله من ماله، بل يخرجه في وجوه البر، كمواساة بعض الفقراء، والمساكين، أو إصلاح دورات مياه، أو ما أشبه ذلك مما ينفع الناس، ولا يجعله من ماله.","link":"https://binbaz.org.sa/fatwas/1677/كيفية-التصرف-بالاموال-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_551.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6205,"question":"أفيد سماحتكم أنني مساهم في البنك الأمريكي، وهو يتعامل بالربا، وعندما علمت ذلك؛ سحبت بعض الأسهم التي تخصني، وفيها بعض النقود من سبب الربا؟","title":"كيفية التصرف بالأموال الربوية","answer":"الجواب: المساهمة في البنوك الربوية لا تجوز، المساهمة في البنوك لا تجوز؛ لأنها تعامل بالربا، والمساهمة فيها من باب التعاون على الإثم، والعدوان. وإذا جاءه ربح من سهمه؛ فينبغي له أن يتصدق بهذا الربح، ولا يجعله من ماله، بل يخرجه في وجوه البر، كمواساة بعض الفقراء، والمساكين، أو إصلاح دورات مياه، أو ما أشبه ذلك مما ينفع الناس، ولا يجعله من ماله.","link":"https://binbaz.org.sa/fatwas/1677/كيفية-التصرف-بالاموال-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_551.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6241,"question":"قرأت في صحيفة عربية مقالًا من ضمنه: إذا كانت الحكمة من الزنا عدم تضييع الأنساب، وعدم إفشاء العداوة، والبغضاء، وما إلى ذلك، فإذا كان هناك حبوبًا لمنع الحمل، ورضا من الطرفين، ولم يكن هناك أية مشكلة، فما المانع من الزنا؟! هذه مقالة قرأتها فما الرد عليها أثابكم الله؟","title":"هل يجوز الزنا إذا انتفت الحكمة من تحريمه؟","answer":"الجواب: الأصل فيما حرم الله أنه يجب اجتنابه، وما أوجب الله يجب التزامه، أما كونه يعلم الحكمة هذا نور على نور، وخير إلى خير، فما حرم الله؛ وجب تركه مطلقًا، ولو لم يعلم الحكمة، ولو علم أن الحكمة التي يعلمها منتفية في ذلك فإنه يجب أن يلتزم بما حرم الله عليه، كما يلتزم بما أوجب الله عليه، فالله حرم الزنا وقال: وَلَا تَقْرَبُوا الزِّنَا إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32] ولم يقل: إلا إذا كان ما تحمل، أو إذا كان كذا، أو كان كذا، بل حرمه، وقال: إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32].  فالزنا حرمه الله، ورتب عليه العذاب الأليم، ومضاعفة العذاب، والخلود في النار لما يترتب عليه من الشر الكثير، ووجود بعض النوادي التي يظن صاحبها أنه لا يترتب عليها ما هو معروف من عواقب الزنا، لا قيمة لها. فالاعتبار بتحريم ما حرم الله، سواء جاءت الأشياء المترتبة عليها، أو لم تحصل، فيجب الالتزام بما حرم الله، والبعد عما حرم الله، والحذر من ذلك، ولو فرضنا أن تلك الحكم التي نص عليها أهل العلم لا تأتي، ولا تقع لو فعل ما حرم الله عليه، نسأل الله العافية. فالواجب: الالتزام بترك ما حرم الله، وفعل ما أوجب الله مطلقًا، ولو ظن أنها لا تحمل، ولو ظن أنها تعاطت الحبوب، ولو ظن أنه ليس هناك أحد يكون بينه، وبينه شحناء، كل هذه ظنون لا وجه لها، والحكم لا يتعلق بها، الحكم يتعلق بالإيلاج بالتحريم، ووسائله، فيجب الحذر من الزنا، ووسائله مطلقًا، هذا هو الواجب بإجماع المسلمين، وبنص القرآن، ونص السنة.","link":"https://binbaz.org.sa/fatwas/1735/هل-يجوز-الزنا-اذا-انتفت-الحكمة-من-تحريمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_578.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6260,"question":"السؤال الأول:قد تفضل مشايخنا جزاهم الله خير الجزاء بالكلام عن اليتيم، وأهمية رعايته، والعناية به، ولكننا نرى -في هذا الوقت وفي عصرنا الحاضر- نجد اليتامى في بلاد المسلمين متروكين، مهملين، وخصوصًا في بلاد كلبنان، وفلسطين، حيث ترك اليتامى هناك، ولم يحتضنوا، بل إن دول الكفر هي التي احتضنتهم، وأخذت تربيهم على العقائد الباطلة، ولاسيما النصارى، فما هو موقف العلماء من ذلك، أفيدونا جزاكم الله خير الجزاء؟","title":"وجوب احتضان يتامى المسلمين وعدم تركهم للأعداء","answer":"الجواب: الواجب على أهل الإسلام أن يحتضنوا اليتامى من أبناء المسلمين، وأن يتولوهم، وأن يعطفوا عليهم، وأن لا يدعوهم للنصارى، ولا لغير النصارى من الكفرة، هذا هو الواجب. ولم يثبت عندي أن أيتام المسلمين في لبنان احتضنهم النصارى أن هذا إشاعة، ويقال عن بعض الدول: إنها نشرت هذا، لكن لم يثبت عندي هذا الشيء. والذي أعتقد أن الدول الإسلامية أخذت من ذلك ما يلزمها، وأنها عنيت بهذا الأمر، ولكني حتى الآن لم أعرف الحقيقة التي تولتها كل دولة، أو ماذا عملت؟ هذا يحتاج إلى مزيد عناية، وسؤال، واستفسار من الدول الإسلامية التي نرجو أنها عملت واجبها، ولاسيما دولة هذه البلاد، ودول الخليج الذين أنعم الله عليهم بالثروة، فإن الواجب عليهم أكبر برعاية أطفال المسلمين، وفي رعاية المستضعفين من المسلمين، ولا بدّ أن يكون لهذا -إن شاء الله- ما يسبب الحصول على المعلومات الكافية، الوافية عن هذا الشيء.","link":"https://binbaz.org.sa/fatwas/1771/وجوب-احتضان-يتامى-المسلمين-وعدم-تركهم-للاعداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_610.mp3","categories":["قضايا معاصرة"]},{"id":6269,"question":"السؤال الأول:قد تفضل مشايخنا جزاهم الله خير الجزاء بالكلام عن اليتيم، وأهمية رعايته، والعناية به، ولكننا نرى -في هذا الوقت وفي عصرنا الحاضر- نجد اليتامى في بلاد المسلمين متروكين، مهملين، وخصوصًا في بلاد كلبنان، وفلسطين، حيث ترك اليتامى هناك، ولم يحتضنوا، بل إن دول الكفر هي التي احتضنتهم، وأخذت تربيهم على العقائد الباطلة، ولاسيما النصارى، فما هو موقف العلماء من ذلك، أفيدونا جزاكم الله خير الجزاء؟","title":"وجوب احتضان يتامى المسلمين وعدم تركهم للأعداء","answer":"الجواب: الواجب على أهل الإسلام أن يحتضنوا اليتامى من أبناء المسلمين، وأن يتولوهم، وأن يعطفوا عليهم، وأن لا يدعوهم للنصارى، ولا لغير النصارى من الكفرة، هذا هو الواجب. ولم يثبت عندي أن أيتام المسلمين في لبنان احتضنهم النصارى أن هذا إشاعة، ويقال عن بعض الدول: إنها نشرت هذا، لكن لم يثبت عندي هذا الشيء. والذي أعتقد أن الدول الإسلامية أخذت من ذلك ما يلزمها، وأنها عنيت بهذا الأمر، ولكني حتى الآن لم أعرف الحقيقة التي تولتها كل دولة، أو ماذا عملت؟ هذا يحتاج إلى مزيد عناية، وسؤال، واستفسار من الدول الإسلامية التي نرجو أنها عملت واجبها، ولاسيما دولة هذه البلاد، ودول الخليج الذين أنعم الله عليهم بالثروة، فإن الواجب عليهم أكبر برعاية أطفال المسلمين، وفي رعاية المستضعفين من المسلمين، ولا بدّ أن يكون لهذا -إن شاء الله- ما يسبب الحصول على المعلومات الكافية، الوافية عن هذا الشيء.","link":"https://binbaz.org.sa/fatwas/1771/وجوب-احتضان-يتامى-المسلمين-وعدم-تركهم-للاعداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_610.mp3","categories":["قضايا معاصرة"]},{"id":6277,"question":"لي أخ صار عليه حادث، وهو يقود سيارته، وكان الخطأ منه حيث كان نعسانًا (نائم) وقد ذهب ضحية هذا الحادث أربعة أنفس، فهل عليه كفارة غير كفارة الدية، وما هي؟","title":"كفارة من قتل بسيارته وهو نعسان","answer":"الجواب: الذي أصاب الناس بسيارته ناعسٌ ولا صاحٍ عليه الدية، والكفارة، الذي صدم الناس حتى قتلهم، سواء بسرعته، أو بنعاسه، أو بقلة بصيرته، أو غير ذلك؛ فهو على كل حال ظالم، ويستحق أن يسوق الدية، وعليه كفارة عن كل نفس كفارة عتق رقبة، فإن عجز؛ صام شهرين متتابعين عن كل نفس، نسأل الله الهداية.","link":"https://binbaz.org.sa/fatwas/1797/كفارة-من-قتل-بسيارته-وهو-نعسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_636.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6335,"question":"لا يخفى عليكم أن البنوك الموجودة الآن ربوية، وتتعامل بالربا داخل المملكة، وخارجها، وقد جعل قسط من رأس مالها للمواطن مساهمة، وحسب علم بعض الناس أنها حلال، فعليكم أمام الله أن توضحوا ذلك لأجل أن يكون الناس على بينة من ذلك، وبما أن كل شخص يريد بضاعة من الخارج، لا ترد إلا عن طريق البنوك الموجودة، ولماذا لا تكون هناك بنوك إسلامية تتعامل هكذا؟","title":"البنوك الربوية وخطرها والتحذير منها","answer":"الجواب: البنوك الربوية كلها محرمة، ويجب أن لا يتعامل معها، بل يجب أن تهجر، وأن لا يتعامل معها لما في التعامل معها من التعاون على الإثم، والعدوان، وقد نشرنا هذا غير مرة في الصحف الأهلية، ونشر غيرنا ذلك، وبيان تحريم الربا فهو بحمد الله واضح في القرآن العظيم، والسنة المطهرة. ولا شك أن تحذيرنا عن الربا واجب، فعلى أهل العلم أن يحذروا من الربا دائمًا، ويبينوا للناس أنه من كبائر الذنوب، وأنه خطر عظيم، ومن أسباب العقوبات العامة، ظهور الربا، والزنا، والخمر، والغيبة، والنميمة، وعقوق الوالدين، وقطيعة الرحم، وأشباه ذلك من المعاصي كلها، من أسباب العقوبات العامة -نعوذ بالله- فيجب الحذر من ذلك، ويجب على كل مسلم أن يحذر من ذلك.  ونسأل الله أن يسهل إيجاد بنوك إسلامية قريبًا؛ فإن الدولة -وفقها الله- قد وعدت بهذا الشيء إيجاد بنوك إسلامية، ووجود مؤسسات إسلامية تغني عن البنوك الربوية، ونرجو أن يستهل هذا قريبًا -إن شاء الله- حتى يقضى على هذه البنوك الربوية، أو يهديهم الله، فيرجعون إلى الصواب.","link":"https://binbaz.org.sa/fatwas/1922/البنوك-الربوية-وخطرها-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_707.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6338,"question":"النفاق يقام على صاحبه الحد، أم لا؟","title":"حكم إقامة الحد على المنافق","answer":"الجواب: إذا ثبت أنه زنديق؛ يستتاب، فإن تاب وإلا قتل، وبعض أهل العلم يرى أنه يقتل مطلقًا، ولا يستتاب إذا ظهر أنه في الباطن مكذب جاحد للحق، ويتظاهر بالإسلام، فكثير من أهل العلم يرى أنه يقتل حدًا، كافرًا، وبعض أهل العلم يستتيبه، فإن تاب، واستقام على دين الله، ولم يظهر منه بعد ذلك ما يدل على النفاق؛ فلا بأس، وإلا قتل. لكن أعمال المنافقين الظاهرة هذه تسمى نفاقًا عمليًا، فإن النفاق نفاقان: اعتقادي، وهو المكذب لله، ورسوله في الباطن، فهذا كفره أكبر -نعوذ بالله- وهذا الذي قال الله فيه : إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] يعني هم في الدرك الأسفل من الكفار، تحت الكفار، نعوذ بالله.  أما النفاق الثاني: النفاق العملي، كونه يتكاسل في الصلاة، أو يكذب في بعض الأحيان، أو يخون الأمانة، هذا نفاق عملي -نعوذ بالله- وهو قد يكون وسيلة إلى النفاق الأكبر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1942/حكم-اقامة-الحد-على-المنافق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_729.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6341,"question":"يوجد صندوق توفير في شركة كهرباء الرياض المنطقة الوسطى، وهذا الصندوق يعيد المبالغ للمشتركين لمن أمضى خمس سنوات 50% ولمن أمضى عشر سنوات 100% ما حكم ذلك شرعًا؟","title":"حكم صندوق التوفير","answer":"الجواب: هذا من الربا، إذا كان يعطيهم أموالًا، وهم يعملون فيها، ويعطونه 50% مثل البنوك سواء سواء، صندوق التوفير مثل البنوك، أما إذا كان شيء بينهم، يعني جماعة اشتركوا فيما بينهم صندوق يضعون فيه مالاً بينهم؛ لحاجاتهم هم، ولحوادث تقع لهم، ونمى .. وكيل لهم ينميه لهم، هذا ما هو الربا، هذا لمصلحتهم هم. أما صندوق توفير يتولاه ناس، يأخذون أموال الناس، يعملون فيها، ويعطونه 50% أو 10% أو 100% بعد خمس سنين، أو بعد ثلاث، أو بعد عشر، فهذا من الربا، من جنس الربا، سواء.","link":"https://binbaz.org.sa/fatwas/1924/حكم-صندوق-التوفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_709.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6349,"question":"ما حكم إيداع المال بدون أخذ الفائدة عليه كأمانة، أو حساب جار في البنوك الموجودة حاليًا؛ علمًا أنها تتعامل بالربا، وإعطاء الفائدة؟","title":"حكم إيداع المال في البنوك الربوية دون أخذ الفائدة","answer":"الجواب: لا يجوز أن يعطوا مالاً يحفظونه عندهم؛ لأنهم يعاملون بالربا، وهذا إعانة لهم في الربا، لكن بعض أهل العلم يقول: إذا كان للضرورة، وليس عنده مكان يحفظ فيه ماله، ولم يجد من يحفظ ماله إلا من طريق هذه البنوك، فقد يجوز له للضرورة من دون فائدة، ولكن إذا اجتهد -إن شاء الله- وَجَدَ محلاً لماله، ولم يعطه هذه البنوك التي تستعين به على الربا، والشر، أما الفائدة فلا.","link":"https://binbaz.org.sa/fatwas/1925/حكم-ايداع-المال-في-البنوك-الربوية-دون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_710.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6359,"question":"يوجد صندوق توفير في شركة كهرباء الرياض المنطقة الوسطى، وهذا الصندوق يعيد المبالغ للمشتركين لمن أمضى خمس سنوات 50% ولمن أمضى عشر سنوات 100% ما حكم ذلك شرعًا؟","title":"حكم صندوق التوفير","answer":"الجواب: هذا من الربا، إذا كان يعطيهم أموالًا، وهم يعملون فيها، ويعطونه 50% مثل البنوك سواء سواء، صندوق التوفير مثل البنوك، أما إذا كان شيء بينهم، يعني جماعة اشتركوا فيما بينهم صندوق يضعون فيه مالاً بينهم؛ لحاجاتهم هم، ولحوادث تقع لهم، ونمى .. وكيل لهم ينميه لهم، هذا ما هو الربا، هذا لمصلحتهم هم. أما صندوق توفير يتولاه ناس، يأخذون أموال الناس، يعملون فيها، ويعطونه 50% أو 10% أو 100% بعد خمس سنين، أو بعد ثلاث، أو بعد عشر، فهذا من الربا، من جنس الربا، سواء.","link":"https://binbaz.org.sa/fatwas/1924/حكم-صندوق-التوفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_709.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6367,"question":"النفاق يقام على صاحبه الحد، أم لا؟","title":"حكم إقامة الحد على المنافق","answer":"الجواب: إذا ثبت أنه زنديق؛ يستتاب، فإن تاب وإلا قتل، وبعض أهل العلم يرى أنه يقتل مطلقًا، ولا يستتاب إذا ظهر أنه في الباطن مكذب جاحد للحق، ويتظاهر بالإسلام، فكثير من أهل العلم يرى أنه يقتل حدًا، كافرًا، وبعض أهل العلم يستتيبه، فإن تاب، واستقام على دين الله، ولم يظهر منه بعد ذلك ما يدل على النفاق؛ فلا بأس، وإلا قتل. لكن أعمال المنافقين الظاهرة هذه تسمى نفاقًا عمليًا، فإن النفاق نفاقان: اعتقادي، وهو المكذب لله، ورسوله في الباطن، فهذا كفره أكبر -نعوذ بالله- وهذا الذي قال الله فيه : إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] يعني هم في الدرك الأسفل من الكفار، تحت الكفار، نعوذ بالله.  أما النفاق الثاني: النفاق العملي، كونه يتكاسل في الصلاة، أو يكذب في بعض الأحيان، أو يخون الأمانة، هذا نفاق عملي -نعوذ بالله- وهو قد يكون وسيلة إلى النفاق الأكبر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1942/حكم-اقامة-الحد-على-المنافق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_729.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6401,"question":"وسؤال آخر مضمونه أن رجلًا زنا بامرأة، وحملت منه، ما الحكم في المولود إذا كان ولدًا، أو بنتًا، ثم عقد عليها بعد ذلك؟ وهل المولود ينادى بأبيه، وهل يرثه، أفيدونا جزاكم الله؟","title":"حكم انتساب ولد الزنا إلى الزاني بعد زواجه بالزانية","answer":"الجواب: نسأل الله العافية، إذا زنا بها فالولد ليس له، ولكن لها، ينسب إليها، ويقال: ابن فلانة، ولد فلانة، وينسب إلى عبدالله، أو عبدالرحمن ولا ينسب إلى الزاني؛ لأنه ليس بزوج، إنما هو تيس مستعار، خبيث، فعل المنكر؛ فلا ينسب إليه، بل ينسب إلى المرأة، أو تنسبه إلى عبدالله؛ لأن الناس كلهم عبيد الله، ولا يسمى إلى هذا الزاني أبداً، ونكاحه باطل إذا تزوجها وهي حامل، يكون نكاحه باطل. السؤال: الحمل منه هو؟ الجواب: لا ينسب إليه؛ لأن الحمل باطل، ليس منسوبًا إليه، ولكنه منسوب إلى المرأة، ماء فاسد لا ينسب إليه، بل ينسب إلى المرأة، فإذا وضعت الحمل، وتزوجها بعد ذلك بعد توبة منهما ينبغي أن يتوبا إلى الله  فلا بأس. السؤال: .......؟ الجواب: لا بدّ من الولي إذا كان ما لها ولي، فالسلطان يعني ولي الأمر في بلدها، أمير بلدها، أو قاضي بلدها إذا وجد، إذا كان ما لها ولي؛ يكون قاض البلد، أو أمير البلد يزوجها. السؤال: ........؟ الجواب: إذا كان ما لها ولي، لا أب، ولا أخ، ولا عم، ولا ابن عم.","link":"https://binbaz.org.sa/fatwas/1977/حكم-انتساب-ولد-الزنا-الى-الزاني-بعد-زواجه-بالزانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_764.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6425,"question":"السؤال الأول وهو ما يتصل بالموضوع: هل يجوز شراء الذهب الذي فيه خرز، حيث إنه يوجد الآن بكثرة في الأسواق؟","title":"حكم شراء الذهب إلى أجل","answer":"الجواب: يجوز شرائه لكن بغير الورق، أما بالورق لا بدّ يدًا بيد، لا يجوز النسيئة، يشتري الذهب الذي فيه خرز بالفضة، بالورق يدًا بيد، أو بفضة حقيقية يدًا بيد؛ لا بأس، أو بأموال أخرى يشتري سلعة ذهبية التي فيها خرز، فيها ماس، فيها لؤلؤ، يشتريها بسكر، بسيارة، بملابس، بأشياء أخرى غير الذهب، والفضة، والأوراق المعروفة بدلًا الفضة، والذهب.  أما إذا كان بهذا؛ لا بدّ أن يكون يدًا بيد، وإن كان بذهب؛ فلا بدّ من التماثل إن كانت السلعة فيها ذهب، لا بدّ أن يفرز الذهب، ويتماثل مع الذهب يدًا بيد، وإذا باعه بغير الذهب، بأوراق؛ فلا بأس، لكن يدًا بيد، ولا يقول: أعطنيها والدراهم أعطيك بعد حين، أو .. بعد حين لا، يدًا بيد.","link":"https://binbaz.org.sa/fatwas/2139/حكم-شراء-الذهب-الى-اجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_788.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6429,"question":"السؤال الأول وهو ما يتصل بالموضوع: هل يجوز شراء الذهب الذي فيه خرز، حيث إنه يوجد الآن بكثرة في الأسواق؟","title":"حكم شراء الذهب إلى أجل","answer":"الجواب: يجوز شرائه لكن بغير الورق، أما بالورق لا بدّ يدًا بيد، لا يجوز النسيئة، يشتري الذهب الذي فيه خرز بالفضة، بالورق يدًا بيد، أو بفضة حقيقية يدًا بيد؛ لا بأس، أو بأموال أخرى يشتري سلعة ذهبية التي فيها خرز، فيها ماس، فيها لؤلؤ، يشتريها بسكر، بسيارة، بملابس، بأشياء أخرى غير الذهب، والفضة، والأوراق المعروفة بدلًا الفضة، والذهب.  أما إذا كان بهذا؛ لا بدّ أن يكون يدًا بيد، وإن كان بذهب؛ فلا بدّ من التماثل إن كانت السلعة فيها ذهب، لا بدّ أن يفرز الذهب، ويتماثل مع الذهب يدًا بيد، وإذا باعه بغير الذهب، بأوراق؛ فلا بأس، لكن يدًا بيد، ولا يقول: أعطنيها والدراهم أعطيك بعد حين، أو .. بعد حين لا، يدًا بيد.","link":"https://binbaz.org.sa/fatwas/2139/حكم-شراء-الذهب-الى-اجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_788.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6440,"question":".. خارج بلادنا يسكنون مع عوائل نصرانية بحجة أنهم يكتسبون لغة منهم، ولكن في نفس الوقت يشربون معهم الخمر، ويأكلون معهم لحم الخنزير، ويتركون الصلاة، والصوم مدارة، ومجاراة لهم، إلى غير ذلك من تشويه سمعة الدين، وأهله، فيرجع وهو حرب على الإسلام والمسلمين فما هو رأي حكومتنا الرشيدة في ذلك؟","title":"حكم السكن مع العائلات النصرانية بحجة اكتساب اللغة الإنجليزية","answer":"الجواب: هذا تقدمت الإشارة إليه، هذا بعض ما تقدمت الإشارة إليه، وأن هذا لا يجوز، لا يجوز بعثهم بالكلية، فإذا بعثوا، ثم أذن لهم أن ينزلوا وسط الكفار، وفي بيوتهم؛ صار الأمر أخطر، هذا لا شك أنه ممنوع ... من أجل ابتعاث الطلبة للدراسة في الخارج، ولكن الواجب العناية بالتنفيذ، ومتابعة التنفيذ.  والذين يؤمرون بالسكنى بين العوائل، بحجة أنهم يفهمون اللغة، ويتسهل لهم فهم اللغة الإنجليزية مثلاً، هذا من دسائس الشيطان، ومن نزغات الشيطان، فإنه لينزغ بينهم وبين عوائلهم، كان هذا أقرب إلى الشر، وأعظم في الخطر، من الزنا، وشرب الخمور، وغيرها، وفساد العقيدة، وفساد الأخلاق، ولو كانوا بعيدين بمعايير اللغة، بعيدة عن الأسر، وعن النساء لكان أسلم. فنزول الطالب بين أسر الكفار، وفي بيوتهم، وينامون عندهم، هذا لا شك أنه منكر عظيم، وخطير، لا يجوز بقاؤه أبدًا، وعلى الدولة أن تمنع من هذا منعًا باتًا، وعلينا، وعلى بقية العلماء أن يجدوا في هذا الأمر، وأن ينصحوا ولاة الأمور؛ حتى لا يبقى لهذا أثر، وحتى يسلم المسلمون من شر هذه الفكرة الباطلة، وهذه الأشياء الباطلة.","link":"https://binbaz.org.sa/fatwas/2186/حكم-السكن-مع-العاىلات-النصرانية-بحجة-اكتساب-اللغة-الانجليزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_811.mp3","categories":["قضايا معاصرة"]},{"id":6453,"question":".. خارج بلادنا يسكنون مع عوائل نصرانية بحجة أنهم يكتسبون لغة منهم، ولكن في نفس الوقت يشربون معهم الخمر، ويأكلون معهم لحم الخنزير، ويتركون الصلاة، والصوم مدارة، ومجاراة لهم، إلى غير ذلك من تشويه سمعة الدين، وأهله، فيرجع وهو حرب على الإسلام والمسلمين فما هو رأي حكومتنا الرشيدة في ذلك؟","title":"حكم السكن مع العائلات النصرانية بحجة اكتساب اللغة الإنجليزية","answer":"الجواب: هذا تقدمت الإشارة إليه، هذا بعض ما تقدمت الإشارة إليه، وأن هذا لا يجوز، لا يجوز بعثهم بالكلية، فإذا بعثوا، ثم أذن لهم أن ينزلوا وسط الكفار، وفي بيوتهم؛ صار الأمر أخطر، هذا لا شك أنه ممنوع ... من أجل ابتعاث الطلبة للدراسة في الخارج، ولكن الواجب العناية بالتنفيذ، ومتابعة التنفيذ.  والذين يؤمرون بالسكنى بين العوائل، بحجة أنهم يفهمون اللغة، ويتسهل لهم فهم اللغة الإنجليزية مثلاً، هذا من دسائس الشيطان، ومن نزغات الشيطان، فإنه لينزغ بينهم وبين عوائلهم، كان هذا أقرب إلى الشر، وأعظم في الخطر، من الزنا، وشرب الخمور، وغيرها، وفساد العقيدة، وفساد الأخلاق، ولو كانوا بعيدين بمعايير اللغة، بعيدة عن الأسر، وعن النساء لكان أسلم. فنزول الطالب بين أسر الكفار، وفي بيوتهم، وينامون عندهم، هذا لا شك أنه منكر عظيم، وخطير، لا يجوز بقاؤه أبدًا، وعلى الدولة أن تمنع من هذا منعًا باتًا، وعلينا، وعلى بقية العلماء أن يجدوا في هذا الأمر، وأن ينصحوا ولاة الأمور؛ حتى لا يبقى لهذا أثر، وحتى يسلم المسلمون من شر هذه الفكرة الباطلة، وهذه الأشياء الباطلة.","link":"https://binbaz.org.sa/fatwas/2186/حكم-السكن-مع-العاىلات-النصرانية-بحجة-اكتساب-اللغة-الانجليزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_811.mp3","categories":["قضايا معاصرة"]},{"id":6519,"question":"ما حكم السفر للنزهة إلى بلاد الكفار، ومجالستهم في منازلهم، والاختلاط بينهم، وذلك مما نلاحظه في كل عام في فترة الصيف بالذات؟","title":"حكم السفر للنزهة في بلاد الكفار ومجالستهم","answer":"الجواب: السفر إلى بلاد المشركين من المحرمات، نص العلماء على تحريم السفر إلى بلاد أهل الشرك، وهذا هو الأصل، وقد نعى الله على الذين بقوا بين المشركين، وبين خطرهم، وعقابهم في النار، وأنهم ظالمو أنفسهم بإقامتهم بين المشركين، فليس للمؤمن أن يسافر إلى بلاد أهل الشرك، ويجب عليه الامتناع من ذلك، والبقاء بين إخوانه المسلمين، ومما ورد في هذا قوله ﷺ: أنا برئ من كل مسلم يقيم بين المشركين.  ويروى عنه -عليه السلام- أنه قال: من جامع المشرك، وسكن معه فهو مثله وفي الحديث الصحيح: لا يقبل الله من مشرك عملًا بعدما أسلم، أو يفارق المشركين يعني حتى يفارق المشركين، فالواجب عدم السفر إليهم، والإقامة بين أظهرهم لما فيه من الخطر العظيم؛ لأنه قد يستحسن أحوالهم، وقد تؤثر فيه بعض شبههم، قد يشاركهم في بعض المعاصي، فهو على خطر، وأعظم ذلك أن يستحسن دينهم، أو تنقدح في قلبه شبهة من شبههم، فيشك في دينه، ويرجع من ذلك كافرًا مرتدًا، نسأل الله العافية. فالأمر عظيم، فالواجب الحذر من ذلك، وعدم السفر إلى بلاد أهل الشرك، لا في وقت العطلة من الدراسة، ولا في غير ذلك، لا للنزهة، ولا لغيرها، اللهم إلا من كان لديه علم، وبصيرة ليدعو إلى الله، ويعلم الناس الخير، ويظهر دينه، فهذا لا بأس.","link":"https://binbaz.org.sa/fatwas/2244/حكم-السفر-للنزهة-في-بلاد-الكفار-ومجالستهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_865.mp3","categories":["قضايا معاصرة"]},{"id":6541,"question":"وآخر يسأل إذا سافرت في خط، ووجدت فيه العدو قاطعين الخط، وينهبون أموال الناس، هل أعطيهم مالي، أم أقاتلهم، وإذا قَتَلت، أو قُتِلت ما حكم الإسلام؟","title":"حكم مقاتلة قطاع الطرق","answer":"الجواب: ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال له رجل: يا رسول الله، يأتيني الرجل يريد مالي؟ قال: لا تعطه مالك، قال: فإن قاتلني؟ قال: قاتله. قال: فإن قتلته؟ قال: فهو في النار. قال: فإن قتلني؟ قال: فأنت شهيد هكذا أمره النبي ﷺ رواه مسلم في الصحيح.  فأنت بالخيار إن قاتلته إذا أبى إلا القتال؛ فلك أن تقاتله، ولا تعطه مالك، وإذا أردت أن تفدي نفسك بمالك، وأن تعطيه ما يكفيك قتاله؛ فلا بأس عليك، النفس أغلى من المال، لكن إن قاتلت؛ فلا بأس عليك، وإن قتلته؛ فهو في النار -نعوذ بالله - ودمه هدر، وإن قتلك فأنت شهيد؛ لأنك مظلوم، وإن عرفت أن تسكته بشيء من مالك، ثم ترفع أمره إلى ولاة الأمور بعد ذلك، هذا لا بأس به، ولا حرج فيه.  المعنى ليس بلازم لك أن تقاتل، فإن قاتلت؛ فلا حرج، وإن تركته وشره، وأعطيته بعض ما يرضيه؛ حتى تحفظ نفسك، ودمك؛ فلا بأس بذلك، ثم ترفع بأمره بعد ذلك.","link":"https://binbaz.org.sa/fatwas/2383/حكم-مقاتلة-قطاع-الطرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_916.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6558,"question":"هل شراء كيس أرز بسمتي بـ115 ريالًا بشرط أن تعطيه كيس أرز أبو بنت بـ95 ريالًا يجوز هذا التبادل؟","title":"حكم بيع الأرز بمثله متفاضلاً","answer":"الجواب: هذا لا يجوز بيع الرز بالرز إلا مثلًا بمثل، الرز بالرز، والحنطة بالحنطة، والشعير بالشعير، والتمر والملح، كل أنواع الحبوب هذه لا يجوز بيعها ببعض إلا يدًا بيد، مثلاً بمثل، يعني 100 كيلو بـ 100 كيلو، 100 صاع بـ 100 صاع، 50 صاع بـ 50 صاع يدًا بيد مثلاً بمثل، لا يزادد، ولا ينقص، أما بأكياس لا ما ينفع، أكياس تزيد، وتنقص، لا بد أن يكون مثلًا بمثل بالكيل، أو بالوزن، والكيل أحسن.","link":"https://binbaz.org.sa/fatwas/2424/حكم-بيع-الارز-بمثله-متفاضلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_951.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6564,"question":"رجل يتعامل في البنوك الربوية، وسألته لماذا تتعامل مع البنوك؛ فقال: أنا لا آخذ الفائدة الربوية؟","title":"حكم من يتعامل مع البنوك الربوية دون أخذ الفائدة","answer":"الجواب: الرسولﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: «هم سواء» فالتعاون مع من يأخذ الربا، ويعامل في الربا تعامل لا يجوز؛ لأن الله قال: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] فليس للمؤمن أن يتعاطى الربا في المعاملات.","link":"https://binbaz.org.sa/fatwas/2425/حكم-من-يتعامل-مع-البنوك-الربوية-دون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_952.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6567,"question":"ما حكم وضع الابن غير الشرعي -أي ابن الزنا- بالمجتمع المسلم؟ ولمن ينسب، ومن يكون وليه؟ وهل يولى القضاء إذا تأهل لذلك؟ وهل يزوج من المسلمة؟ وأين يدفن إذا مات؟ وهل يصلى عليه؟ ففي بعض المجتمعات يقتل الطفل عند الولادة، فما حكم من يفعل ذلك ؟","title":"أحكام ولد الزنا","answer":"الجواب:\n\nولد الزنا إذا كان من أم مسلمة؛ حكمه حكم أولاد المسلمين، يربيه المسلمون، ويحسنون إليه، وليس عليه من ذنب أمه، ولا ذنب من زنا بها شيء: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فالوزر عليهما، لا عليه، وإنما هو أمانة بين المسلمين، عليهم أن يربوه تربية إسلامية، وأن يحسنوا إليه حتى يشب، ويكبر، وإذا بلغ الحلم؛ حكمه حكم سائر المسلمين، وعلى الدولة أن تقوم بهذا الأمر، وأن تعنى بهذا الأمر؛ حتى تصون هؤلاء، وتحميهم من القتل، ومن الأذى.\n\nوأما كونه يقتل بعد الولادة، أو تسعى في قتله عند الولادة، هذا منكر عظيم، ولا يجوز، ومن فعل هذا جمع جريمتين، جريمة الزنا، وجريمة القتل بغير حق، نعوذ بالله. \n\nفالواجب: ألا يقتل، بل يحفظ، ويدع في دار الحضانة الإسلامية، أو إلى امرأة مسلمة تقوم بحاله، وتحضنه، وتحسن إليه، وتربيه، ويعلم مع أولاد المسلمين في بلاد المسلمين، ويوجه إلى الخير، ومتى استقام، وبلغ الحلم، وتخلق بأخلاق الأخيار؛ صح أن يكون داعية إلى الله، وأن يكون قاضيًا، وأن يكون أميرًا، وأن يكون زوجًا لبقية من يكافئه من المسلمين، فليس عليه ذنب، الذنب على غيره، إنما عليه الاستقامة إذا بلغ، عليه أن يستقيم على أمر الله، وأن يحذر محارم الله، ومتى صلح في نفسه، واستقام في نفسه؛ فحكمه حكم سائر المسلمين، له ما لهم، وعليه ما عليهم، وإذا مات صغيرًا؛ دفن في مقابر المسلمين، مادام من أم مسلمة، دفن في مقابر المسلمين، غسل، وصلي عليه كسائر أولاد المسلمين، ولا يجوز إهماله ولا إضاعته، ويسمى بالأسماء المناسبة: عبدالله، عبدالرحمن، عبدالملك، الأسماء التي تناسب، محمد، زيد، ما في بأس، محمد، زيد، أي اسم من الأسماء المناسبة، يقال: ابن عبدالله، ينسب إلى عبدالله إلى عبدالملك، كل الناس عبيد الله.\n\nالسؤال: .. يزوج من..؟\n\nالجواب: يزوج من المسلمين، المسلم إذا صلح؛ ما تضره أمه، ولا يضره من زنا بها .\n\nالسؤال: طيب إن كان هذا الشخص بأن الطفل هذا مات، وهو مجهول؟\n\nالجواب:  يدفن مع المسلمين، والحمد لله، والله يتولى حسابه.\n\nالسؤال: يتولى القضاء يا شيخ؟\n\nالجواب:  يتولى القضاء وغيره.","link":"https://binbaz.org.sa/fatwas/2415/احكام-ولد-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_942.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6590,"question":"هل شراء كيس أرز بسمتي بـ115 ريالًا بشرط أن تعطيه كيس أرز أبو بنت بـ95 ريالًا يجوز هذا التبادل؟","title":"حكم بيع الأرز بمثله متفاضلاً","answer":"الجواب: هذا لا يجوز بيع الرز بالرز إلا مثلًا بمثل، الرز بالرز، والحنطة بالحنطة، والشعير بالشعير، والتمر والملح، كل أنواع الحبوب هذه لا يجوز بيعها ببعض إلا يدًا بيد، مثلاً بمثل، يعني 100 كيلو بـ 100 كيلو، 100 صاع بـ 100 صاع، 50 صاع بـ 50 صاع يدًا بيد مثلاً بمثل، لا يزادد، ولا ينقص، أما بأكياس لا ما ينفع، أكياس تزيد، وتنقص، لا بد أن يكون مثلًا بمثل بالكيل، أو بالوزن، والكيل أحسن.","link":"https://binbaz.org.sa/fatwas/2424/حكم-بيع-الارز-بمثله-متفاضلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_951.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6623,"question":"كثيرًا ما نسمع عن الإضراب عن الطعام حتى الموت، ما حكم الإسلام في ذلك؟","title":"حكم الإضراب عن الطعام حتى الموت","answer":"الجواب: هذا الإضراب ما له أصل، هذا إعانة للأعداء على مقاصدهم الخبيثة، هذا النظام ما له أصل، وإذا كان يفضي إلى ضرر عليه، أو قتل نفسه؛ فهو لا يجوز، هذا الذي نعتقده في هذا، هذا أخذوه من أعداء الله، هذا لا نعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/2470/حكم-الاضراب-عن-الطعام-حتى-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_997.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6638,"question":"كثيرًا ما نسمع عن الإضراب عن الطعام حتى الموت، ما حكم الإسلام في ذلك؟","title":"حكم الإضراب عن الطعام حتى الموت","answer":"الجواب: هذا الإضراب ما له أصل، هذا إعانة للأعداء على مقاصدهم الخبيثة، هذا النظام ما له أصل، وإذا كان يفضي إلى ضرر عليه، أو قتل نفسه؛ فهو لا يجوز، هذا الذي نعتقده في هذا، هذا أخذوه من أعداء الله، هذا لا نعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/2470/حكم-الاضراب-عن-الطعام-حتى-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_997.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6664,"question":"هل يجوز استعمال التنويم المغناطيسي في اكتشاف سرقة مبلغ من المال في بلد لا تحكم بشريعة الله؟ وهل هو نوع من الشعوذة، أم أنه من العلم؟","title":"حكم استعمال التنويم المغناطيسي في اكتشاف السرقات","answer":"الجواب: هذا لا أدري عنه، لكن الذي يظهر لي -والله أعلم- والأقرب عندي: أنه لا يجوز هذا؛ لأن معناه إكراه له على الإقرار بغير حق، فليس من الشرع أن ينوم حتى يقر بغير اختياره، والشريعة جاءت بالستر على المسلمين، فلا ينبغي أن يستعمل هذا، لكن من ظهر منه الحق بإقراره الصريح، ما هو بالإكراه، أو بالبينة؛ نفذ فيه حكم الله، وأما إذا كان فيه إكراه أو .. التنويم المغناطيسي فهذا يشبه الإكراه، الذي يظهر لي -والله أعلم- أنه لا يجوز ..","link":"https://binbaz.org.sa/fatwas/2544/حكم-استعمال-التنويم-المغناطيسي-في-اكتشاف-السرقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1039.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6708,"question":"رجل الآن يسكن جنبي، وعنده ثمانية من الأطفال، والآن زوجته حامل، تقول: أريد أسقط هذا الجنين، هل هذا يجوز؟الشيخ: تقول ماذا؟الطالب: يقول: العيال الآن أنا عندي ثمانية مكفينا، والذي في بطنها ذا لازم أسقطه لأجلها؟","title":"حكم إسقاط الجنين","answer":"الجواب:  هذا يختلف، إن كان في الأربعين الأولى، وعليها ضرر؛ فلا بأس في الأربعين الأولى، أما بعد هذا لا يجوز. السؤال: إذا كان يعني يا شيخ شهر، شهرين؟ الجواب: لا شهر بس، الأربعين الأولى فقط.  السؤال: أربعين يومًا؟ الجواب: في حال النطفة، هذا يجوز عند الحاجة إلى ذلك بالطرق المباحة التي ما فيها مضرة، يعرفها الأطباء.","link":"https://binbaz.org.sa/fatwas/2589/حكم-اسقاط-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1085.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6714,"question":"شخص يسافر -إن شاء لله- إلى الخارج للدراسة، وسيضطر إلى لبس ما يلبسون في الخارج، وذلك تجنبًا للإحراج، والفتنة، فما رأي سماحتكم في ذلك؟","title":"خطورة الدراسة في بلاد الكفر","answer":"الجواب: الواجب عليه ألا يتشبه بأعداء الله أينما كان، ولا ينبغي له أن يدرس في الخارج، بل ينبغي له أن يدرس في الداخل، ولا يدرس في الخارج؛ لأن الخارج فيه فتنة، وخطر عظيم، فينبغي له أن يقتصر على دراسته في بلاده، وبين إخوانه المسلمين، حذرًا من الفتنة التي وقع فيها الكثير من الناس، فإذا اضطر إلى ذلك، ولم يتيسر له الدراسة في الداخل؛فليحافظ على دينه، وليحذر التشبه بأعداء الله في ملابسهم، أو غيرها.","link":"https://binbaz.org.sa/fatwas/2598/خطورة-الدراسة-في-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1094.mp3","categories":["قضايا معاصرة"]},{"id":6719,"question":"رجل الآن يسكن جنبي، وعنده ثمانية من الأطفال، والآن زوجته حامل، تقول: أريد أسقط هذا الجنين، هل هذا يجوز؟الشيخ: تقول ماذا؟الطالب: يقول: العيال الآن أنا عندي ثمانية مكفينا، والذي في بطنها ذا لازم أسقطه لأجلها؟","title":"حكم إسقاط الجنين","answer":"الجواب:  هذا يختلف، إن كان في الأربعين الأولى، وعليها ضرر؛ فلا بأس في الأربعين الأولى، أما بعد هذا لا يجوز. السؤال: إذا كان يعني يا شيخ شهر، شهرين؟ الجواب: لا شهر بس، الأربعين الأولى فقط.  السؤال: أربعين يومًا؟ الجواب: في حال النطفة، هذا يجوز عند الحاجة إلى ذلك بالطرق المباحة التي ما فيها مضرة، يعرفها الأطباء.","link":"https://binbaz.org.sa/fatwas/2589/حكم-اسقاط-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1085.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6757,"question":"ما حكم العمل في البنوك الربوية، وأخذ الراتب منهم، الآن كثير من الناس يعملون عندهم بجهل الحال، أو بعلم، أفتونا جزاكم الله خيرًا؟","title":"حرمة العمل في البنوك الربوية","answer":"الجواب: العمل في البنوك الربوية منكر، ولا يجوز، الرسول ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء العمل في البنوك في الربا، وفي غير البنوك، إذا كان في الربا؛ لا يجوز الربا، ولا المعاونة عليه، لا بكونه كاتبًا، ولا محاسبًا، ولا غير ذلك، -والله المستعان-.","link":"https://binbaz.org.sa/fatwas/2656/حرمة-العمل-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1152.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6760,"question":"ما حكم من يعرف حكم الله في جزئية من الإسلام، ولكنه يرتكب الحرام فيها، ويرفض حكم الله؟","title":"حكم من يرتكب ذنباً وهو يعلم حكم الله فيه","answer":"الشيخ: هذا حكمه حكم أهل المعاصي، فالناس يعرفون أن الزنا حرام، ويزنون، ويعرفون أن الخمر حرام، ويقعون في ..، فعلى من وقع في المعصية، وهو يعلم أنها معصية، عليه عقوبتها، وعليه خطرها، لكن إذا استحل إذا قال: الزنا حلال؛ يكون كافرًا -نعوذ بالله- وإذا قال: إن الخمر حلال؛ صار كافرًا، وإذا قال: إن اللواط حلال؛ صار كافرًا -نعوذ بالله- وإذا قال: إن السرقة حلال؛ صار كافرًا.  أما إذا فعل هذه المعاصي، ويعلم أنه عاصٍ، ويعلم أنه مخالف لأمر الله، ويعلم أنه على خطر؛ فله حكم العصاة، تحت مشيئة الله  وعلى الدولة المسلمة أن تقيم فيهم أمر الله، وتقيم عليه حد الله، ولا يكون كافرًا بذلك، إذا زنا لا يكون كافرًا إلا إذا استحل الزنا، وإن شرب الخمر ما يكون كافرًا إلا إذا استحل الخمر، وقال: إنه حلال. وهكذا إذا عق والديه لا يكون كافرًا، لكن إذا قال: يباح لي عقوق والدي؛ يكون كافرًا -نعوذ بالله- وإذا قال: يباح لي أن أفعل الزنا، وأن أشرب الخمر؛ صار كافرًا -نعوذ بالله-. فالحاصل: أن العصاة على قسمين: عصاة استحلوا المعاصي التي حرمها الله، ورأوها مباحة، فهؤلاء كفار إباحيون مع الكفرة، يجب أن يستتابوا، فإن تابوا، وإلا قتلوا من ولاة أمور المسلمين. القسم الثاني: عصاة يعرفون أنهم عصاة، ويعلمون أنهم عصاة، ولكن حملهم الشيطان، والنفس الأمارة بالسوء على تعاطي المعصية، فهؤلاء مثل ما قال الله -جل وعلا- تحت مشيئة الله: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] هو تحت مشيئة الله، إن شاء الله غفر له إذا مات على ذلك، وإن شاء عذبه على قدر الجريمة التي مات عليها، ثم بعدما يطهر في النار، ويعذب، بعد ذلك يدخل إلى الجنة بإسلامه الذي مات عليه، وتوحيده الذي مات عليه.","link":"https://binbaz.org.sa/fatwas/2667/حكم-من-يرتكب-ذنبا-وهو-يعلم-حكم-الله-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1164.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6798,"question":"نرجو التكرم بتعريف الحاضرين بمعنى الاستشراق، والمستشرقين، لأن كثيرًا منهم قد لا يفهم كلمة مستشرقين، جزاكم الله خير الجزاء؟","title":"معنى الاستشراق المستشرقين","answer":"الجواب: الاستشراق، والمستشرقين هؤلاء أناس من النصارى، ومن اليهود، ومن غيرهم من الكفرة، تعلموا لغة الشرق، تعلموا اللغة العربية، وكتبوا عن الإسلام، وعن الأديان، بعضهم قد ينصف، ويتكلم بالحق، وأغلبهم لا ينصف، ولا يتكلم بالحق، وبعضهم قد يتكلم بالحق في مواضع؛ ليغر الناس، ويدس الباطل، ويدس الشر في مواضع أخرى، من النصارى، واليهود وغيرهم لدخولهم إلى الشرق، وأخذهم لغة الشرق، ودراستهم آثار الشرق، وما كان عليه الشرق من دين، وهدى؛ حتى يخرجوهم عن دينهم، وحتى يشككوهم في دينهم، وحتى يدعوهم إلى الباطل، إلى النصرانية، والبعثية، واليهودية، والوثنية، وغير ذلك، وأقل شيء أن يشككوهم في دينهم، أقل شيء أن يجعلوهم شاكين في هذا الدين، ليس عندهم ثبات، وليس عندهم .. بسبب ما ألقوه في قلوبهم من الأفكار الفاسدة، والتشكيكات، والأعمال الخبيثة.","link":"https://binbaz.org.sa/fatwas/2682/معنى-الاستشراق-المستشرقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1179.mp3","categories":["قضايا معاصرة"]},{"id":6802,"question":"نرجو التكرم بتعريف الحاضرين بمعنى الاستشراق، والمستشرقين، لأن كثيرًا منهم قد لا يفهم كلمة مستشرقين، جزاكم الله خير الجزاء؟","title":"معنى الاستشراق المستشرقين","answer":"الجواب: الاستشراق، والمستشرقين هؤلاء أناس من النصارى، ومن اليهود، ومن غيرهم من الكفرة، تعلموا لغة الشرق، تعلموا اللغة العربية، وكتبوا عن الإسلام، وعن الأديان، بعضهم قد ينصف، ويتكلم بالحق، وأغلبهم لا ينصف، ولا يتكلم بالحق، وبعضهم قد يتكلم بالحق في مواضع؛ ليغر الناس، ويدس الباطل، ويدس الشر في مواضع أخرى، من النصارى، واليهود وغيرهم لدخولهم إلى الشرق، وأخذهم لغة الشرق، ودراستهم آثار الشرق، وما كان عليه الشرق من دين، وهدى؛ حتى يخرجوهم عن دينهم، وحتى يشككوهم في دينهم، وحتى يدعوهم إلى الباطل، إلى النصرانية، والبعثية، واليهودية، والوثنية، وغير ذلك، وأقل شيء أن يشككوهم في دينهم، أقل شيء أن يجعلوهم شاكين في هذا الدين، ليس عندهم ثبات، وليس عندهم .. بسبب ما ألقوه في قلوبهم من الأفكار الفاسدة، والتشكيكات، والأعمال الخبيثة.","link":"https://binbaz.org.sa/fatwas/2682/معنى-الاستشراق-المستشرقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1179.mp3","categories":["قضايا معاصرة"]},{"id":6815,"question":"طيب يا شيخ، غفر الله لك، بالنسبة للريال السعودي يساوي عشرين قرشًا، وهناك في السوق السوداء يشترونه بأربعين قرشًا، أو بخمسين قرشًا، ما الحكم في ذلك؟","title":"حكم الزيادة في الصرف","answer":"الجواب: إذا كان يدًا بيد؛ ما في بأس. السؤال: يعني المكسب هذا جائز؟ الجواب: إذا كان يدًا بيد؛ لأن الجنس غير الجنس، هذا ورق، وهذا معدن.","link":"https://binbaz.org.sa/fatwas/2700/حكم-الزيادة-في-الصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1199.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6817,"question":"ما حكم السفر إلى البلاد الإسلامية التي يكثر فيها الاختلاط بين الرجال، والنساء؟ وجزاكم الله عنا خير الجزاء.","title":"حكم السفر للبلاد الإسلامية التي فيها اختلاط بين الرجال والنساء","answer":"الجواب: لا يجوز السفر إلى بلاد الكفرة؛ لأن فيه من الشر العظيم ما لا يحصى، فلا يجوز السفر إلى بلاد المشركين، وقد نص العلماء على ذلك، والرسول -عليه الصلاة والسلام- يقول: أنا برئ من كل مسلم يقيم بين المشركين .. فالسفر إلى بلاد المشركين فيه أخطار عظيمة، اللهم إلا للضرورة القصوى، كعلاج المرض عند الضرورة، فهذا أجازه جماعة من أهل العلم للضرورة، مع الحذر، والبعد عن أسباب الشر، أو داعية إلى الله من أهل العلم، يدعون إلى الله، ويعلمون الناس الخير، وهو من أهل العلم والبصيرة، وممن لا يخاف الفتنة، فلا بأس إذا كان يعرف دينه، ويظهر دينه، ويدعو إلى الله.","link":"https://binbaz.org.sa/fatwas/2676/حكم-السفر-للبلاد-الاسلامية-التي-فيها-اختلاط-بين-الرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1173.mp3","categories":["قضايا معاصرة"]},{"id":6821,"question":"نرجو التكرم بتعريف الحاضرين بمعنى الاستشراق، والمستشرقين، لأن كثيرًا منهم قد لا يفهم كلمة مستشرقين، جزاكم الله خير الجزاء؟","title":"معنى الاستشراق المستشرقين","answer":"الجواب: الاستشراق، والمستشرقين هؤلاء أناس من النصارى، ومن اليهود، ومن غيرهم من الكفرة، تعلموا لغة الشرق، تعلموا اللغة العربية، وكتبوا عن الإسلام، وعن الأديان، بعضهم قد ينصف، ويتكلم بالحق، وأغلبهم لا ينصف، ولا يتكلم بالحق، وبعضهم قد يتكلم بالحق في مواضع؛ ليغر الناس، ويدس الباطل، ويدس الشر في مواضع أخرى، من النصارى، واليهود وغيرهم لدخولهم إلى الشرق، وأخذهم لغة الشرق، ودراستهم آثار الشرق، وما كان عليه الشرق من دين، وهدى؛ حتى يخرجوهم عن دينهم، وحتى يشككوهم في دينهم، وحتى يدعوهم إلى الباطل، إلى النصرانية، والبعثية، واليهودية، والوثنية، وغير ذلك، وأقل شيء أن يشككوهم في دينهم، أقل شيء أن يجعلوهم شاكين في هذا الدين، ليس عندهم ثبات، وليس عندهم .. بسبب ما ألقوه في قلوبهم من الأفكار الفاسدة، والتشكيكات، والأعمال الخبيثة.","link":"https://binbaz.org.sa/fatwas/2682/معنى-الاستشراق-المستشرقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1179.mp3","categories":["قضايا معاصرة"]},{"id":6887,"question":"هل يتغير القلب لو أزيل مثلًا بعملية جراحية، وبدل بقلب آخر في حالة الأمراض التي تحدث للقلب، وينتج عنها إجراء عملية بالقلب؟","title":"حكم استبدال قلب الإنسان بقلب آخر","answer":"الجواب: إجراء العملية للقلب من حيث التاريخ لم نعلم لها نجاحًا مستمرًا، وإنما سمعنا نجاحا مؤقتا في أوقات قليلة للعلاج.  أما إذا نجح القلب؛ حكمه حكم القلب الأصيل، إذا نجح، واستقر، وصار يعقل به، ويفهم به؛ صار هذا القلب الذي أبدل عن القلب الأول، وجعل فيه خصائصه، واتصلت به الشرايين، والأشياء التي كانت تمد القلب السابق، فإن حكمه حكم القلب السابق، ما دام يعقل به، ويفهم به، حكمه حكم العقل السابق، والقلب السابق، يكون مكلفًا في كل شيء.  أما إذا زال عقله؛ فإنه يزول تكليفه، ولكن فيما سمعنا الآن أن العلاج المتعلق بالقلب كل ذلك لم ينجح النجاح التام، وإنما هو نجاح مؤقت بأوقات محدودة.","link":"https://binbaz.org.sa/fatwas/2765/حكم-استبدال-قلب-الانسان-بقلب-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1257.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":6935,"question":"وضعت امرأة علاجًا مكونًا من حبوب في ثلاجة في بيتها، وتسلطت عليها طفلة، وأكلتها، وكانت سببًا في وفاتها في حينها، فهل على المرأة من شيء، مع أن هذا الأمر حدث منذ خمس سنوات؟","title":"حكم امرأة تناولت طفلتها دواءً فماتت بسببه","answer":"الجواب: الجواب -والله أعلم- إن كان المحل الذي وضعت فيه الحبوب في محل قريب في متناول الأطفال، قريب منهم، بحيث ما احتاطت، ولا أبعدته عنهم في محل رفيع؛ فالأظهر -والله أعلم- عليها الدية، والكفارة؛ لأنها جعلته في محل قريب من الأطفال، والأطفال كالبهائم. أما إذا كان في محل رفيع، وفي محل بعيد عن متناولهم؛ فالظاهر أنه ليس عليها شيء؛ لأن الطفل قد يتعبث، ويطلع على الأشياء، ويتناول أشياء بعيدة؛ فلا عليها شيء -إن شاء الله-. السؤال: ما عليها شيء؟ الجواب: ما عليها شيء إذا كان في محل مرتفع عن متناول الأطفال، وليس حولهم. السؤال: ما في عليها صيام يعني؟ الجواب: لا عليها صيام، ولا غيره.","link":"https://binbaz.org.sa/fatwas/2865/حكم-امراة-تناولت-طفلتها-دواء-فماتت-بسببه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1313.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":6950,"question":"تناقش الآن مشكلة في الضفة الغربية التي احتلها اليهود منذ 67، وهذه المشكلة هي: هل يجوز نهب أموال اليهود، وسرقتها، وأخذها بأي طريق كان؛ ذلك بأنهم أعداؤنا، والذين سرقوا أموالنا، وأرضنا، وسرقوا كرامتنا، أود أن أسمع رأي سماحتكم في هذا الموضوع، هل حصل في تاريخنا الإسلامي ما يشبه هذه المشكلة؟ علمًا بأن هناك من المشايخ من أفتى بجواز هذا الأمر، وآخرون أفتوا بعدمه؟","title":"حكم أخذ أموال الحربيين","answer":"الجواب: نعم نعم، لمن بينهم وبينهم الحرب أن يأخذوا أموالهم، وينهبوها، ويسرقوها؛ لأنهم حرب للمسلمين، وخصومهم. أما إن كان اليهود في بلد أدرك فيها الأمن، لا يحل أمانه إذا كان في بلد قد أمن فيها، في مصر، أو في أي مكان قد أمن فيها، لا يتعدى عليه حتى يخرج من بلاده، حتى يذهب عن بلادهم. أما من بينهم وبينهم الحرب، كالفلسطينيين؛ فإنهم لهم أن يأخذوا منهم ما شاؤوا، ولهم ما قدروا عليه، ويسرقون أولادهم، وبناتهم، وأموالهم، وغير ذلك.","link":"https://binbaz.org.sa/fatwas/2880/حكم-اخذ-اموال-الحربيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1328.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6952,"question":"هل يجوز أن يتبرع الشخص المسلم -حيًّا كان أو ميتًا- بأي عضو من أعضاء جسمه، سواء لشخص مثله محتاج لهذا العضو، مثل: الكلى لهيئة طيبة، أو مركز للأبحاث لعمل التجارب في جثته بعد وفاته، أو أن يهبها حرية التصرف في أعضائه بعد وفاته، يعني خدمة للطب؟","title":"حكم التبرع بعضو من الأعضاء حال الحياة أو الموت","answer":"الجواب: هذا فيه خلاف بين أهل العلم، التبرع بالكلية، ونحوها فيه خلاف بين أهل العلم، منهم من أجازه، ومنهم من منعه. أما كونه يتبرع بجثته لتشرح ما يجوز، ليس له أن يسمح بذلك، المسلم لا يشرح، إنما الخلاف في هل يجوز أن يسمح بكليته أن تؤخذ لغيره، أو قلبه يؤخذ لغيره عند وفاته؟  هذا محل النظر، وكثير من أهل العلم يمنعون من ذلك، ويقولون: ليس له التصرف في جسمه، فهو ملك لله، وليس ملك لنفسه، فليس له أن يتصرف بنفسه، وكليته، أو قلبه، أو كذا، أو كذا، وآخرون قالوا: إذا سمح بذلك في حياته؛ فلا بأس، وعندي في هذا توقف.. والكلام في هذا معروف عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/2882/حكم-التبرع-بعضو-من-الاعضاء-حال-الحياة-او-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1330.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":6977,"question":"ما حقيقة قول القائل بأن المسلمين في وضع حرج يرثى له، وأنهم متفرقون، ومتأخرون فيما بينهم، ومتناحرون، وأعداء الإسلام يتربصون بالمسلمين الدوائر، فلا داعي لإثارة، وزيادة فرقة المسلمين بذكر الخلافات العقائدية، وأمور البدع، فهم يقولون: لا داعي لدراسة العقيدة الآن؛ لأن هناك أمورًا أهم من دراسة العقيدة كتوحيد المسلمين ضد أعدائهم، راجين من سماحتكم أن تبينوا لنا معنى العقيدة على منهج السلف، وما هو تعريف العقيدة؟","title":"السبيل إلى جمع كلمة المسلمين","answer":"الجواب:\n\nجمع المسلمين إنما يكون على العقيدة، ما هو على التفرق، والبدع، جمع المسلمين يكون على توحيد الله، وطاعة الله، واتباع سنته، والشرك، والبدع هو الذي فرق الناس، والمعاصي هي التي فرقت الناس، فطريق اجتماع الناس هو أن يتفقوا على تحكيم شريعة الله، واتباع ما جاء به النبي ﷺ. \n\nفإن اتفقت الدول الإسلامية على اتباع الشريعة، وتحكيم ما جاء به الرسول ﷺ، والاستقامة على ذلك، والتعاون في هذا ضد الكفرة فهذا هو طريق السعادة، وهذا طريق الجمع.\n\nوالعقيدة الصحيحة هي التي درج عليها الرسول ﷺ وأصحابه، هي توحيد الله، والإيمان به، وبأسمائه، وصفاته، والاستقامة على دينه، وتنفيذ أوامره، وترك نواهيه، وتحكيم شريعته، والتحاكم إليها، ونبذ ما خالفها، هذا منهج أهل السنة، والجماعة، وهذا هو طريق الرسول ﷺ وأصحابه، وطريق أتباعهم بإحسان.\n\nفلما غير الناس تفرقوا، لما غير الناس هذا يحكم القانون الفرنسي، وهذا يحكم القانون الإفرنجي الأمريكي، وهذا يحكم كذا، وهذا يأمر بهذا، وهذا ينهى عن هذا، واختلفوا فيما بينهم، وصارت الشحناء، والعداوة، وصارت الدول متفرقة دولًا توالي كذا، ودولًا توالي كذا، وكل يخاف على سيادته، وعلى كذا، وعلى كذا، فمن أجل هذا صارت هذه الفرقة، ومع ما نشأ من الشرك، والبدع في كثير من الدول الإسلامية، وكثير من البلاد الإسلامية، هذه هي التي تسبب الفرقة.\n\nوإذا وفق الله الجميع، وتعاونوا على البر، والتقوى، وعلى تحكيم الشريعة، ودانوا بالحق الذي بعث الله به نبيه -عليه الصلاةوالسلام- واعتصموا بحبل الله جميعًا؛ صاروا بذلك أمة واحدة، واستقام أمرهم، وهابهم عدوهم، نسأل الله للجميع الهداية، نسأل الله أن يردهم للصواب، وأن يهدينا، وإياهم صراطه المستقيم.","link":"https://binbaz.org.sa/fatwas/2921/السبيل-الى-جمع-كلمة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1369.mp3","categories":["مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7077,"question":"هل يجوز إيداع المال في بنك ربوي، مثل البنك العربي الوطني؟ وما حكم ترك هذا البنك إذا كان يتعامل بالربا، وأنا لا أتعامل معه؟","title":"حكم إيداع الأموال في البنوك الربوية بدون أخذ الفائدة","answer":"الجواب:\n\nالأصل لا يجوز إيداع الأموال في البنوك الربوية، هذا هو الأصل؛ لأن في ذلك إعانة لها على أعمالها الخبيثة، لكن إذا اضطر إلى ذلك، وخاف على ماله؛ فإنه يودع بدون شرط الربا، يودع الوديعة فقط من دون شرط الربا.\n\nوإذا تيسر له أن يجعل صندوقًا في هذا البنك معه مفتاحه يحفظه عنده؛ هذا أسلم؛ حتى لا يعينهم على رباهم إذا تيسر هذا، هذا معمول كما بلغنا في بعض البنوك، يجعل صندوقًا خاصًا فيه ماله، يعطيهم إياه بأجر معلوم، على السنة، أو الشهر حتى يأخذ هذا الصندوق، هذا أطيب وأحسن، فإن لم يتيسر ذلك؛ جعله عندهم بدون ربا للضرورة فقط، أما إذا تيسر أن يودعه في محل غير ربوي؛ فهذا هو الواجب عليه.","link":"https://binbaz.org.sa/fatwas/3092/حكم-ايداع-الاموال-في-البنوك-الربوية-بدون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1471.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7088,"question":"بعض الناس يضعون أموالهم في البنوك خارج المملكة، وحيث إن هذه البنوك تعطي فوائد في كل الأحوال، فيرى بعض الناس أن أخذ هذه الفوائد، والتصدق بها للدول الإسلامية الفقيرة، كبناء مساجد، وبناء المستشفيات، والصدقة، بدلًا من تركها لهذه البنوك التي تقدمها لدول غير إسلامية، فما حكم ذلك؟","title":"حكم أخذ الفوائد الربوية لصرفها في وجوه البر","answer":"الجواب:\n\nأما الاتفاق على ذلك فلا يجوز، الاتفاق على الربا لا يجوز، ولو قال: تصدق بالزيادة، ما يجوز الاتفاق على الربا، ولا يجوز المعاملة بالربا، لكن لو أن إنسانًا فعل ذلك لقلة إيمانه، وضعف إيمانه، ثم هداه الله، يتصدق بهذه الأشياء لما قبضها، يتصدق بها في وجوه البر، وأعمال الخير، يتصدق على الفقراء في أفريقيا وغيرها، وفي المجاهدين، أو غير ذلك؛ لأنه مال ليس له أحد، فيصرف فيما ينفع المسلمين. \n\nأما أنه يتعامل معهم، وينوي هذه النية ما يجوز، ما يجوز التعامل بالربا ويقول: أنا أتصدق، أو أفعل كذا وكذا، مثل ما أنه لا يجوز أن يغش، أو يخون، ويقول: أتصدق بالزيادة، كل هذا لا يجوز، يجب عليه أن يتحرى الشرع، ويتمسك بالشرع، ولا يتعدى حدود الشرع، لكن لو أن إنسانًا دخل عليه مليون، أو مليونين بالربا، تساهل في ذلك، وغلبه الطمع، ثم هداه الله، هذه التي دخلت عليه بالربا يتصدق بها، ويعطيها أهل الجهاد، أو الأفارقة المحتاجين، أو غيرهم من المحاويج، أو يقضي بها دينًا عن المدانين، وضعفاء المساكين، أو يصلح بها دورات المياه للمحتاجين، أو ما أشبه ذلك من وجوه البر.","link":"https://binbaz.org.sa/fatwas/3095/حكم-اخذ-الفواىد-الربوية-لصرفها-في-وجوه-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1473.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7092,"question":"هناك فتوى بتحريم دفع زيادة على مقايضة الذهب القديم بالجديد، واعتبار ذلك ربا الفضل، ولكن هناك كلام من تجار الذهب مفاده: أنهم ينفقون أموالًا في طلاء الذهب القديم؛ حتى يصبح ناصعًا مثل الجديد، كما أنهم يبذلون جهدًا في تصنيعه، فكيف تفسير هذه الشبهة؟","title":"حكم بيع الذهب القديم بالجديد مع مبلغ من المال","answer":"الجواب:\n\nبكل حال، ما يجوز بيع الذهب الجديد بالذهب القديم، ولا الذهب الجديد بالجديد، ولا الذهب القديم بالقديم، كله ما يجوز إلا يدًا بيد مثلًا بمثل، سواء بسواء، لا بد أن يكون هذا مثل هذا، وزنًا بوزن، مثلًا بمثل.\n\n أما كون هذا أغلى، أو أنفس، أو هذا دون ذلك، ما يضر، النبي ﷺ ألغى هذا الفرق، قال: \"الذهب بالذهب ربًا، مثلًا بمثل، سواء بسواء يدًا بيد\" وهكذا الفضة مثلًا وسواء، ومعلوم أنها لا بد لها من خلط .. الفضة يمسكها ويقيمها، وقد يبتلى الذهب بشيء من الغش اليسير.\n\nفالحاصل: أن الذهب بالذهب مطلقًا، لا بد يكون مثلًا بمثل، سواء بسواء، يدًا بيد، فلا يباع هذا بهذا وزيادة، هو ربا أن يباع الجنيه بجنيه وزيادة درهم أو درهمين، لا، لا بد يباع هذا بهذا يدًا بيد، مثلًا بمثل، أو يباع بسلعة أخرى، كأن يباع الذهب بالفضة بالورق، يباع بالتمر بالرز، بالشاي، بالسكر ما يخالف، أما ذهب بذهب لا بد فيه من التساوي، والتقابض، وهكذا الفضة، وهكذا الرز. \n\nالسؤال: ...؟\n\nالجواب: يأخذ لا بأس، لكن مثلًا بمثل، سواء بسواء، إذا سمح صاحب الطيب أن يعطيه سواء بسواء، وإلا فليبيع بشيء آخر غير الذهب، بالفضة، بالورق، بالطعام، بالملابس، بالسيارات، بشيء آخر، يعني حتى لا يقع الربا.","link":"https://binbaz.org.sa/fatwas/3097/حكم-بيع-الذهب-القديم-بالجديد-مع-مبلغ-من-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1475.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7128,"question":"ما ترى في استبدال عشرة ريالات ورقية سعودية بأحد عشر ريالًا حديدًا سعوديًا من عملة هذا الزمان، هل هذا ربا؟","title":"حكم استبدال عشرة ريالات ورقية بأحد عشر ريالا معدنيا","answer":"الجواب:\n\nكثير من الإخوان يقول: إنه شيء واحد؛ لأنها كلها ريال، وعندي في هذا الشيء.. لأن العملة غير العملة، الحديد غير الورق، ولكن توقي هذا أحسن وأحوط، كونه يأخذ عشرة بعشرة، خمسة بخمسة، يكون هذا أحوط، وأسلم.","link":"https://binbaz.org.sa/fatwas/3154/حكم-استبدال-عشرة-ريالات-ورقية-باحد-عشر-ريالا-معدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1512.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7148,"question":"يقول: أودعت فلوسي في أحد البنوك منذ فترة طويلة، وعندما سحبت المبلغ قالوا لي: هذا لك أرباح حوالي خمسين ألف ريال، وأنا علمت أن هذا ربا، ولا يجوز لي، والآن أسأل عندنا بقريتنا حفيرة، أي جابية، وهي مورد لهذه القرية، يشربون منها، فهل يصح لي أن أضع هذا المبلغ فيها، نريد توسعتها وإدرار الماء، وكثرة الاستفادة؟","title":"صرف المال الربوي في مصالح المسلمين","answer":"الجواب:\n\nنعم إذا أخذت مثل هذا المبلغ، أو دخل على الإنسان مبلغ ليس بشرعي؛ فإنه يجعل في مصالح المسلمين، في وجوه الخير، مثل المغصوب التي غصبها ونسي أهلها وجهل أهلها، يتصدق بها على الفقراء، أو يجعلها في مصالح المسلمين، وتوسيع الحفرة، وجعل سور عليها هذا من مصالح المسلمين، وهكذا إطعام الفقراء، أو قضاء دين المدينين، أو تزويج المحتاجين، كل هذا من مصالح المسلمين، ولا تأكلها.","link":"https://binbaz.org.sa/fatwas/3177/صرف-المال-الربوي-في-مصالح-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1535.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7154,"question":"لا شك ولا ريب أن القول بتحريم تمثيل الصحابة قول وجيه، وكذا من هو من بعدهم، لكن ألا ترى أن تمثيل غير هؤلاء من أناس صالحين لعلها أن تغير من سلوك الناس، وتعتبر من وسائل الدعوة إلى الله، فما دام الأمر كذلك، فما حكمه، وقد ثبت علميًا تأثيره على المشاهدين؟","title":"حكم تمثيل أدوار الصحابة والعلماء والأئمة","answer":"الجواب:\n\nالتمثيل لا يجوز يا أخي، التمثيل كذب وزور، لا يجوز لا للصحابة، ولا لغير الصحابة، والذي كفى الأولين يكفي التالين، الذي كفى الأولين من هذه الأمة يكفي الآخرين، النصيحة والتوجيه من دون حاجة إلى التمثيل.\n\nفانصحوا الناس، والعلماء ينصحون ويوجهون هذا حلال، وهذا حرام، وهذا مما أمر الله به، وهذا مما نهى الله عنه، وهذه مفاسد كذا وهذه مصالح كذا بالبيان والإيضاح، يكفي البيان والإيضاح من دون حاجة إلى التمثيل.\n\nيحط نفسه فلانًا وفلانًا وفلانًا يكذب، يحط نفسه عمر وهو ليس بعمر، يحط نفسه شيخ الإسلام ابن تيمية، وهو ليس كذلك، يحط نفسه ابن عبدالسلام، وهو ليس كذلك، يحط نفسه الشافعي أو مالك، وليس كذلك، أو يحط نفسه أبا جهل، أو عتبة بن ربيعة، أو أبو لهب، يمثل نفسه بالكفرة كل هذا منكر.","link":"https://binbaz.org.sa/fatwas/3179/حكم-تمثيل-ادوار-الصحابة-والعلماء-والاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1537.mp3","categories":["قضايا معاصرة","مسائل متفرقة في العقيدة"]},{"id":7194,"question":"تجار الجملة يبيعون الذهب بالدين، ويسدد بأقساط، فمثلًا يشتري بائع الذهب المفرق بمائة ألف، أو أقل، أو أكثر، ويسددها أقساطًا، فهل في هذا إثم.. ذهب بذهب بفارق الصنعة؟","title":"حكم بيع الذهب بالدين مع التقسيط","answer":"الجواب: \n\nهذا لا يجوز، بيع الذهب، أو غيره من العٌمَل إلى أجل، لا يجوز هذا ربًا، فإذا باع ذهبًا بدولار، أو بجنيه استرليني، أو بدينار أردني، أو عراقي، أو غير ذلك، أو بالعملة السعودية نسيئة، أو مع التفرق من غير قبض، هذا هو الربا.\n\nالنبي  قال: الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح، مثلاً بمثل سواء بسواء يدًا بيد، فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم؛ إذا كان يدًا بيد إذا اختلفت لا بأس بالتفاضل، لكن يدًا بيد، فبيع الذهب بالدولار، أو بالفضة، أو بالدنانير، أو بالريال السعودي يدًا بيد لا بأس، أما نسيئة، أو في وقت آخر، يعني يقول له: أعطيك إياه بعدين؛ لا يصح، لا بد يدًا بيد.\n\nوهكذا بيع الذهب بالذهب أكثر، الذهب الجديد بالذهب القديم مع الفرق، هذا ما يجوز، لأن الذهب .. يكون مثلًا بمثل، سواء بسواء.\n\nولما اشترى رجل قلادة يوم خيبر، قلادة فيها ذهب وخرز؛ أنكر عليه النبي ﷺ وقال: لا تباع حتى تفصل يعني: لا تباع حتى يفصل الذهب لحاله، والخرز لحاله، وهذا الذي يفعله يقولون: هذا مقابل الصيغة، هذا غلط، الواجب أن يباع الذهب بعملة أخرى حتى لا يقع الربا، أما ذهب بذهب، ولو كان هذا أطيب، وهذا أردأ لا بد يكون مثلًا بمثل.\n\nولما اشترى بعض الصحابة الصاعين من التمر بثلاثة آصاع من التمر؛ أنكر عليه النبي ﷺ وقال: أوه -أي- عين الربا، مع أن الصاعين أفضل من الثلاثة؛ لأنه تمر طيب، لكن أنكر عليه النبي ﷺ قال: عين الربا لا تفعل، بع الجمع بالدراهم ثم اشتر بالدراهم جنيبًا يعني تمرًا طيبًا.","link":"https://binbaz.org.sa/fatwas/3252/حكم-بيع-الذهب-بالدين-مع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1585.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7196,"question":"بخصوص العمل في تحويل الأموال بواسطة المصارف من ريال، إلى جنيه سوداني هذا يؤثر في اقتصاد السودان، ما رأي سماحتكم، وما حكم ذلك؟","title":"حكم صرف العملة إلى عملة أخرى أثناء تحويلها","answer":"الجواب:\n\nما نعلم بأسًا في التحويل، إذا حول دولارات إلى السودان، أو إلى غير السودان، أو الجنيه الاسترليني، أو غير ذلك بالعملة التي يريد، والتي يرغب فيها، لكن يدًا بيد، لا بد يكون يدًا بيد، يقبض العملة التي يريد، ويحولها.\n\nوأجاز قوم هذا الشيك؛ لأنه قبض، هذا الشيك إذا كان على بنك فيه رصيد للشخص، فإن قبض الشيك قبض للمال؛ لأنه يقوم مقامه، ليس مثل الدين، يقوم مقامه؛ لأنه مال، أينما ذهب به؛ حصل المطلوب، لكن إذا تيسر أن يقبض ماله بنفسه ثم يحوله؛ يكون هذا أكمل.\n\nالسؤال: لا، هو يحول الجنيه السوداني إلى دولار، ويحتفظ بالدولار معه؛ ليبيعه في السودان، أو في مصر، يسموه السوق السوداء، بدون علم الحكومة؟\n\nالجواب: لكن لابد يقبضها.\n\nالطالب: هو يقبضها فعلًا، ولكن هذا يضر الاقتصاد السوداني، أو المصري في حالة تحويلة عن طريق غير البنك؟ \n\nالجواب: ما نعلم بأسًا في هذا.","link":"https://binbaz.org.sa/fatwas/3268/حكم-صرف-العملة-الى-عملة-اخرى-اثناء-تحويلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1596.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7262,"question":"ما هو حد الحرابة؟ ومن تاب قبل أن يقدر عليه في حد الحرابة هل يقام عليه الحد؟","title":"ما هو حد الحرابة وما حكم من تاب قبل أن يقدر عليه؟","answer":"الجواب: \n\nالحرابة من المنكرات العظيمة، وهي قطع الطريق، والخروج على الناس بالسلاح لأخذ أموالهم، هذه يقال لها: حرابة، يقال لهم: قطاع الطريق، ويقال لهم: المفسدون في الأرض. \n\nوهم يخرجون على الناس بالسلاح، بأنواع السلاح، ولو بالعصي في البلد، أو في الطرقات، والفلاوي الصحراء، يتعرضون لهم بالسلاح، أو بالعصي، أو بأيديهم على الصحيح، حتى ولو بأيديهم -إذا كان ما في أيديهم سلاح- ولو بأيديهم بالقوة، فيأخذون أموال الناس بالقوة.\n\nهؤلاء يقال لهم قطاع الطريق، وعلى ولي الأمر أن يعاملهم بما ذكره الله في كتابه في قوله سبحانه: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلَافٍ أَوْ يُنْفَوْا مِنَ الْأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ۝ إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيم  [المائدة:33، 34].\n\nهؤلاء هم قطاع الطريق، وهم أصحاب الحرابة، وعلى ولي الأمر أن يتابعهم بالقوة، وأن يجتهد في تتبع آثارهم، ومطاردتهم حتى يمسكهم، ويقضي عليهم بما شرع الله، حتى لا يفسدوا في الأرض، وحتى لا يخلوا بالأمن.\n\nالسؤال: الربا من الحرابة؟\n\nالجواب: حرب لله ورسوله، لكن ما هي من الحرابة المعروفة، تسمى حربًا لله ورسوله؛ لأنها معصية، وكبيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3329/ما-هو-حد-الحرابة-وما-حكم-من-تاب-قبل-ان-يقدر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1650.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7272,"question":"ما هو حد الحرابة؟ ومن تاب قبل أن يقدر عليه في حد الحرابة هل يقام عليه الحد؟","title":"ما هو حد الحرابة وما حكم من تاب قبل أن يقدر عليه؟","answer":"الجواب: \n\nالحرابة من المنكرات العظيمة، وهي قطع الطريق، والخروج على الناس بالسلاح لأخذ أموالهم، هذه يقال لها: حرابة، يقال لهم: قطاع الطريق، ويقال لهم: المفسدون في الأرض. \n\nوهم يخرجون على الناس بالسلاح، بأنواع السلاح، ولو بالعصي في البلد، أو في الطرقات، والفلاوي الصحراء، يتعرضون لهم بالسلاح، أو بالعصي، أو بأيديهم على الصحيح، حتى ولو بأيديهم -إذا كان ما في أيديهم سلاح- ولو بأيديهم بالقوة، فيأخذون أموال الناس بالقوة.\n\nهؤلاء يقال لهم قطاع الطريق، وعلى ولي الأمر أن يعاملهم بما ذكره الله في كتابه في قوله سبحانه: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلَافٍ أَوْ يُنْفَوْا مِنَ الْأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ۝ إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيم  [المائدة:33، 34].\n\nهؤلاء هم قطاع الطريق، وهم أصحاب الحرابة، وعلى ولي الأمر أن يتابعهم بالقوة، وأن يجتهد في تتبع آثارهم، ومطاردتهم حتى يمسكهم، ويقضي عليهم بما شرع الله، حتى لا يفسدوا في الأرض، وحتى لا يخلوا بالأمن.\n\nالسؤال: الربا من الحرابة؟\n\nالجواب: حرب لله ورسوله، لكن ما هي من الحرابة المعروفة، تسمى حربًا لله ورسوله؛ لأنها معصية، وكبيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3329/ما-هو-حد-الحرابة-وما-حكم-من-تاب-قبل-ان-يقدر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1650.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7283,"question":"لي والدة ولها طفل توفي منذ زمن قديم، وسبب الوفاة هو أنها كانت واضعة عليه الغطاء، أو اللحاف، وأنه من الصوف، ولقد توفيت هذه الطفلة إثر هذا اللحاف، علمًا بأنها لم تقصد هذا الفعل ولكن من جهلها بمثل هذه الأمور، والآن هل عليها كفارة أم لا؟","title":"غطت ولدها بلحاف فمات هل عليها الدية والكفارة؟","answer":"الجواب:\n\nنعم إذا وضعت على الطفل اللحاف الثقيل ومات بسبب ذلك؛ فإن هذا قتل، لكنه قتل خطأ لجهلها، فعليها الدية والكفارة، الدية إذا سمح عنها أبوه والورثة؛ فلا بأس. \n\nوأما الكفارة فعليها عتق رقبة مؤمنة، عبد أو أمة، فإن عجزت؛ تصوم شهرين متتابعين، ستين يومًا عن هذه المصيبة التي وقعت منها، نسأل الله أن يعينها، وأن يغفر لنا ولها وللمسلمين.\n\nالسؤال: الأم ما تحجب الورثة؟\n\nالجواب: على كل حال إذا كان أبوه موجودًا فهو الذي يرث، وإن كان له جدة ترث؛ لأن الأم لا ترث؛ لأنها قاتلة، وإن كان ما له أحد إلا بني عم، أو عصبة هم الورثة.","link":"https://binbaz.org.sa/fatwas/3343/غطت-ولدها-بلحاف-فمات-هل-عليها-الدية-والكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1664.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7309,"question":"ما حكم إسقاط الحمل في الشهر الثاني؟","title":"حكم إسقاط الحمل في الشهر الثاني فأكثر","answer":"الجواب: لا ينبغي اشتراط ذلك إلا من علة شرعية، أما في الأربعين الأولى فكثير من أهل العلم يتسامح في ذلك إذا كان لمصلحة، ما دام في الأربعين الأولى نطفة، أما إذا انتقل إلى الأربعين الثانية، إلى العلقة والمضغة؛ فالصواب أنه لا يجوز إلا من علة شرعية يخشى منها على الأم.","link":"https://binbaz.org.sa/fatwas/3382/حكم-اسقاط-الحمل-في-الشهر-الثاني-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1699.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7315,"question":"ما حكم إسقاط الحمل في الشهر الثاني؟","title":"حكم إسقاط الحمل في الشهر الثاني فأكثر","answer":"الجواب: لا ينبغي اشتراط ذلك إلا من علة شرعية، أما في الأربعين الأولى فكثير من أهل العلم يتسامح في ذلك إذا كان لمصلحة، ما دام في الأربعين الأولى نطفة، أما إذا انتقل إلى الأربعين الثانية، إلى العلقة والمضغة؛ فالصواب أنه لا يجوز إلا من علة شرعية يخشى منها على الأم.","link":"https://binbaz.org.sa/fatwas/3382/حكم-اسقاط-الحمل-في-الشهر-الثاني-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1699.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7321,"question":"باستقراء آيات الربا في القرآن الكريم يتبين أن صاحب رأس المال هو المستفيد، وهو صاحب المنفعة وحده، والفقير هو المتضرر، وهو المظلوم، أما المعاملات المصرفية الموجودة اليوم في البنوك فالمستفيد هو صاحب رأس المال الصغير والمنفعة متبادلة، فهو يختلف عن الربا، بل هو عكس الربا، فما رأي سماحتكم في هذا، ألا ترون فيه تيسيرًا للمسلمين، ودفعًا للحرج عنهم؟","title":"تحريم الربا ليس مرتبطا بمعرفة الحكمة","answer":"الجواب: لا هذا غلط، هذه مغالطة، فالمستفيد هذا وهذا، المقترض قد يستفيد يبني له عمارة، يتزوج، يقضي دينه، هو يصبر على الزيادة التي سموها الفائدة، والبنك يستفيد؛ لأنه يصرف هذه الأموال في جهات كثيرة، يصرفها في معاملات كثيرة، في شراء سلع، وفي صرف أموال بأموال، يستفيد. وآخذ القرض قد يستفيد أيضًا فيما اقترض لأجله، في شراء سيارة يستعملها، في تزوج، في عمارة، في قضاء دين عليه قد أشغله صاحبه، إلى غير ذلك، قد يستفيد هذا وهذا، فكل منهما مستفيد، وإن كان بعض أهل الدين قد يكون مضطرًا، قد يكون محتاجًا إلى الدين، وإلى الزيادة التي يسمونها الفائدة، لكن هو مستفيد، وذاك مستفيد، كلاهما مستفيد.  فالذي أعطى المال ويعطى الفائدة هو مستفيد، والبنوك مستفيدة فائدة أكثر؛ لأنها تتصرف تصرفات كثيرة بأموال عظيمة، ويحصل لها فوائد كثيرة، فهي أيضًا مستفيدة. والربا محرم، سواء استفاد هذا أو هذا أو كلاهما، علينا أن نلتزم ما قاله الله ورسوله، وأن نحذر ما حرم الله ورسوله، وأما مراعاة الحكمة وتحققها وعدمها فهذا شيء آخر، إذا تحققت فنور على نور، وإذا تحققت الحكمة أو لم تعرف الحكمة لم يضرك ذلك، والحكمة في هذا واضحة؛ لأنهم يتساهلون في هذه الأمور ما دام يرجو هذه الفائدة، فهو يعطي الأموال الكثيرة، يرجو هذه الفائدة، وقد ينزل الله بها بأسه، فتتلف عليه أمواله، وتنزل العقوبة بصاحب المال، فيفلس وتذهب الأموال الكثيرة هدرًا من غير فائدة لهذا الذي وضع المال؛ فيخسر هذا وهذا، نسأل الله العافية. ثم لو قدرنا أنه ربح ربحًا كثيرًا، وأنه أراد الربح؛ فليس هذا علة في الربا، بل هذا مما يحرم الربا، إذا كان المضطر يمنع من الربا وهو مضطر ومحتاج، فكيف بالذي هو متساهل يريد الزيادة، ويريد الفضل، ويريد التمتع بالزيادات وليس مضطرًا إليها؟! فهو أولى بأن يمنع من تعاطي الربا.","link":"https://binbaz.org.sa/fatwas/3397/تحريم-الربا-ليس-مرتبطا-بمعرفة-الحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1711.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7342,"question":"لي أخت ذهبت ذات يوم إلى المستشفى، وعند رجوعها من المستشفى رجعت وهي في عجلة من نفسها، فوضعت العلاج في مكان غير آمن، وكان لديها بنت صغيرة، فأكلت ذلك العلاج حتى أدى ذلك إلى وفاة البنت الصغيرة، نرجو من سماحتكم أن تقنعوها بما يرضي نفسها بحيث أنها تقول: قد اقترفت ذنبًا، أفتوني هل يعود عليها أي نوع من أنواع الحدود التي فرضها الله  أو كفارة ذلك الذنب الذي غير قصد منها وإلى آخره؟","title":"حكم الأم إذا كانت سبباً في قتل طفلها دون قصد","answer":"الجواب: نرجو ألا يكون عليها إثم؛ لأنها لم تتعمد قتلها، ولم تتعمد التسبب في ذلك، وإنما غفلت ونسيت الخطر، فجعلته في مكان غير مناسب في متناول الصبية والصبي الصغير، والذي يظهر من هذا أن عليها الدية والكفارة؛ لأنها مفرطة، جعلته في مكان قريب من الصغار الذين لا يعقلون، فالواجب عليها أن يكون في محل مرتفع، في محل بعيد عن متناول الصغار. أما الإثم فنرجو ألا يكون عليها إثم؛ لأنها لم تتعمد الشر، وإنما غفلت، أو نسيت، فجعلته في محل غير مناسب، ولكن عليها الدية والكفارة إلا إذا سمح الورثة عن الدية فلا بأس، أما الكفارة فهي عتق رقبة مؤمنة، فإن لم تجد؛ صامت شهرين متتابعين.","link":"https://binbaz.org.sa/fatwas/3426/حكم-الام-اذا-كانت-سببا-في-قتل-طفلها-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1735.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7352,"question":"لي قطعة أرض أحرثها، فذات يوم احتجت لمبلغ عشرة آلاف ريال لكي أسدد هذا المبلغ الذي علي، ثم رهنت الأرض بعشرة آلاف، وسجلت هذا المبلغ الذي علي، ثم إن هذه الأرض تبقى عند صاحبها يحرثها ويستثمرها جميع حصادها إلى أن أسدد له المبلغ، فهل في هذا ربا؟","title":"حكم استثمار المرهون حتى سداد القرض","answer":"الجواب: نعم، الربا كونه يأخذ الأرض يستثمرها، يستفيد منها بدون أجرة من أجل إمهالك في القرض، حتى تعطيه القرض، هذا ما يجوز، هذا ربًا، القرض ما يكون فيه زيادة، قرض مثلًا بمثل من دون زيادة، أما أن يشرط عليك أنه ينتفع بالأرض، ويستعملها حتى تؤدي إليه، فهذا مثل ما أقرضته ألفًا بألف ومائة، أو بألف ومائتين، هذا ربًا ما يجوز. السؤال: ...؟ الجواب: البيع شيء آخر، إذا اقترض المال وباعه الأرض إلى أجل معلوم ما هو متحيل، ما قصد التحيل حقيقة، ما هو تحيل على أنه يستثمرها ويعيدها إليه، بل حقيقة باعها عليه وجعل له خلال شهرين ثلاثة إن وجد المال وإلا الأرض له ما في بأس، أما إذا كان حيلة ما يجوز. السؤال: والذي يسمونه إقالة، يعني شبه بيع يوفي عليه الوقت المعلوم إن وفي فيها ونعمة وإلا حل عليها البيع؟ الجواب: لا، تكون له، الثمرة لصاحبها لأن هذا يتخذ حيلة، فالثمرة للبائع، لا للمشتري، حتى لا يتخذ حيلة.","link":"https://binbaz.org.sa/fatwas/3419/حكم-استثمار-المرهون-حتى-سداد-القرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1730.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7401,"question":"لقد كانت زوجتي حاملًا في شهرها الأخير، وفي إحدى الليالي حصل بيني وبين زوجتي خلاف وجدل في الكلام، ونتيجة ذلك أنها نامت على بطنها، في صباح اليوم التالي، كان لي موعد مع الدكتور، فأخبرني بموت الجنين علمًا بأن قصد زوجتي كان العناد فقط، ولم تكن تقصد موت الجنين، مع عدم علمي هل الجنين مات بسبب هذه الحركة، أم مات قبل ذلك؟","title":"موت الجنين بسبب نوم الأم على بطنها","answer":"الجواب: إذا قرر الطبيب المختص أن موت الجنين بسبب عنادها ونومها على بطنها؛ فعليها الدية، وعليها الكفارة؛ لأنها قاتلة، فعليها الدية وعليها الكفارة بما فعلت؛ لأنها متسببة في موته، أما إذا كان موته بأسباب أخرى؛ فلا حرج عليكما جميعًا، والواجب عليها السمع والطاعة لزوجها في المعروف، وعدم العناد، هذا الواجب على النساء السمع والطاعة في المعروف وعدم العناد، إلا إذا أمرها بمعصية فلا، إذا أمرها بالكشف لإخوانه، بعض الأزواج يقول اكشفي لإخواني ولأعمامي، لا تستري عنهم عنده دياثة، وعدم غيرة - نسأل الله العافية- هذا ليس لها طاعته في ذلك.  وهكذا إذا أمرها بالتبرج في الأسواق، أو عند الأجانب، كل هذا لا طاعة له، لا يجوز أن يطاع في ذلك، أو أمرها بشرب المسكر، أو بالعقوق لوالديها ليس له طاعة في ذلك -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3497/موت-الجنين-بسبب-نوم-الام-على-بطنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1801.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":7440,"question":"لقد عرفنا أن مهربي المخدرات يقتل، فنرجو من فضيلة الشيخ الدليل القاطع على هذا؛ ليكون حجة للدعاة إلى الله؟","title":"الدليل على قتل مهربي المخدرات","answer":"الجواب: قد قرر هيئة كبار العلماء حين درسوا أحكام المخدرات، وما حصل بها من الشر العظيم على المسلمين، والفساد الكبير، وضياع الكثير من الشباب وغيرهم بسبب تعاطيهم هذه المخدرات، وإصرارهم عليها، وإدامتهم لها، ونظروا في كلام أهل العلم، وتقرر من ذلك: أن الذي يهربها من هنا إلى هنا؛ يجب أن يقتل؛ لفساده في الأرض؛ لأنه من باب الفساد في الأرض، ولأنه أيضًا أشد من المحاربة، إذا كان المحارب الذي يأخذ أموال الناس في الطرقات يقتل، فهذا الذي يفسد عقول الناس أولى بالقتل.  أما الذي يروجها بالبيع والشراء؛ فهذا يؤدب، ويعزر بما يراه ولي الأمر من سجن وأدب، فإن ارتدع، وإلا وجب قتله؛ لأن قتله فيه حفظ لعقول المسلمين، وحفظ لحياتهم، فكان من رحمة الله للعباد: أن شرع التعزير بالقتل؛ لما لا يردعه الأدب بالجلد، والسجن، ونحو ذلك.  وهذا وجه ما صدر من الحكم في ذلك؛ لأنه من الفساد في الأرض؛ ولأنه أشد من المحاربة التي هي أخذ الأموال بغير حق، في الطرقات، وفي نحوها في البلاد بالقوة، فإذا كان الذي يأخذ أموال الناس، أو يخيف الطرق يقتل أو يصلب أو تقطع يده ورجله، فالذي يفسد عقول الناس، ويهرب ما يضر عقولهم، ويفسد عليهم دينهم ودنياهم أولى بهذه العقوبة -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3538/الدليل-على-قتل-مهربي-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1843.mp3","categories":["الجنايات والحدود","قضايا معاصرة"]},{"id":9051,"question":"نعود أيضًا في هذه الحلقة إلى رسالة أخينا (أ. ع. ج) من جمهورية مصر العربية، عرضنا من رسالته سؤالًا واحد في حلقة مضت وفي هذه الحلقة بقي له سبعة عشر سؤالًا، يسأل في هذا السؤال ويقول: ما هو مستقبل العالم الإسلامي من حيث القوة والضعف حسبما نظرت السنة الشريفة، وكذلك مستقبل أعداء الإسلام في هذه الحياة الدنيا؟","title":"مستقبل العالم الإسلامي ومستقبل أعداء الإسلام","answer":"فالحاصل أن الأصل أن الإسلام تشتد غربته عامًا بعد عام وقرنًا بعد قرن، لكن في الجملة هذا في الجملة كما قال جماعة من أهل العلم، وقد يأتي الله بزمان ينفس الله فيه عن المسلمين فيحصل فيه خير كثير، وتكون الحالة فيه أحسن من الزمن الذي قبله رحمة من الله جل وعلا، وقد يكون ذلك في جانب دون جانب، وفي إقليم دون إقليم، كما جرى في وقت الشيخ محمد بن عبدالوهاب وفي بلدان أخرى خرج فيها مصلحون صارت الحالة في بلادهم أحسن من الحالة التي قبلها وقتًا ما.\nوالله جل وعلا أخبرنا أن هذا الإسلام ينتهي في آخر الزمان، وأن هناك ريحًا تخرج يرسلها الله عز وجل يقبض بها أرواح المؤمنين والمؤمنات ثم يبقى الأشرار فعليهم تقوم الساعة، ففي آخر الزمان يقبض القرآن يرفع القرآن ويقبض المؤمنون والمؤمنات ويبقى الأشرار فعليهم تقوم الساعة.\nلكن في هذا العصر في أول هذا القرن وفي آخر القرن السابق حصل بحمد الله يقضة للمسلمين وحركة مباركة للمسلمين صار فيها المسلمون الآن أحسن من حالهم قبلها بأوقات بسبب الحركة الإسلامية من الشباب وغيرهم، بسبب كثرة الدعاة إلى الله والجمعيات الإسلامية والمراكز الإسلامية في شتى بقاع الأرض، وقد انتشر الدعاة من هنا وهناك من الجامعة الإسلامية ومن هذه الرئاسة الرئاسة العامة للبحوث العلمية والإفتاء والدعوة والإرشاد، ومن الرابطة، ومن جهات أخرى.\nفالحاصل أن هذا الوقت الآن يبشر بخير من حركة إسلامية قوية وتكاتف ودعوة إلى الله ونشاط، فنرجو أن يكون المستقبل القريب أحسن مما مضى بكثير، أما ما بعد ذلك فالله أعلم جل وعلا، والأدلة معروفة في هذا الباب.\nوأما مستقبل الكفرة فكذلك كلما نشط الإسلام ضعف جانب الكفر وكلما ضعف الإسلام نشط جانب الكفر، وأما تفصيل الأشياء وعلم نهاياتها فهذا إلى الله .\nلكن واجب على المسلمين أن يجتهدوا في نصر دين الله، والدعوة إلى الله، وأن يتعاونوا على البر والتقوى، وأن يحرصوا على جهاد الأعداء ونشر تعاليم الإسلام حتى يظهر دينهم، وحتى يقوى دينهم، وحتى يستعيدوا بعض ما سلبه الأعداء منهم، هذا واجب المسلمين وهذا الواجب على الدول الإسلامية أن تتقي الله، وأن تحكم شريعته سبحانه، وأن تجتهد في إصلاح أوضاع بلادها وإقامة حكم الله في بلادها وفي شعبها، هذا هو الواجب على جميع المسلمين.\nوقد سرنا ما سمعنا عن حكومة بنجلاديش من إعلانهم تحكيم الشريعة واجتماعهم على هذا الأمر، وهذا يبشر بخير كثير ونرجو أن يوفقهم الله لهذا الأمر وأن يعينهم على تحكيم الشريعة، وأن يوفق الباقين لهذا الأمر، وأن يقتدوا بغيرهم ممن سعى وبادر إلى تحكيم الشريعة، وهكذا حكومة الباكستان عندها عزم كبير على تحكيم الشريعة، فنسأل الله أن يعينها على ذلك.\nوهكذا نرجو لبقية الدول الإسلامية كحكومة مصر، وحكومة الأردن وغيرهما نسأل الله لهم العون والتوفيق حتى يحكموا شريعة الله، وحتى يدعو النظم المخالفة لشرع الله، هذا هو الواجب عليهم، وبذلك ينصرهم الله ويعينهم ويحسن لهم العاقبة ويجمع شملهم على الخير، والله المسئول سبحانه أن يوفق المسلمين جميعًا حكامًا ومحكومين، وقادة وشعوبًا لكل ما فيه رضاه وصلاح عباده، وأن يعينهم على تحكيم الشريعة والتمسك بها وترك ما يخالفها إنه سبحانه وتعالى سميع قريب.\nالمقدم: جزاكم الله خيرًا ونفع بعلمكم واستجاب لدعوتكم.","link":"https://binbaz.org.sa/fatwas/7200/مستقبل-العالم-الاسلامي-ومستقبل-اعداء-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17804.mp3","categories":["قضايا معاصرة"]},{"id":13920,"question":"السائلة (س. م. م) من جمهورية مصر العربية تقول في سؤالها: ما حكم استعمال وسائل تنظيم الأسرة التي نسمع عنها في وقتنا الحاضر؟ وهل في هذا مخالفة لما جاء في القرآن والسنة؟","title":"حكم استعمال وسائل تنظيم الأسرة","answer":"الجواب: هذا سؤال مجمل، تنظيم الأسرة هذا سؤال مجمل لابد من التفصيل، فإن كان المراد تنظيم الأسرة يعني تنظيم الحمل فهذا فيه تفصيل: إذا كان عليها مشقة كونها ترضع وتخشى الحمل ويضر الولد حملها فلا بأس بتعاطي ما يمنع الحمل حتى تكمل الرضاعة، أو كان عليها مضرة.. تقرير الأطباء أن عليها مضرة من الحمل المتوالي فلا مانع من تعاطي ما يمنع الحمل المتوالي إن كان تحمل بعد كل ثلاث سنين أو أربع سنين إذا كان عليها مضرة في الحمل المتوالي.\nالمقصود تنظيم الأسرة إذا كان لأمر شرعي فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12313/حكم-استعمال-وساىل-تنظيم-الاسرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54405.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":13999,"question":"المقدم مساعد سالم جار النبي المالكي يقول في رسالته: هل يجوز نقل الدم من الزوج إلى زوجته، وهل ينقل من شخص ثاني إلى ثاني ولو اختلفت دياناتهم مثل: من مسلم إلى شيوعي أو من شيوعي إلى مسلم ؟","title":"حكم نقل الدم بين الزوجين ومن الكافر إلى المسلم","answer":"الجواب: لا أرى حرجًا في نقل الدم إذا دعت الحاجة إليه، إذا قرر الأطباء الحاجة إليه وناسب دم هذا دم هذا فلا بأس، سواء كان من زوجة إلى زوجها أو من زوج إلى زوجته أو من كافر إلى مسلم أو من مسلم إلى كافر لا بأس بهذا، إلا أن يكون الكافر حربيًا تدعو الشرعية إلى قتله فلا ينقل له شيء، أما إذا كان الكافر ذميًا أو معاهدًا أو مستأمنًا فلا حرج.\nفالحاصل: أن نقل الدم لا يؤثر ما هو مثل الرضاع، الرضاع إذا تمت شروطه أثر وحصل به التحريم، أما نقل الدم فلا ليس مثل الرضاع، فلا بأس أن ينقل الدم من الزوج إلى الزوجة ومن الزوجة إلى الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/12423/حكم-نقل-الدم-بين-الزوجين-ومن-الكافر-الى-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54005.mp3","categories":["الطب والتداوي","قضايا المرأة","قضايا معاصرة"]},{"id":18698,"question":"أخونا له مسألة أخرى يقول فيها: ظهور الكتب لمؤلفين مستشرقين باللغة العربية قد أظهر خطرًا محدقًا بتفكيرنا الذي نشأ بقراءة كتب السلف الصالح، وإني أوضح ذلك قائلًا: إن أدباءنا وكتابنا ومؤرخينا ظلوا وما لبثوا يستعملون الألفاظ المبجلة لمن كتبوا عنهم، بينما نرى هؤلاء المستشرقين تحسهم وأنت تقرأ لهم أنهم يعتدلون في ذلك، أي: إنك ترى أنهم يكتبون بكل تدبر، ولا يلقون الكلمات جزافًا، أي أنهم يذكرون العيوب والحسنات، بينما الكاتب العربي حتى ولو أنه يكتب قصة أو شيئًا عن المسلمين تجد أنه يذكر الحسنات دون السقطات والمساوئ مما جعل القارئ غير واثق فيما يكتب هذا الكاتب العربي المسلم. أرجو التوجيه وتوضيح هذه المسألة، جزاكم الله خيرًا.","title":"كيفية التعامل مع المستشرقين وكتاباتهم","answer":"الجواب: لا شك أن الكتاب يتفاوتون، ولا ريب أن المترجمين للناس يتفاوتون، فمن الناس من يعتدل، ويذكر حسنات الرجل وأعماله الطيبة حتى يقتدى به، حتى يتأسى به في الخير، ويترك السيئات التي لا ينبغي ذكرها؛ لأنه لا ينبغي ذكر سيئات الأموات؛ لأنه غيبة، فلا ينبغي ذكر سيئاتهم، بل ينبغي ذكر أعمالهم الطيبة التي يقتدى بهم فيها. أما السيئات فينبغي دفنها، وعدم ذكرها؛ لأنها من الغيبة، والله -جل وعلا- يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] اللهم إلا أن يكون ذلك الرجل من أهل البدع، من أهل الكفر بالله، ممن يخشى أن يقتدى به في الباطل، فتذكر مساويه ليحذر، ولا يقتدى به في باطله، فيكون هذا من باب النصيحة للمسلمين، فإذا ذكر المترجم أو المؤرخ بعض عيوب الأموات التي يخشى أن يتأسى بهم فيها من البدع التي فعلوها أو الدعاية ضد الإسلام، أو ما أشبه ذلك، وبين هذا ليحذروا، وأن لا يقتدى بهم في الباطل فهذا حسن. أما السيئات التي بينه وبين الله التي دون الكفر، فينبغي ألا تذكر، وأن تترك؛ لأن ذلك من الغيبة، وأن تذكر حسناتهم العظيمة، وأعمالهم الطيبة التي يدعى لهم بسببها، ويتأسى بهم فيها، هكذا ينبغي للمؤرخ والمترجم للأموات، لكن من اشتهر بالشر والبدعة، ونحو ذلك تبين بدعته وشره الذي اشتهر به حتى لا يقتدى به، وحتى تعلم حاله، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17800/كيفية-التعامل-مع-المستشرقين-وكتاباتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92007.mp3","categories":["الطب والتداوي","قضايا معاصرة"]}]
